window.__D("text/zohar/c020",{"p":[[9520011748,"<p>תּוּ פָּתַח וְאָמַר. (קהלת ז׳:י״ט) הַחָכְמָה תָּעוֹז לֶחָכָם מֵעֲשָׂרָה שַׁלִּיטִים אֲשֶׁר הָיוּ בָּעִיר. הַחָכְמָה תָּעוֹז לֶחָכָם, דָּא מֹשֶׁה, כַּד סָלִיק לְטוּרָא דְּסִינַי לְקַבְּלָא אוֹרַיְיתָא, אִזְדַּעֲזָעוּ כָּל אִינּוּן רְקִיעִין, וְכָל אִינּוּן מַשִּׁרְיָין עִלָּאִין, וְאָמְרוּ קָמֵיהּ, מָארִיהּ דְּעָלְמָא, וּמַה כָּל טוּבָא, וְכָל חֶדְוָה דִּילָן, לָאו אִיהוּ אֶלָּא בְּאוֹרַיְיתָא, וְאַת בָּעֵי לְנַחְתָּא לָהּ בְּאַרְעָא. אִתְכְּנִישׁוּ עַל מֹשֶׁה לְאוֹקְדֵיהּ בְּנוּרָא, אִתְתָּקַּף מֹשֶׁה וְכוּ', כְּמָה דְּאוּקְמוּהָ חַבְרַיָּיא, דְּקוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ לְמֹשֶׁה וְכוּלֵי.</p>\n<p>אֲבָל הַחָכְמָה תָּעוֹז לֶחָכָם, כָּל מַאן דְּאִתְעַסָּק בְּאוֹרַיְיתָא, וְאִשְׁתָּדַּל בָּהּ לִשְׁמָהּ, אִתְתָּקַּף בָּהּ בְּאוֹרַיְיתָא, בְּשַׁעֲתָא דְּאִצְטְרִיךְ לְמֶהֱוֵי לֵיהּ תֻּקְפָּא וְחֵילָא, לְאַגָּנָא עָלֵיהּ בְּשַׁעֲתָא דְּאִצְטְרִיךְ. וְהַהוּא תֻּקְפָּא וְחֵילָא מֵאָן אֲתָר אִתְתָּקַּף. הָדָר וְאָמַר, מֵעֲשָׂרָה שַׁלִּיטִים. אִינּוּן (מ\"ט ע\"א) עֶשֶׂר אֲמִירָן דִּכְתִּיבִין בָּהּ בְּאוֹרַיְיתָא, דְּאִינּוּן שַׁלִּיטִין עִלָּאִין, דְּבַּר נָשׁ אִתְתָּקַּף בְּהוּא בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי כָּל רָזִין דְּעָלְמָא, וְכָל פִּקּוּדִין, וְכָל חָכְמְתָא דְּעֵילָּא וְתַתָּא, בְּהוּ תַּלְיָא, וּבְהוּ אִתְכְּלִיל כֹּלָּא, וְכֹלָּא אִיהוּ בְּאוֹרַיְיתָא. זַכָּאָה חוּלְקֵיהּ מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, לְמֶהֱוֵי מִתְתָּקַף בְּתֻּקְפָּא לְעָלְמָא דְּאָתֵי.</p>\n<p>עֲשָׂרָה שַׁלִּיטִין, עֶשֶׂר זִינֵי חָכְמְתָא אִינּוּן בָּהּ בְּאוֹרַיְיתָא, בְּעֶשֶׂר שְׁמָהָן גְּלִיפָן, וְאִתְכְּלִילוּ בִּשְׁמָא חַד, דְּעֶשְׂרִין וּתְרֵין אַתְוָון גְּלִיפִין, רָזִין דְּעָלְמָא דְּאָתֵי, בְּאִינּוּן זִיהֲרִין, דְּלָא שַׁלְטָא עֵינָא לְמֵחמֵי, וַאֲפִילּוּ בְּסָכְלְתָנוּ לְמִנְדַּע, וּלְאִסְתַּכְּלָא בְּהַהוּא עִדּוּנָא, וְכִסּוּפָא, דְּקוּדְשָׁא בְּרִיךְ הוּא אַחֲסִין לוֹן לְצַדִּיקַיָּיא לְעָלְמָא דְּאָתֵי. כְּמָה דְאַתְּ אָמֵר (ישעיהו ס״ד:ג׳) עַיִן לא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>"],[9520011749,"<p>פָּתוֹרָא דְּבַר נָשׁ, מְזַכֵּי לֵיהּ לְמֵיכַל עַל פָּתוֹרָא אָחֳרָא, בְּעִדּוּנָא דְּהַהוּא עָלְמָא, כְּמָה דְאַתְּ אָמֵר (שמואל ב ט׳:י״ג) כִּי עַל שֻׁלְחָן הַמֶּלֶךְ תָּמִיד הוּא אוֹכֵל. וְדָוִד מַלְכָּא הֲוָה אָמַר, (תהילים כ״ג:ה׳) תַּעֲרֹךְ לְפָנַי שֻׁלְחָן נֶגֶד צוֹרְרָי, וְדָא אִיהוּ אִתְסַדְּרוּתָא דְּפָתוֹרָא בְּהַהוּא עָלְמָא, דְּהָא כְּדֵין אִיהוּ עִדּוּנָא וְכִסּוּפָא, דְּנִשְׁמְתָא אִתְהֲנֵי בְּהוּ, בְּעָלְמָא דְּאָתֵי.</p>\n<p>וְכִי פָּתוֹרָא אִית לוֹן לְנִשְׁמָתִין בְּהַהוּא עָלְמָא. אִין. דְּהָא מְזוֹנָא וְסִפּוּקָא דְּעִדּוּנָא, אַכְלֵי בְּהַהוּא עָלְמָא, כְּגַוְונָא דְּמַלְאֲכֵי עִלָּאֵי אַכְלֵי. וְכִי מַלְאֲכֵי עִלָּאֵי אַכְלֵי. אִין. כְּגַוְונָא דִּלְהוֹן אָכְלוּ יִשְׂרָאֵל בְּמַדְבְּרָא. וְהַהוּא מְזוֹנָא, רָזָא אִיהוּ לְטַלָא, דְּנָגִיד וְאִתְמְשָׁךְ מֵעֵילָּא, מֵרָזָא דְּעָלְמָא דְּאָתֵי, וְאִיהוּ מְזוֹנָא דִּנְהִירוּ מְשַׁח רְבוּת קֻדְשָׁא, וְנִשְׁמָתֵהוֹן דְּצַדִּיקַיָּא אִתְּזָנוּ מִתַּמָּן בְּגִּנְתָּא דְּעֵדֶן, וְאִתְהֲנוּן תַּמָּן. דְּהָא תַּמָּן נִשְׁמָתְהוֹן דְּצַדִּיקַיָּא, מִתְלַבְּשָׁן בְּגִּנְתָּא דְּעֵדֶן דִּלְתַתָּא, כְּגַוְונָא דְּהַאי עָלְמָא.</p>\n<p>וּבְשַׁבָּתֵי וּבִזְמַנֵּי, מִתְפַּשְּׁטָאן, וְסַלְּקִין לְמֵחמֵי בִּיקָרָא דְּמָארֵיהוֹן, וּלְאִתְעַדְּנָא בְּעִדּוּנָא עִלָּאָה כְּדְקָא יֵאוֹת, דִּכְתִּיב, (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבֹא כָּל בָּשָׂר לְהִשְׁתַּחֲווֹת לְפָנַי אָמַר יְיָ'. וְכִי כָּל בָּשָׂר יֵיתֵי, לָאו הָכִי הֲוָה לֵיהּ לְמִכְתַּב, אֶלָּא כָּל רוּחַ אוֹ כָּל נְשָׁמָה, מַהוּ כָּל בָּשָׂר. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא עֲבַד לֵיהּ לְבַּר נָשׁ בְּהַאי עָלְמָא, כְּגַוְונָא דִּיְקָרָא דְּכָבוֹד עִלָּאָה לְעֵילָּא. הַהוּא כָּבוֹד עִלָּאָה, אִיהוּ רוּחַ לְרוּחַ, וְנִשְׁמְתָא לַנְשָׁמָה, <Nonei></i>עַד דְּמָטֵי לְחָד אֲתָר לְתַתָּא דְּאִקְרֵי גּוּף, וּבְהַאי עָיֵיל חַד רוּחַ דִּמְקוֹרָא דְּחַיִּים, דְּאִקְרֵי כֹּל, בְּדָא אִיהוּ כָּל טוּבָא, וְכָל מְזוֹנָא, וְכָל סִפּוּקָא, דְּהַהוּא גּוּף. וְרָזָא דָּא, (קהלתה) וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא (ס\"אמאי בכל היא) הַאי כָּל אִיהוּ רוּחַ לְהַהוּא גּוּף.</p>\n<p>כְּגַוְונָא דָּא בַּר נָשׁ בְּהַאי עָלְמָא, אִיהוּ גּוּף, וְרוּחַ דְּשַׁלְטָא בֵּיהּ, כְּגַוְונָא דְּהַהוּא רוּחַ עִלָּאָה, (ס\"א דשלטא על גופא דאקרי כל) דְּאִקְרֵי כֹּל, דְּשָלַט עַל גּוּפָא לְעֵילָּא, וְדָא הוּא דְּאִקְרֵי כָּל בָּשָׂר, וְעַל דָּא כְּתִיב, יָבֹא כָל בָּשָׂר לְהִשְׁתַּחֲווֹת לְפָנַי אָמַר יְיָ'. עַל הַהוּא עִדּוּנָא כְּתִיב, (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>\n<p>חֲדּוּ חַבְרַיָּיא בְּאָרְחָא. כַּד מָטוּ לְגוֹ טוּרָא חַד אָמַר רִבִּי חִיָּיא לְהַהוּא טַיְּיעָא, מָה שְׁמֶךָ. אָמַר לֵיהּ חָנָן. אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא יְחֹנִנְךָ, וְיִּשְׁמַע לְקוֹלֶךָ בְּשַׁעֲתָא דְּתִצְטְּרִיךְ לֵיהּ. אָמַר רַבִּי יוֹסִי, וַדַּאי הָא נָטֵי שִׁמְשָׁא, וְהָכִי בָּתַר טוּרָא דָּא, אִית כְּפַר חַד עַל שְׁמָךְ, דְּאִקְרֵי כְּפַר חָנָן, נָבִית תַּמָּן בְּגִין יְקָרָא דִּשְׁמָךְ. כַּד מָטוּ לְהָתָם, עָאלוּ לְבֵית אוּשְׁפִּיזַיְיהוּ, וְסִדְרוּ קָמַיְיהוּ פָּתוֹרָא, בְּכַמָּה זִינִין לְמֵיכַל. אָמַר רִבִּי חִיָּיא, וַדַּאי פָּתוֹרָא דָּא, כְּגַוְונָא דְּעָלְמָא דְּאָתֵי, וְאִית לָן לְסַלְּקָא הַאי פָּתוֹרָא, וּלְאַעְטְּרָא לֵיהּ בְּמִלִּין דְּאוֹרַיְיתָא.</p>"],[9520011750,"<p>פָּתַח רִבִּי יוֹסִי וְאָמַר, (דברים ח׳:י׳) וְאָכַלְתָּ וְשָבָעְתָּ וּבֵרַכְתָּ אֶת יְיָ' אֱלֹהֶיךָ עַל הָאָרֶץ הַטּוֹבָה אֲשֶׁר נָתַן לָךְ. אִי בְּאַרְעָא דְּיִשְׂרָאֵל מְבָרְכֵינָן, לְבַר מֵאַרְעָא מְנָלָן. דְּהָא בְּגַוְונָא דָּא לָא אִצְטְרִיךְ. אֶלָּא, קוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא, פָּלִיג אַרְעָא, יִשׁוּבָא אִיהוּ לִסְטַר חַד, וְחַרְבָּא אִיהוּ לִסְטַר אָחֳרָא. פָּלִיג יִשׁוּבָא, וְאַסְחַר עָלְמָא סַחֲרָנֵיהּ דִּנְקוּדָה חֲדָא. וּמַאן אִיהוּ, דָּא אַרְעָא קַדִּישָׁא, אַרְעָא קַדִּישָׁא אֶמְצָעִיתָא דְּעָלְמָא. וּבְאֶמְצָעִיתָא דְּאַרְעָא קַדִּישָׁא, אִיהוּ יְרוּשָׁלַ ם. אֶמְצָעִיתָא דִּיְרוּשָׁלַ ם אִיהוּ בֵּית קֹדֶשׁ הַקֳּדָשִׁים, וְכָל טִיבוּ וְכָל מְזוֹנָא דְּכָל יִשׁוּבָא, תַּמָּן נָחִית מִלְּעֵילָּא. וְלֵית לְּךָ אֲתָר בְּכָל יִשׁוּבָא דְּלָא אִתְּזַן מִתַּמָּן.</p>\n<p>פָּלִיג חַרְבָּא. וְלָא אִשְׁתְּכַח חַרְבָּא תַּקִּיפָא בְּכָל עָלְמָא, בַּר הַהוּא מִדְבָּר, דְּתַבְרוּ (קפ\"ד) חֵילֵיהּ וְתֻקְפֵּיהּ יִשְׂרָאֵל אַרְבָּעִים שָׁנָה, כְּמָה דְּאַתְּ אָמֵר (דברים ח׳:ט״ו) הַמּוֹלִיכֲךָ בַּמִּדְבָּר הַגָּדוֹל וְהַנּוֹרָא. בְּהַהוּא מַדְבְּרָא, שַׁלְטָא סִטְרָא אָחֳרָא, וּבָעַל כָּרְחֵיהּ אַזְלוּ יִשְׂרָאֵל עָלֵיהּ, וְתָבְרוּ חֵילֵיהּ, אַרְבְּעִין שְׁנִין. וְאִי יִשְׂרָאֵל יִשְׁתַּכְחוּ זַכָּאִין בְּאִינּוּן אַרְבְּעִין שְׁנִין, הֲוָה מִתְעַבְּרָא הַהוּא סִטְרָא אָחֳרָא מֵעָלְמָא, וּמִדְקָא אַרְגִּיזוּ לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כָּל אִינּוּן זִמְנִין, אִתְתָּקַּף הַהוּא סִטְרָא אָחֳרָא, וְנָפְלוּ כֻּלְּהוּ תַּמָּן תְּחוֹת רְשׁוּתֵיהּ.</p>\n<p>וְאִי תֵּימָא, וְהָא מֹשֶׁה דְּסָלִיק עַל כָּל בְּנֵי עָלְמָא, הֵיךְ מִית תַּמָּן. לָאו הָכִי, דְּהָא מֹשֶׁה מְהֵימָנָא לָא הֲוָה בִּרְשׁוּתֵיהּ, אֶלָּא בְּהַר הָעֲבָרִים. מַאי הָעֲבָרִים. פְּלוּגְתָּא. דְּאִתְפְּלָגוּ עָלֵיהּ שַׁלִיטִין עִלָּאִין דִּלְעֵילָּא, וְלָא אִתְמְסָר בִּידָא דִּמְמָנָא וְשַׁלִיטָא אָחֳרָא, וְאִשְׁתְּאָר הָכִי, עַד דְּאָתָא מֹשֶׁה עַבְדָּא מְהֵימָנָא, וְשָׁלִיט עָלֵיהּ, וְאִתְקְבָר תַּמָּן, וְלָא אִתְעַסָּק בֵּיהּ בִּקְבוּרָתֵיהּ, בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, דִּכְתִּיב, (דברים לה) וַיִקְבֹּר אוֹתוֹ בַגַּי.</p>\n<p>וַיִקְבֹּר אוֹתוֹ, מַאן. הַהוּא דִּכְתִּיב בֵּיהּ בְּאֹרַח סָתִים, (שמות כ״ד:ט״ז) וְאֶל (וירא ק\"ג ע\"ב) מֹשֶׁה אָמַר, וְלָא כְּתִיב מַאן אִיהוּ. וַיִּקְרָא אֶל מֹשֶׁה, וְלָא כְּתִיב מַאן אִיהוּ. אוּף הָכָא וַיִקְבּוֹר אוֹתוֹ, וְלָא כְּתִיב מַאן אִיהוּ, אֶלָּא וַדַּאי הַאי אֲתָר יְדִיעָא אִיהוּ לְגַבֵּי חַבְרַיָּיא. וְעַל דָּא, בְּהַהוּא טוּרָא לָא שַׁלִּיט עָלֵיהּ, בַּר מֹשֶׁה בִּלְחוֹדוֹי, וְאִיהוּ אִתְקְבַר תַּמָּן. וּבְגִין לְמִנְדַּע לְכָל דָּרִין אַחֲרָנִין דְּעָלְמָא, דְּאִינּוּן מְתֵי מִדְבָּר יְקוּמוּן, הַהוּא רַעְיָא דִּלְהוֹן אַשְׁרֵי לֵיהּ בְּגַּוַּויְיהוּ, לְמֶהֱוִי כֻּלְּהוּ בְּאִתְעָרוּתָא דְּקִיּוּמָא לְעָלְמָא דְּאָתֵי.</p>\n<p>וְאִי תֵּימָא, אִי הָכִי דְּהַהוּא מַדְבְּרָא אִיהוּ תֻּקְפָּא דְּסִטְרָא אָחֳרָא, הֵיךְ פָּקִיד קוּדְשָׁא בְּרִיךְ הוּא, עַל הַהוּא שָׂעִיר, לְשַׁדְּרָא לֵיהּ לְטוּרָא אָחֳרָא, דְּאִקְרֵי עֲזָאזֵל, הֲוָה לוֹן <Nonei></i>לְשַׁדְּרָא לֵיהּ לְהַהוּא טוּרָא דְּאַזְלֵי יִשְׂרָאֵל בְּמַדְבְּרָא בֵּיהּ. אֶלָּא, כֵּיוָן דְּהָא אָזְלוּ בֵּיהּ יִשְׂרָאֵל אַרְבְּעִין שְׁנִין, הָא אִתְּבַּר תֻּקְפֵּיהּ. וְתֻקְפֵּיהּ אִתְתָּקַּף בַּאֲתָר דְּלָא עָבַר בֵּיהּ גְּבָר תַּמָּן לְעָלְמִין, וּבְהַהוּא טוּרָא, הָא הֲוָה דִּיּוּרֵיהוֹן דְּיִשְׂרָאֵל תַּמָּן אַרְבְּעִין שְׁנִין.</p>\n<p>אֲבָל בְּהַאי שָׂעִיר, הַהוּא אֲתָר אִיהוּ טִנָרָא תַּקִּיפָא עִלָּאָה, וּתְחוֹת עָמְקָא דְּהַהוּא טִנָרָא, דְּבַר נָשׁ לָא (ס\"א לא יכיל למיעל תמן) עָיִיל תַּמָּן אִיהוּ שַׁלִּיט יַתִּיר לְמֵיכַל טַרְפֵיהּ, בְּגִין דְּיִתְעַבָּר מֵעַלַיְיהוּ דְּיִשְׂרָאֵל, וְלָא יִשְׁתְּכַּח בְּהוּ מְקַטְרְגָא עָלַיְיהוּ בְּיִשּׁוּבָא.</p>\n<p>שׁוּלְטָנוּתֵיהּ דְּרָזָא דִּמְהֵימְנוּתָא, גּוֹ אֶמְצָעִיתָא דִּנְקוּדָה דְּכָל (עלמא) אַרְעָא קַדִּישָׁא, בְּבֵי קֹדֶשׁ הַקָּדָשִׁים. וְאַף עַל גַּב דְּהַשְׁתָּא לָאו אִיהוּ בְּקִיּוּמָא, בִּזְכוּתֵיהּ כָּל עָלְמָא אִתְּזַן, וּמְזוֹנָא וְסִפּוּקָא מִתַּמָּן נָפְקָא לְכֹלָּא, בְּכָל אֲתָר סִטְרָא דִּישׁוּבָא. וּבְגִין כַּךְ, אַף עַל גַּב דְּיִשְׂרָאֵל הַשְׁתָּא לְבַר מֵאַרְעָא קַדִּישָׁא, עִם כָּל דָּא מֵחֵילָא וּזְכוּתָא דְּאַרְעָא, אִשְׁתְּכַח מְזוֹנָא וְסִפּוּקָא לְכָל עָלְמָא. וְעַל דָּא כְּתִיב (דברים ח׳:י׳) וּבֵרַכְתָּ אֶת יְיָ' אֱלֹהֶיךָ עַל הָאָרֶץ הַטּוֹבָה אֲשֶׁר נָתַן לָךְ. עַל הָאָרֶץ הַטּוֹבָה וַדַּאי, דְּהָא בְּגִינָהּ מְזוֹנָא וְסִפּוּקָא אִשְׁתְּכַח בְּעָלְמָא.</p>\n<p>מַאן דְּאִתְעֲדָּן עַל פָּתוֹרֵיהּ וּמִתְעַנַּג בְּאִינּוּן מֵיכְלִין, אִית לֵיהּ לְאַדְכְּרָא וּלְדָאֲגָא עַל קְדוּשָּׁה דְּאַרְעָא קַדִּישָׁא, וְעַל הֵיכָלָא דְּמַלְכָּא דְּקָא אִתְחֲרִיב. וּבְגִין הַהוּא עֲצִיבוּ דְּאִיהוּ קָא מִתְעֲצַב עַל פָּתוֹרֵיהּ, בְּהַהוּא חֶדְוָה וּמִשְׁתְּיָּא דְּתַמָּן, קוּדְשָׁא בְּרִיךְ הוּא חָשִׁיב עָלֵיהּ כְּאִלּוּ בְּנָה בֵּיתֵיהּ, וּבָנָה כָּל אִינּוּן חַרְבֵּי דְּבֵי מַקְדְּשָׁא, זַכָּאָה חוּלָקֵיהּ.</p>"],[9520011751,"<p>כּוֹס שֶׁל בְּרָכָה, לָא הֲוֵי אֶלָּא בִּתְלָתָא. בְּגִין דְּהָא מֵרָזָא דִּתְלַת אֲבָהָן קָא מִתְבָּרְכָא, וְעַל דָּא לָא אִצְטְרִיךְ כּוֹס אֶלָּא בִּתְלָתָא. כּוֹס שֶׁל בְּרָכָה אִצְטְרִיךְ לְמֵיהַב לֵיהּ בִּימִינָא וּבִשְׂמָאלָא, וּלְקַבְּלָא לֵיהּ בֵּין תַּרְוַויְיהוּ, בְּגִין דְּאִתְיְהִיב בֵּין יְמִינָא וּשְׂמָאלָא. וּלְבָתַר יִּשְׁתְּבִיק לֵיהּ בִּימִינָא, דְּהָא מִתַּמָּן אִתְבָּרְכָא.</p>\n<p>עֲשָׂרָה דְּבָרִים נְאֶמְרוּ בְּכוֹס שֶׁל בְּרָכָה, וְכֻלְּהוּ הֲווֹ כַּדְקָא יֵאוֹת, בְּגִין דְּתִקּוּנֵי דְּכוֹס שֶׁל בְּרָכָה עֲשָׂרָה אִינּוּן, וְהָא אוּקְמוּהָ חַבְרַיָּא. כּוֹס שֶׁל בְּרָכָה אִצְטְרִיךְ לְאַשְׁגָּחָא בֵּיהּ בְּעֵינָא, בְּגִין דִּכְתִּיב, (דברים י״א:י״ב) עֵינֵי יְיָ' אֱלהֶיךָ בָּהּ, וְלָא אִצְטְרִיךְ לְאִתְנָשֵׁי מֵעֵינָא, אֶלָּא לְאַשְׁגָּחָא בֵּיהּ.</p>\n<p>כּוֹס שֶׁל בְּרָכָה, אִתְבְּרַךְ בְּהַהוּא בִּרְכְתָא, דְּקָא מְבָרֵךְ בַּר נָשׁ עָלֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין (כך) דְּאִיהוּ רָזָא דִּמְהֵימְנוּתָא, וְאִצְטְרִיךְ לְנַטְרָא לֵיהּ בִּנְטִירוּ עִלָּאָה, כְּמַאן דְּאִיהוּ חַשִׁיבוּתָא דְּמַלְכָּא, דְּהָא בְּגִינֵיהּ, אִתְבְּרַךְ פָּתוֹרֵיהּ, בְּשַׁעֲתָא דְּבִרְכָּתָא מְזוֹנָא, דְּהַהוּא בַּר נָשׁ מְבָרֵךְ.</p>\n<p>פָּתוֹרֵיהּ אִצְטְרִיךְ דְּלָא יְהֵא בְּרֵיקָנַיָּא, דְּהָא לֵית בִּרְכְתָא מִשְׁתַּכְּחָא עַל פָּתוֹרָא רֵיקָנַיָּא, כְּמָה דְּאוּקְמוּהָ, דִּכְתִּיב, (מלכים ב ד׳:ב׳) הַגִּידִי לִי מַה יֶשׁ לָכְי בַּבָּיִת וְגוֹ'. וְעַל דָּא פָּתוֹרָא לָא אִצְטְרִיךְ לְאִתְחֲזָאָה בְּרֵיקָנַיָּא, דְּהָא בִּרְכָּאן עִלָּאִין לָא שַׁרְיָין, אֶלָּא בַּאֲתָר שְׁלִים. וְרָזָא דָּא (שמות ל״א:ו׳) וּבְלֵב כָּל חָכָם לֵב נָתַתִּי חָכְמָה, וּכְתִיב (דניאלב) יָהֵב חָכְמְתָא לְחַכִּימִין. וְעַל רָזָא דְּנָא שֻׁלְחָן דְּלֶחֶם הַפָּנִים, דִּכְתִּיב, (שמות כ״ה:ל׳) וְנָתַתָּ עַל הַשֻׁלְחָן לֶחֶם פָּנִים לְפָנַי תָּמִיד.</p>"],[9520011752,"<p><Noneb>רעיא מהימנא</b> תַּנָאִין וְאָמוֹרָאִין אִתְכְּנָשׁוּ כֻּלְכוּ, דְּהָא קָא מָטוּ שַׁעֲתָא, לְתַקְּנָא בֵּיהּ מָאנֵי מַלְכָּא, (ס\"א לאזהרא ולאתתקנא) לְאַנְהָרָא לְאִתְתַּקְנָא קָמֵיהּ, דְּאִינּוּן: מַשְׁכְּנָא, מְנַרְתָּא, פָּתוֹרָא, מַדְבְּחָא, כִּיוֹר, וְכַנוֹ, אֲרוֹן, וְכַפּוֹרֶת, וּכְרוּבִים, וְכֹלָּא בְּשֶׁקֶל. וּבְגִין דָּא מָנֵּי לְיִשְׂרָאֵל, זֶה יִתְּנוּ.</p>\n<p>קָם תָּנָא חֲדָא וְאָמַר, (ודאי) רַעְיָא מְהֵימָנָא וַדַּאי הָכִי הוּא, וְלָךְ מָנֵּי לְמֶעְבַּד כֻּלְּהוּ, הֲדָא הוּא דִּכְתִּיב, וְעָשִׂיתָ מְנוֹרָה. וְעָשִׂיתָ שֻׁלְחָן. וְהָכִי בְּכֹלָּא, וּרְאֵה וַעֲשֵׂה, וּמִכֹּלָּא לָא אִתְקָשֵׁי לְךָ לְמֶעְבַּד, אֶלָּא תְּלַת מִלִּין דִּרְשִׁימִין בְּאַתְוָון דִּשְׁמֶךָ, מְ\"נוֹרָה, שְׁ\"קָלִים, הַ\"חֹדֶשׁ. אֲמַאי אִתְקָשֵּׁי לָךְ.</p>\n<p>אֲמַר לֵיהּ, סָבָא סָבָא, אַתוּן מְפִיקִין <Nonei></i>קוּשְׁיָא דָּא דְּאִתְקָשֵׁי לִי, מִן מִקְשָׁה תֵּיעָשֶׂה הַמְּנוֹרָה. וַדַּאי מָאנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אִיהִי שְׁכִינְתָּא, דְּאִיהִי מָאנָא לְשַׁמְּשָׁא לְבַעְלָהּ, אִיהִי מְנַרְתָּא דִּילֵיהּ, דְּאִתְּמַר בֵּיהּ, (תהילים קי״ט:קס״ד) שֶׁבַע בַּיוֹם הִלַּלְתִּיךָ, דְּאִינּוּן: הַגְּדוּלָה, וְהַגְּבוּרָה, וְהַתִּפְאֶרְת, וְהַנֵּצַח, וְהַהוֹד, יְסוֹד, וּמַלְכוּת. שֶׁבַע כְּלִילָא.</p>\n<p>מִשֶּׁבַע דַּרְגִּין אִלֵּין, שְׁלֹשֶׁת קְנֵי מְנוֹרָה מִצִדָּה הָאֶחָד, גּוּפָא וּתְרֵין דְּרוֹעֵי דְּמַלְכָּא. אִיהוּ נֵר מִצְוָה, לְאַנְהָרָא בְּהוֹן. וּשְׁלֹשָׁה קְנֵי מְנוֹרָה מִצִדָּה הַשֵּׁנִי, אִינּוּן תְּרֵין שׁוֹקִין, וּבְרִית. וְאִיהוּ נֵר מַעֲרָבִית, לְאַנְהָרָא בְּהוֹן. מְנַרְתָּא דְּמַלְכָּא אִתְקְרִיאַת, וְאִיהִי נֵר לְאַנְהָרָא בֵּיהּ נֵר מִצְוָה, דְּאִתְּמַר בֵּיהּ (תהילים י״ט:ט׳) מִצְוַת יְיָ' בָּרָה מְאִירַת עֵינָיִם.</p>\n<p>וּמַאן רִישָׁא דִּמְנַרְתָּא, בִּינָה ה' עִלָּאָה, דְּאִית לָהּ תְּלַת קָנִין, בְּדִיּוּקְנָא דָּא ה', תְּלַת וָוִי\"ן, דְּאִינּוּן תְּלַת אֲבָהָן. ה' תַּנִּינָא, ג' קָנִים תִּנְיָינִין בְּדִיּוּקְנָא דָּא ה', (ס\"א תלת ווין) דְּאִינּוּן נְצַח הוֹד יְסוֹד. ו' מְנַרְתָּא דְּאֶמְצָעִיתָא בֶּן יָ\"הּ. עַל שְׁמֵיהּ אִתְקְרֵי בִּינָה. אִיהוּ כָּלִיל ו' קָנִין לְתַתָּא, בְּחוּשְׁבָן ו', בְּו' קָנִין דִּילֵיהּ.</p>\n<p>י' (משלי י״ב:ד׳) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ, תָּגָא דְּסֵפֶר תּוֹרָה, כְּצוּרַת ז' מִסִּטְרָא דְּעָלְמָא דְּאָתֵי, לָאו אִיהִי מָאנָא לְגַבֵּיהּ, וְלָאו מְשַׁמְּשָׁא לְגַבֵּיהּ, אֶלָּא עֲטָרָה עַל רֵישֵׁיהּ. אֲבָל בְּעָלְמָא דֵּין, אִיהִי כְּגַוְונָא דָּא, הוה\"י אִיהוּ מָאנָא תְּחוֹתֵיהּ, שִׁמּוּשָׁא דִּילֵיהּ, בְּכָל סְפִירָה דִּילֵיהּ, בְּכָל אֵבֶר דִּילֵיהּ, בְּכָל מִדָּה דִּילֵיהּ.</p>\n<p>וּבְגִין דָּא, י' דָּא, לְזִמְנִין אִיהִי תְּחוֹתוֹהִי, לְזִמְנִין עַל רֵישֵׁיהּ, לְזִמְנִין בְּאֶמְצָעִיתָא. עַל רֵישֵׁיהּ יְהוָֹ\"ה (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָה. וְדָא (ויקרא כ״ד:ב׳) לְהַעֲלוֹת נֵר תָּמִיד, דְּאִיהוּ י' עַל הו\"ה מִסִּטְרָא דִּמְנַרְתָּא. בְּאֶמְצָעִיתָא, מַחֲצִית הַשֶּׁקֶל, הֲדָא הוּא דִכְתִיב, (שמות ל׳:י״ג) זֶה יִתְּנוּ, כְּגַוְונָא דָּא הוי\"ה. בְּסוֹפָא, בְּמַשְׁכְּנָא, כְּגַוְונָא דָּא הוה\"י, חָמֵשׁ אַמּוֹת אֹרֶךְ, מִסִּטְרָא דְּה' עִלָּאָה, וְה' אַמּוֹת רֹחַב, מִסִּטְרָא דְּה' תַּתָּאָה. וְאַמָּה: ו'. וַחֲצִי הָאַמָּה: י'. וְכֹלָּא אִתְרְמִיז בְּאָת ו'.</p>\n<p>וְדָא אִיהוּ רָזָא, (ישעיהו מ״ה:ה׳) אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אֱלֹהִים דְּאִתְרְמִיז בְּהַאי שְׁמָא, יוֹ\"ד הֵ\"י וָי\"ו הֵ\"י וְכָל שֵׁם דְּשַׁלִּיט ה' עַל י' נוּקְבָּא אִיהוּ, מִסִּטְרָא דִּשְׂמָאלָא. וְאַף עַל גַּב דְּמִסְטְרָא דְּאָת י' אִיהִי בְּרִישָׁא, בָּתַר דְּבִתְרֵין הֵהִי\"ן אִיהִי בְּסוֹפָא, כְּגַוְונָא דָּא הֵ\"י הֵ\"י, אִתְּדָּן לְרוֹב, וְנוּקְבָּא אִיהִי. אֶלָּא י' עַל ה' (נ\"א ו') תָּגָא, תְּחוֹת ה', שִׁמּוּשׁ. כָּל שֶׁכֵּן תְּחוֹת ו'.</p>\n<p>וּבְגִין דְּלָא עֲבִידְנָא קִצוּץ וּפִרוּד בְּיִחוּדָא דִּלְעֵילָּא, דְּכֹלָּא יִחוּדָא חַד, נִתְקָשֶׁה לִי לְמֶעְבַּד. (או תגא, או אמצעי, או שמושא) וְקוּדְשָׁא בְּרִיךְ הוּא דְּיָדַע כָּל מַחֲשַׁבְתִּין, אָמַר, בָּתַר דְּדָא לְטוֹב אִתְכַּוָּון, דְּלָא לְמֶעְבַּד קִצוּץ וּפִרוּד, (שמות כה) תֵּ\"יעָשֶׂה הַמְנ\"וֹרָה, תֵּיעָשֶׂה מֵעַצְמָּה כְּגַוְונָא דִּשְׁכִינְתָּא, תֵּיעָשֶׂה מֵעַצְמּוֹ דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּלא פִּרוּדָא. שְׁאַר מָאנִין דִּבְהוֹן אִיהִי שְׁכִינְתָּא שִׁמּוּשׁ, (שמות ל״ז:א׳) וַיַּעַשׂ בְּצַלְאֵל.</p>\n<p>וּבְכָל אֲתָר דִּשְׁכִינְתָּא תַּתָּאָה אִיהִי עֲטָּרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, כַּד נְטִּילַת מִן בִּינָה, דְּאִיהוּ עָלְמָא דְּאָתֵי, וַדַּאי לֵית יְדִיעָה לְבַּר נָשׁ. בְּקוּדְשָׁא בְּרִיךְ הוּא, וְלָא בְּכָל מִדּוֹת דִּילֵיהּ, עַד דְּיֵעוּל בְּהַאי תַּרְעָא, דְּאִתְּמַר עָלָהּ (תהלים קיח) זֶה הַשַּׁעַר לַיְיָ'.</p>\n<p>בְּאוֹת ל', דְּאִיהִי יי (ייי), אִיהִי כְּלִילָא מִכָּל סְפִירָה, וּמִכָּל אַתְוָון דִּשְׁמָהָן, מְפוֹרָשִׁים וְנִסְתָּרִים. אִיהִי נְקוּדָה בְּכָל אָת וְאָת, שִׁמּוּשָׁא תְּחוֹת בַּעְלָהּ. וְאִיהִי עֲטָרָה עַל רֵישֵׁיהּ, מִסִּטְרָא דִּילָהּ דְּטַעֲמֵי. כְּגוֹן סֶגוֹל נְקוּדָה תְּחוֹת יַרְכֵי מַלְכָּא, (ישעיהו ס״ו:א׳) וְהָאָרֶץ הֲדוֹם רַגְלָי. וְאִיהִי בְּאֶמְצָעִיתָא, עִמֵּיהּ, מַחֲצִית הַשֶׁקֶל, בְּשׁוּרֻק. וְאִיהִי עֲטָּרָה עַל רֵישֵׁיהּ, מִסִּטְרָא דְּסֶגוֹלְתָּא.</p>\n<p>זַרְקָא מַקַּף, שׁוֹפָר הוֹלֵךְ, סֶגוֹלְתָּא, בְּהַהוּא זִמְנָא אִיהִי כֶּתֶר עַל רֵישָׁא דְּמַלְכָּא, כֶּתֶר יִתְּנוּ לְךָ יְיָ' אֱלֹהֵינוּ. אִיהִי יְדִיעַת הַהוּא דְּאִתְּמַר בֵּיהּ, בַּמוּפְלָא מִמָּךְ אַל תִּדְּרוֹשׁ וּבִמְכוּסֶה מִמָּךְ אַל תַּחְקוֹר. דְּבָהּ אִשְׁתְּמוֹדָע, דְּאִיהוּ רִאשׁוֹן לְעֵילָּא בְּתָגָא, דְּהַיְינוּ סֶגוּלְתָּא וְאִיהוּ אַחֲרוֹן, בְּסֶגוֹל. וּמִבַּלְעֲדָיו אֵין אֱלֹהִים, בְּשׁוּרֻק. וְכֹלָּא בָּהּ אִשְׁתְּמוֹדָע. (לתתא)</p>\n<p>מַאן דְּאִתְדַּבָּק בָּהּ לְתַתָּא, אִיהִי מְסַלְּקָא לֵיהּ לְעֵילָּא. וּמַאן דְּבָעֵי לְאִסְתַּלְּקָא עָלָהּ לְאַדְבְּקָא לְעֵילָּא מִינָּהּ, אִיהִי מַשְׁפִּילָתּוֹ לְתַתָּא מִינָּהּ, וְלֵית לֵיהּ חוּלָקָא בָּהּ. וּבְגִין דְּיַעֲקֹב אִשְׁתְּמוֹדָע בָּהּ, אוֹלִיף <Nonei></i>לָהּ לִבְנוֹי, וּמָנֵי דְּלָא יְבַקְּשׁוּן לְסַלְּקָא לְדַרְגָּא לְעֵילָּא מִינָּהּ, דְּאִיהִי כֹּלָּא, עֵילָּא וְתַתָּא וְאֶמְצָעִיתָא. הֲדָא הוּא דִכְתִיב, (בראשית מ״ט:כ״ח) וְזֹאת אֲשֶׁר דִּבֶּר לָהֶם אֲבִיהֶם.</p>\n<p>נָבִיא דְּהֲוָה אִשְׁתְּמוֹדַע בָּהּ, צָוַוח וְאָמַר לְמָארֵי תּוֹרָה חֲכָמִים בְּאוֹרַיְיתָא, וַעֲתִירִין בָּהּ, וּשְׂמֵחִים בְּחֶלְקָם. צָוַוח לְגַבַּיְיהוּ וְאָמַר, (ירמיהו ט׳:כ״ג) כֹּה אָמַר יְיָ' אַל יִתְהַלֵּל וְגוֹ', כִּי אִם בְּזֹאת יִתְהַלֵּל הַמִּתְהַלֵּל הַשְׂכֵּל וְיָדוֹעַ אוֹתִי. דָּוִד דְּהֲוָה יָדַע בָּהּ אָמַר, (תהילים כ״ז:ג׳) אִם תַּחֲנֶה עָלַי מַחֲנְה וְגוֹ', בְּזֹאת אֲנִי בוֹטֵחַ. וְיִרְמְיָה חָזָא גָּלוּתָא אָרִיךְ, וְסָמָאֵל (נ\"א אתא) וְנָחָשׁ וְכָל מְמָנָן דְּשִׁבְעִין אוּמִין בְּרִבּוֹ רִבְּוָון, דְּנַחְתֵּי עַל יִשְׂרָאֵל, וְחָזָא הַאי קְרָא דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא, (ויקרא כ״ו:מ״ד) וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגוֹ', אָמַר נָבִיא (איכה ג׳:כ״א) זֹאת אָשִׁיב אֶל לִבִּי עַל כֵּן אוֹחִיל. וַאֲשֶׁר לֹא שָׁת לִבּוֹ גַּם לָזֹאת, עָלֵיהּ אִתְּמַר (תהילים צ״ב:ז׳) וּכְסִיל לָא יָבִין אֶת זֹאת. (דברים ל״ג:ז׳) וְזֹאת לִיהוּדָה וַיֹּאמַר שְׁמַע יְיָ' קוֹל יְהוּדָה, בְּגִין דְּנָטִיר מַאי דְּמָנֵי לֵיהּ אֲבוֹי זָכָה לְמַלְכוּ. וְדָוִד בְּגִינָהּ אִסְתַּלָּק לְמַלְכוּ, דְּטָרַח כָּל יוֹמוֹי עָלָהּ.</p>\n<p>אָמַר בּוּצִינָא קַדִּישָׁא, עָלָהּ אִתְּמַר, (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה וְגוֹ'. בָּהּ אַזְהַרְתְּ לְיִשְׂרָאֵל, בִּשְׁעַת מִיתָּתְךָ. בָּהּ בֵּרַכְתְּ לְיִשְׂרָאֵל, בְּכָל שֵׁבֶט וְשֵׁבֶט. הֲדָא הוּא דִכְתִיב, (דברים ל״ג:א׳) וְזֹאת הַבְּרָכָה אֲשֶׁר בֵּרַךְ מֹשֶׁה וְגוֹ', וּבְגִין דָּא אוּקְמוּהָ חַבְרַיָּיא מָארֵי מַתְנִיתִין, דִּכְתִּיב, (במדבר י״ט:י״ד) זֹאת הַתּוֹרָה אָדָם כִּי יָמוּת בְּאֹהֶל, וְאָמְרוּ עָלָהּ מַאי כִּי יָמוּת בְּאֹהֶל, אֶלָּא אֵין הַתּוֹרָה מִתְקַיֶּימֶת, אֶלָּא בְּמִי שְׁמֵמִית עַצְמוֹ עָלֶיהָ, וְלֵית מִיתָה אֶלָּא עוֹנִי, דְּעָנִי חָשׁוּב כַּמֵּת.</p>\n<p>דְּאִיהוּ קָרְבָּן עוֹלֶה וְיּוֹרֵד. מִסִּטְרָא דְּעָשִׁיר עוֹלֶה וַדַּאי, דְּאִסְתַּלָּק עָלֵיהּ. דְּכָל עֲתִירִין, כָּל טִיבוּ דְּעַבְדִין, כֻּלְּהוֹן (ס\"א רובא דלהון) לְזַכָּאָה לְהוֹן לְעָלְמָא דְּאָתֵי, וְתַמָּן אִיהִי תָּגָא עַל רֵישַׁיְיהוּ. בֵּינוֹנִי, דְּפָלַח לְמִזְכֵּי בִּתְרֵין עָלְמִין, אִיהוּ מַחֲצִּית הַשֶׁקֶל עִמֵּיהּ בְּעָלְמָא דְּאָתֵי, כְּגוֹן מַצָּה דְּאִתְפְּלִיג, חֶצְיָהּ תַּחַת הַמַפָּה לַאֲפִיקוֹמָן בָּתַר סְעוּדָה. וְחֶצְיָה לְמִצְוָה קֹדֶם סְעוּדָה. וּמִסִּטְרָא דָּא נְאֱמַר בְּאֶסְתֵּר, (אסתר ה׳:ו׳) מַה שְּׁאֵלָתֵךְ וְיִּנָתֶן לָךְ וּמַה בַּקָּשָׁתֵךְ עַד חֲצִי הַמַּלְכוּת וְתֵעָשׂ.</p>\n<p>אֲבָל מַאן דְּאִיהוּ עָנִי, דְּמֵמִית גַּרְמֵיהּ בְּגִינָהּ, כְּגַוְונָא דִּילָךְ רַעְיָא מְהֵימָנָא, אִיהוּ קָרְבָּן יוֹרֵד תְּחוֹתָךְ, וַאֲמַאי. בְּגִין דְּמַאן דְּאַשְׁפִּיל גַּרְמֵיהּ בְּגִין שְׁכִינְתֵּיהּ, דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ נָחִית עָלֵיהּ, וְהַאי הוּא דְּאָמַר דָּוִד, (תהילים קל״ח:ו׳) כִּי רָם יְיָ' וְשָׁפָל יִרְאֶה. וְהַנָּבִיא אָמַר, (ישעיהו נ״ז:ט״ו) כִּי כֹה אָמַר רָם וְנִשָּׂא שׁוֹכֵן עַד וְקָדוֹשׁ שְׁמוֹ וְגוֹ' וְאֶת דַּכָּא וּשְׁפַל רוּחַ. דְּאַף עַל גַּב דַּאֲנָא מָרוֹם וְקָדוֹשׁ אֶשְׁכּוֹן, בְּגִין הַהוּא דְּאִתְעָבִיד דַּכָּא וּשְׁפַל רוּחַ בְּגִין שְׁכִינָתִי, לְסַלְּקָא לָהּ מִשִּׁפְלּוּת דִּילָהּ עֲטָּרָא לְרֵישֵׁיהּ, אָנָא נָחִית לְדַיְּירָא עִמֵּיהּ. וּבָתַר דְּבַעְלָהּ דִּשְׁכִינְתָּא נָחִית עַל בַּר נָשׁ, אִיהִי נְחִיתַת מֵעַל רֵישֵׁיהּ, וְיָהִיבַת אַתְרָא דְּרִישָׁא לְבַעְלָהּ, וּנְחִיתַת לְרַגְלוֹי דְּמַלְכָּא. וְרָזָא דְּמִלָּה, (ישעיהו ס״ו:א׳) הַשָּׁמַיִם כִּסְאִי וְהָאָרֶץ הֲדוֹם רַגְלָי.</p>\n<p>דְּמִיּוֹמָא דְּיָרִית בַּר נָשׁ נִשְׁמְתָא, כְּלִילָא מְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, מֵהַהִיא שַׁעֲתָא (צ\"א ע\"א) אִתְקְרֵי בֵּן. אָמַר חַד תָּנָא, וְכִי מֵהַהוּא יוֹמָא דְּיָרִית בַּר נָשׁ נִשְׁמְתָא, כְּלִילָא מְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, יִתְקְרֵי בְּרֵיהּ מְנָא לָן. מֵהַאי קְרָא דְּאָמַר דָּוִד בְּסֵפֶר תְּהִלִּים, (תהילים ב׳:ז׳) אֲסַפְּרָה אֶל חֹק יְיָ' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךָ.</p>\n<p>אֲמַר לֵיהּ בּוּצִינָא קַדִּישָׁא, רַעְיָא מְהֵימָנָא, מַאי הַיּוֹם יְלִדְתִּיךָ. אֶלָּא בְּגִינָךְ אָמַר דָּוִד בְּרוּחַ קֻדְשָׁא, אֲנִי הַיּוֹם יְלִדְתִּיךָ. הֵן עוֹד הַיּוֹם גָּדוֹל, בְּהַהוּא דְּאִתְּמַר בֵּיהּ, (דברים לה) וְלָא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. אַנְתְּ קַיְּימָת בִּשְׁכִינְתָּא וְאָהַבְתָּ אֶת יְיָ' אֱלהֶיךָ בְּכָל לְבָבְךָ, דְּהַיְינוּ גּוּפָא. וּבְכָל נַפְשְׁךָ, דְּהַיְינוּ נִשְׁמְתָא. דַּחֲמֵשׁ שְׁמָהָן אִית לָהּ: נְשָׁמָה. רוּחַ. נֶפֶשׁ. חַיָּה. יְחִידָה. וּבְכָל מְאֹדֶךָ, בְּכָל מָמוֹנָא דִּילָךְ. קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ לָא יָזוּז מִינָךְ בְּכָל אִלֵּין.</p>\n<p>אַנְתְּ חַשָׁבְתְּ, דְּאֲפִילּוּ הֲווֹ כָּל עָלְמִין תְּחוֹת רְשׁוּתָךְ, הֲוֵית יָהִיב לְאַקָּמָא לִשְׁכִינְתָּא בְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְאַמְלָכָא לֵיהּ בִּשְׁכִינְתֵּיה עַל כָּל מְמָנָן דְּאוּמִין דְּעָלְמָא, וּלְבָתַר לְסַלְּקָא לֵיהּ וּשְׁכִינְתֵּיהּ. בְּדִיּוּקְנָא דִּילָךְ כְּלִילָא מִכָּל מִדּוֹת טָבִין, בְּכָל עָלְמִין, וּבְמַשִּׁרְיָּין עִלָּאִין וְתַתָּאִין, וְעַל כָּל יִשְׂרָאֵל.</p>\n<p>מַחֲשָׁבָה <Nonei></i>טוֹבָה הַקָדוֹשׁ בָּרוּךְ הוּא מְצָרְפָהּ לְמַעֲשֶׂה. בָּתַר דְּאַנְתְּ בְּרֵיהּ, עַל כָּל דְּחָשַׁבְת לְמָרָךְ, יְקֻיָּים עַל יָדָךְ, וְלָא תָּזוּז מִנֵּיהּ לְעָלְמִין, אֶלָּא תְּהֵא בְּדִיּוּקְנֵיהּ בְּכֹלָּא. וְאַנְתְּ בְּגָלוּתָא גָּנִיז מִבְּנִי נָשָׁא. וְאַנְתְּ מֵעָלְמָא דָּא, שְׁלִיחָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְמֵימַר מִלִּין אִלֵּין קֳדָמָךְ, וַאֲנָא מְצוּוֶה מִנֵּיהּ, דְּלָא לְמֵזַז מִינָךְ בְּכָל עֵת וְשַׁעֲתָא דְּאַנְתְּ בָּעֵי. אַנָא וְכָל תַּנָאִין וְאָמוֹרָאִין דִּמְתִיבְתָּאן. קוּם אַשְׁלִים פִּקּוּדִין דְּמָרָךְ.</p>"],[9520011753,"<p>פָּתַח וְאָמַר, וְעָשׂוּ (שמות כ״ה:י׳) אֲרוֹן עֲצֵי שִׁטִּים. סֵפֶר תּוֹרָה, עַמּוּדָא דְּאֶמְצָעִיתָא. אֲרוֹן דִּילֵיהּ, שְׁכִינְתָּא. מִבַּיִת וּמִחוּץ תְּצַפֶּנוּ, לְקוּדְשָׁא בְּרִיךְ הוּא בִּשְׁכִינְתֵּיה, מִלְבַר וּמִלְגוֹ (ד\"א ל\"ג דיליה) וְכֹלָּא חַד. מַה דְּלָאו הָכִי בְּאָרוֹן דְּהַאי עָלְמָא, דְּאוֹרַיְיתָא מִלְּגוֹ מִין אֶחָד, וְאָרוֹן מִין אַחֲרָא. דָּא בִּכְתִיבַת דְּיוֹ, וְדָא עֵץ מְצוּפֶּה זָהָב. דְּוַדַּאי אוֹרַיְיתָא חֲבִיבָא מִכֹּלָּא, הֲדָא הוּא דִכְתִיב, (איוב כ״ח:י״ז) לא יַעַרְכֶנָּה זָהָב וּזְכוּכִית.</p>\n<p>וּמִסִּטְרָא אַחֲרָא אֲפִילּוּ בְּהַאי עָלְמָא, אַחְזֵי דְּכֹלָּא חַד, דְּיוֹ וְעֵץ, דִּדְיוֹ מִתַפּוּחִים, דְּאִתְעָבִידּוּ בְּעֵץ אִינּוּן, (וכל מילין דדיו עץ אינון) וְעוֹד, דְּיוֹ אוּכָם מִלְבַר, וְחִוָּור מִלְּגוֹ. הָכִי אִינּוּן (נ\"א חכמים מארי תורה) מָארֵי תּוֹרָה וַחֲכָמִים, אוּכָמִים בְּהַאי עָלְמָא דְּאִיהוּ לְבַר, שְׁפִירִין בְּהַהוּא עָלְמָא דְּאָתֵי, דְּאִיהוּ מִלְּגוֹ. וּבְגִין דָּא, דְּיוֹ, לִישָׁנָא דַּיוֹ לְעֶבֶד לִהְיוֹת כְּרַבּוֹ. דַּיוֹ: יוֹ\"ד יָדוֹ, חָכְמָה וּתְבוּנָה וָדַעַת דְּכָתַּב בַּר נָשׁ בְּיָדוֹ בִּדְיוֹ. (ע\"כ רעיא מהימנא) (פנחס רמ\"ב ע\"א, פקודא דא להקריב מנחה)</p>"],[9520011754,"<p>פָּתַח רַבִּי יוֹסִי וְאָמַר, בְּאִינּוּן רָזִין עִלָּאִין דְּמַשְׁכְּנָא כְּתִיב, (שמות כ״ה:מ׳) וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם וְגוֹ', וּכְתִיב וַהֲקֵמֹתָ אֶת הַמִּשְׁכָּן כְּמִשְׁפָּטוֹ וְגוֹ', אוֹלִיפְנָא דְּאָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, כָּל תִּקּוּנִין, וְכָל דִּיוּקְנִין דְּמַשְׁכְּנָא, כָּל חַד וְחַד כַּדְקָא חֲזִי לֵיהּ, דְּחָמָא לֵיהּ לִמְטַטְרוֹ\"ן, דְּקָא מְשַׁמֵּשׁ לְכַהֲנָא רַבָּא לְגוֹ. וְאִי תֵּימָא, וְהָא לָא אִתְּקַם מַשְׁכְּנָא לְעֵילָּא, עַד יוֹמָא דְּאִתְּקַם מַשְׁכְּנָא לְתַתָּא, וְלָא (קמ\"ג ע\"א) שִׁמֵשׁ הַהוּא נַעַר דִּלְעֵילָּא, עַד יוֹמָא דְּשִׁמְשׁוּ לְתַתָּא, בְּהַאי מַשְׁכְּנָא אַחֲרָא.</p>\n<p>אֶלָּא וַדַּאי הָכִי הוּא, דְּהָא מַשְׁכְּנָא לָא אִתְּקַם לְעֵילָּא, עַד דְּאִתְּקַם מַשְׁכְּנָא לְתַתָּא, אֲבָל חָמָא מֹשֶׁה חֵיזוּ דְּכָל מַשְׁכְּנָא, וְלָא הֲוָה מִתְסַדֵּר בְּקִיּוּמֵיהּ, עַד דְּאִתְּקַם מַשְׁכְּנָא לְתַתָּא, וְחָמָא לֵיהּ לִמְטַטְרוֹ\"ן מְשַׁמֵּשׁ לְבָתַר, לָאו דְּהֲוָה אִיהוּ מְשַׁמֵשׁ, אֶלָּא דְּהֲוָה מְשַׁמֵּשׁ לְבָתַר, וְלָאו בְּהַהוּא זִמְנָא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, חָמֵי מַשְׁכְּנָא, וְחָמֵי נַעַר, כֹּלָּא מִתְעֲכָּב עַד דְּיִתְקָם הָכָא לְתַתָּא.</p>\n<p>וְאִי תֵּימָא, אִי הָכִי, מְטַטְרוֹן אִיהוּ דְּקָא מְשַׁמֵּשׁ. אֶלָּא וַדַּאי מַשְׁכְּנָא דִּילֵיהּ אִיהוּ, וּמִיכָאֵל כַּהֲנָא רַבָּא, אִיהוּ דְּקָא מְשַׁמֵּשׁ גּוֹ הַהוּא מַשְׁכְּנָא דִּמְטַטְרוֹן. כְּגַוְונָא דִּמְשַׁמֵּשׁ כַּהֲנָא רַבָּא עִלָּאָה לְעֵילָּא, גּוֹ מַשְׁכְּנָא אַחֲרָא סְתִימָא דְּלָא אִתְגַּלְיָיא, בְּרָזָא דְּעָלְמָא דְּאָתֵי. תְּרֵין מַשְׁכְּנִין אִינּוּן. חַד אִיהוּ סְתִימָא עִלָּאָה. וְחַד הַאי מַשְׁכְּנָא דִּמְטַטְרוֹן. תְּרֵי כַּהֲנֵי אִינּוּן, חַד אוֹר קַדְמָאָה. וְחַד מִיכָאֵל כַּהֲנָא רַבָּא לְתַתָּא.</p>"],[9520011755,"<p>מִכָּאן רָזִין סְתִימִין דְּבֵי מַשְׁכְּנָא, מִפּוּמָא דְּבוּצִינָא. מַשְׁכְּנָא עִלָּאָה, אִתְבְּנֵי עַל תְּרֵיסַר מַרְגְּלִיטִין, שַׁיְיפִין עִלָּאִין, יְמִינָא וּשְׂמָאלָא, שְׂמָאלָא וִימִינָא.</p>\n<p>תְּלַת שְׁמָהָן אִינּוּן כְּלִילָן כַּחֲדָא, וְדָא עָיֵיל בְּדָא, וְדָא עָיֵיל בְּדָא. אֵ\"ל, קַדְמָאָה וְאִתְסָדַר בִּימִינָא. א, אִיהוּ קַדְמָאָה דְּאִיהִי (ויקרא ג') יְמִינָא, וְאַגְּלִים וְאִתְצָיָיר בְּרָזָא דִּימִינָא, וְכַד עָיֵיל וְקָא מְשַׁמֵּשׁ לְגוֹ אִתְאֲחָד בַּהֲדֵיהּ ל, וְאִקְרֵי בְּרָזָא דִּילֵיהּ אֵ\"ל, דְּהָא ל' מֵרָזָא דִּלְעֵילָּא גּוֹ קֹדֶשׁ הַקָּדָשִׁים נָפַק.</p>\n<p>לָאו דְּתַמָּן אַגְּלִים, אֶלָּא וַדַּאי כַּד נָפַק אַגְּלִים, כִּשְׁאַר אַתְוָון, דְּכַד נָפְקוּ מֵרָזָא דְּעָלְמָא דְּאָתֵי, אַגְלִימוּ וְאִתְצָיָירוּ. אוּף הָכִי הַאי ל', אַף עַל גַּב דְּאִיהוּ רָזָא דִּלְעֵילָּא, לָא אַגְּלִים, עַד דְּנָפַק לְבַר, וּכְדֵין אֵ\"ל. וְדָא רָזָא דִּימִינָא.</p>\n<p>שְׂמָאלָא כָּלִיל בְּגַוֵּיהּ לִימִינָא, וְנָטִיל הַאי שְׁמָא לְגַבֵּיהּ, וְאִתְכְּלִיל בַּהֲדֵיהּ, וְכַד אִתְכְּלִיל <Nonei></i>בַּהֲדֵיהּ אִקְרֵי אִיהוּ אֱלֹהִים. וְאִי תֵּימָא, הָא אַקְדִּים שְׂמָאלָא בְּרָזָא דְּעָלְמָא דְּאָתֵי.</p>\n<p>וַדַּאי הָכִי הוּא. אֶלָּא, כַּד נָפְקוּ דַּרְגִּין, בְּרָזָא דְּאַתְוָון מִגּוֹ עָלְמָא דְּאָתֵי, בָּעָא שְׁמָא דָּא לְאִתְחֲזָאָה וּלְאִתְבְּנֵי, לְאַחֲזָאָה עַל הַהוּא אֲתָר דְּנַפְקֵי מִתַּמָּן, וְאִתְבְּנִי שְׁמָא דָּא, כְּגַוְונָא דָּא. אֵ\"ל בְּקַדְמִיתָא בְּסִטְרָא דִּימִינָא, אִתְכְּלִיל גּוֹ שְׂמָאלָא, וְנָטִיל לֵיהּ שְׂמָאלָא, וְאִקְרֵי אֱלֹהִים, וְדָא אִיהוּ רָזָא דִּימִינָא, אֲמָר לֵיהּ בִּשְׁמָא וכו' בִּשְׁמָא דֶּאֱלֹהִים, וְעַל רָזָא דָּא, בְּכָל אֲתָר דְּאִיהוּ דִּינָא, תַּמָּן אִיהוּ רַחֲמֵי, דְּהָא כָּלִיל אִיהוּ דִּינָא, וְהָא אִתְבְּנֵי וְאִתְחַזֵּי.</p>\n<p>הַהוּא דְּנָפַק מִתַּמָּן, אֶמְצָעִיתָא, נָטִיל לְתַרְוַויְּיהוּ, וְאִשְׁתָּלִים, וְאִקְרֵי אֱלהֵינוּ. הָא הָכָא שְׁלִימוּ דְּאִתְחָזֵי מֵרָזָא דְּעָלְמָא עִלָּאָה, וְכֹלָּא אִתְכְּלִיל דָּא בְּדָא. כֵּיוָן דְּהַאי אֶמְצָעִיתָא אִשְׁתְּלִים, שָׁרָא עָלֵיהּ שְׁמָא קַדִּישָׁא, מַפְתְּחָא דְּכֹלָּא, דְּאִקְרֵי יְהוָֹ\"ה, וּכְדֵין נָטִיל לְכָל סִטְרִין, עֵילָּא וְתַתָּא, יְמִינָא וּשְׂמָאלָא, וּלְכָל סִטְרִין אַחֲרָנִין. וְעַל דָּא, כַּד אִשְׁתְּלִים מֵרָזָא דִּתְרֵין סִטְרִין מִימִינָא וּשְׂמָאלָא, אִקְרֵי אֱלֹהֵינוּ, הָא הָכָא יְמִינָא וּשְׂמָאלָא וְאֶמְצָעִיתָא בִּכְלָלָא דִּשְׁמָא דָּא. וְדָא אִתְחָזֵי וְאִתְבְּנֵי. רָזָא דְּאַתְוָון נָפְקוּ מִתַּמָּן, כְּגַוְונָא דָּא אִתְבְּנִי וְאִתְחַזֵּי, כָּל חַד וְחַד.</p>\n<p>הָא אִתְכְּלִיל יְמִינָא בִּשְׂמָאלָא, וְנָטִיל שְׂמָאלָא שְׁמָא דִּימִינָא, יְמִינָא אָן כָּלִיל בְּגַוִּיהּ שְׂמָאלָא, לְמֶהוֵי נָטִיל יְמִינָא רָזָא דִּשְׂמָאלָא. אֶלָּא, כַּד אִתְכְּלִיל יְמִינָא בִּשְׂמָאלָא, וְנָטִיל שְׂמָאלָא שְׁמָא רָזָא דִּימִינָא, יְמִינָא כָּלִיל בְּגַוִּיהּ שְׂמָאלָא, שְׁמָא אֵ\"ל. וְאִיהוּ הי\"ם.</p>\n<p>אֲמַאי הָכִי. אֶלָּא בְּשַׁעֲתָא דְּאִתְבְּנֵי הַהוּא אֲתָר דְּנַפְקוּ מִתַּמָּן, נָטִיל לִשְׂמָאלָא תְּרֵין אַתְוָון, יְמִינָא נָטִיל חַד, מֵרָזָא דְּעָלְמָא דְּאָתֵי. שְׂמָאלָא תְּרֵין, וְאִיהוּ הי\"ם. כְּדֵין יְמִינָא כָּלִיל בְּגַוֵּיהּ לִשְׂמָאלָא, וְנָטִיל לְאָת בַּתְרָאָה ם, וְנָטִיל י' דְּהֲוָה בִּשְׂמָאלָא, ם אִיהוּ בִּשְׁלִימוּ מֵ\"ם, וְאִתְבְּנִי הָכִי מַיִם, בְּהַהוּא י' דְּנָטִיל יַתִּיר. כְּדֵין יְמִינָא כָּלִיל לֵיהּ לִשְׂמָאלָא בְּגַוֵּיהּ.</p>"],[9520011756,"<p>לְבָתַר אִתְבָּנוּן אַתְוָון, א' דְּהֲוָה בְּקַדְמִיתָא בְּסִטְרָא דִּימִינָא, אוֹלִיד וְאַפִּיק אָת ש', כָּלִיל בִּתְלַת סִטְרִין, וְאִשְׁתָּתַּף בְּאָת א', וְאִתְעָבִיד אֵשׁ. תּוּ אַעְדּוּ אַתְוָון אִלֵּין, גּוֹ בְּטִישׁוּ דִּתְרֵין סִטְרִין אִלֵּין, וְאִתְקְרִיבוּ כַּחֲדָא בְּמַחְלוֹקֶת, וּמִגּוֹ מַחֲלוֹקֶת דָּא דְּמַיִם בְּאֵשׁ, וְאֵשׁ בְּמַיִם, אוֹלִידוּ אַתְוָון וְאַפִּיקוּ אָת ר' וְאָת ו' וְאָת ח' וְאִתְעָבִידוּ רוּחַ, וְעָאל בֵּין תְּרֵין סִטְרִין, וּכְדֵין אִתְיָישָׁבוּ אַתְוָון קַדְמָאֵי בְּדוּכְתַּיְיהוּ, כָּל חַד וְחַד בִּשְׁלִימוּ.</p>\n<p>תּוּ אַתְוָון אַעְדּוּ, וְאִתְגַּלְגְּלוּ כַּחֲדָא, א' אַפִּיק מ', דְּאִיהוּ מִסִּטְרָא דִּילֵיהּ בִּימִינָא, דְּהָא בִּימִינָא אִתְיָישָׁב. מ' אַפִּיק ש' בְּגִין דְּהָא מ' כְּלִילָא אִיהִי, בְּקַדְמִיתָא הֲוַת מִשְּׂמָאלָא, וְאִתְכְּלִיל לְבָתַר בִּימִינָא וְאִשְׁתְּלִים בִּתְרֵין סִטְרִין, כֵּיוָן דְּאִשְׁתְּלִים, אַעְדּוּ וְאוֹלִידוּ כַּחֲדָא, וְאִתְכְּלִלוּ בִּתְרֵין סִטְרִין.</p>\n<p>אִתְתְּקָפוּ אַתְוָון אמ\"ש תְּלַת אִלֵּין, וְאַעֲדוּ וְאוֹלִידוּ תְּלַת אַחֲרָנִין, גּוֹ גִּלְגּוּלָא. מ' אִתְתָּקַּן וְאַעְדֵּי וְאוֹלִיד ר'. א' אַעְדֵּי וְאוֹלִיד ו'. ש' אַעְדֵּי וְאוֹלִיד ח', וְאִשְׁתָּכְלַל כֹּלָּא.</p>\n<p>תּוּ אַעְדּוּ אַתְוָון אִלֵּין רָזָא אמ\"ש, וְאִתְגַּלְגְּלוּ כְּמִלְּקַדְּמִין, א' אַעְדֵּי וְאוֹלִיד וְאַפִּיק אָת ב' בְּסִטְרָא דְּמַעֲרָב, כְּדֵין אִתְיָישָׁב אִיהוּ בִּסְטַר דָּרוֹם. מ' אַעְדֵּי וְאוֹלִיד וְאַפִּיק אָת ד' בְּסִטְרָא דְּצָפוֹן, כְּדֵין אִסְתַּלָּק אִיהוּ בֵּין צָפוֹן וְדָרוֹם, וְתַלְיָא בַּאֲוִירָא. ש' אַעְדֵּי וְאוֹלִיד וְאַפִּיק אָת ג', וְאִתְיָישָׁב בְּסִטְרָא דְּמִזְרָח, וְאִיהוּ אִסְתַּלָּק בֵּין מַעֲרָב וּמִזְרָח, וְתַלְיָא בַּאֲוִירָא. אִשְׁתְּכָחוּ תְּרֵין אַתְוָון מ\"ש, תַּלְיָין בַּאֲוִירָא.</p>\n<p>א' דְּאִשְׁתְּאַר, אִסְתַּלָּק בְּדוּכְתֵּיהּ, וְסָלִיק לְעֵילָּא, וְאִתְעַטָּר בֵּיהּ יָ\"ה. בְּאִלֵּין אִתְתָּקַּף, וְאַעְדֵּי וְאוֹלִיד ה\"ו, וְקָאִים בְּדוּכְתֵּיהּ, כְּדֵין אִתְעֲטָּר, וְאַנְהִיר, וּפָשִׁיט נְהִירוּ, וְאוֹלִיד נְהִירוּ, וְאַפִּיק אָת ט', בַּטִישׁוּ דְּקָא בָּטַשׁ וְנָהִיר רָזָא דְּעָלְמָא עִלָּאָה, <Nonei></i>בִּנְהִירוּ.</p>\n<p>כְּדֵין אִסְתַּלָּק א', וְנָטִיל מִגּוֹ אֲוִירָא מ\"ש, וְאִתְחַבָּרוּ בַּהֲדֵּיהּ, וַהֲווּ אמ\"ש כְּמִלְּקַדְּמִין, וְאִתְיָישָׁב א' בְּסִטְרָא דְּדָרוֹם, ש' בְּסִטְרָא דְּמִזְרָח, מ' בְּסִטְרָא דְּצָפוֹן. סַלְּקָא ג' דְּהֲוָה בְּסִטְרָא דְּמִזְרָח, וְאַעְדֵּי וְאוֹלִיד צ\"ת. אָתָא ב' דְּהֲוָה בִּסְטַר מַעֲרָב, וְסָלִיק וְאִתְחֲבָר בֵּין צ\"ת. סְלִיקוּ א' ו', דָּא מִסְּטָר מַעֲרָב (נ\"א דרום) וְדָא מִסְּטָר מִזְרָח, וְאִתְחַבָּרוּ תַּרְוַויְיהוּ בַּהֲדֵי ב' בֵּין צ\"ת, וְאַנְהִיר שְׁמָא צְבָאוֹת.</p>\n<p>כַּד אִתְנְהִיר שְׁמָא דָּא גּוֹ מַשְׁכְּנָא, אַעְדּוּ אַתְוָון וְאוֹלִידוּ ז' ב' (נ\"א ג') נ'. סְלִיקוּ אמ\"ש כְּמִלְּקַדְּמִין, וְאַעֲדוּ וְאוֹלִידוּ ס' ע' פ'.</p>\n<p>אִשְׁתְּאַר ק' יְחִידָאי, וְסַלְּקָא וְנַחְתָּא, קַיְּימָא גּוֹ נוּקְבָּא דִּתְהוֹמָא רַבָּא, חָמָא לֵהּ קוּדְשָׁא בְּרִיךְ הוּא, דְּקָא מִתְעַרְבְּבָא, בְּלֹא גּוּפָא וְלָא צִיּוּרָא, וְלָא עָיִיִל לְמַשְׁכְּנָא. עָבֵד לֵהּ חוּפָּאָה לְמַשְׁכְּנָא. וּמַאי נִיהוּ. יְרִיעוֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן, כְּמָה דְאַתְּ אָמֵר, (שמות כ״ו:ז׳) וְעָשִׂיתָ יְרִיעֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן, לְאֹהֶל וְלָא אֹהֶל. קוֹ\"ף וְלָא אָדָם.</p>\n<p>תּוּ אִתְגַּלְגָּלוּ אַתְוָון כְּמִלְּקַדְּמִין, גּוֹ עוֹבָדָא דְּמַשְׁכְּנָא, אמ\"ש, ש' אִתְגַּלְגְלָא וְאִתְיָישְׁבָא בִּסְטַר מִזְרָח, וְאִשְׁתְּאַר ג' תַּלְיָיא בַּאֲוִירָא. מ' אִתְגַּלְגְּלָא וְאִתְיָישְׁבָא בִּסְטַר צָפוֹן, וְנָפַק ד' וְאִתְחַבָּר גּוֹ ש' בְּהַהוּא סִטְרָא. א' אִתְגַּלְגַּל וְאִתְיָישָׁב וְסָלִיק לְגַבֵּי י', וְסַלְּקָא וְאִתְתַּקְפָא בַּהֲדֵיהּ, וְנָטִיל לֵיהּ, וְאִתְחֲבָּר גּוֹ בְּחִבּוּרָא חֲדָא שַׁדָּ\"י. כַּד שְׁמָא דָּא אִתְתָּקַּן גּוֹ מַשְׁכְּנָא, כְּדֵין קִיוּמָא וְקַיְמָא אִיהוּ מִגּוֹ מַשְׁכְּנָא דִּלְתַתָּא.</p>\n<p>תּוּ אַתְוָון אִתְגַּלְגָּלוּ כְּמִלְּקַדְּמִין, לְאִתְיַישְּׁבָא מַשְׁכְּנָא, סְלִיקוּ אַתְוָון, א' בְּרֵישָׁא, ת' לְבָתַר, א\"ת. ב' בְּרִישָׁא, ש' לְבָתַר, אִתְחַלָּפוּ אַתְוָון, אב\"ג ית\"ץ, אִתְגַּלְגָּלוּ בְּגִלּוּפֵי קֻדְשָׁא א' ק'. א' אַפִּיק ק'. לְנַטְרָא מַשְׁכְּנָא. ק', אַפִּיק ר'. ר' אַפִּיק ע' קר\"ע.</p>\n<p>רָזָא דָּא, (בראשית כ״ז:ט״ז) וְאֶת עוֹרוֹת גְּדָיֵי הָעִזִּים הִלְבִּישָׁה עַל יָדָיו וְעַל חֶלְקַת צַוָּארָיו. כְּגַוְונָא דָּא, וְעָשִׂיתָ יְרִיעֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן. דְּהָא חוּלָקָא דָּא, אִצְטְרִיךְ לְאַחֲזָאָה לְבַר, לְנַטְרָא הַהִיא דִּלְגָּאו, וְעַל רָזָא דָּא אַלְבִּישָׁת לֵיהּ לְיַעֲקֹב לְבַר. שט\"ן קר\"ע, אַתְוָון אִינּוּן רְשִׁימָן לְבַר, בְּגִין נְטוּרָא דְּמַשְׁכְּנָא, דְּאִיהוּ רָזָא דִּבְרִית קַדִּישָׁא, וְאִתְפָּרְעָא עָרְלָה לְבָתַר בְּחוּפָּאָה דָּא.</p>\n<p>תּוּ אִתְגַּלְגְּלוּ אַתְוָון, וְאַפִּיק א\"ת ב\"ש, שִׁקוּצִי\"ת בְּרֵאשִׁית בָּרָא אֱלהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ וְהָאָרֶץ הָיְתָה תֹהוּ וְגוֹ'. בְּגִלְגּוּלָא דָּא וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ בְּאַתְוָון קר\"ע שט\"ן. וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם ג' אַפִּיק ר', ד' ק' עַד הָכָא אַתְוָון, אִתְגַּלְגְּלוּ, וּבְטִישׁוּ דָּא בְּדָא לְתִקּוּנָא גּוֹ מַשְׁכְּנָא.</p>\n<p>אִינּוּן אמ\"ש אַפִּיקוּ תּוֹלָדִין, (נ\"א ת') ה' צ' ו' ף' אַתְוָון דְּתַלְיָין גּוֹ אֲוִירָא, וּבְטִישׁוּ בְּאִינּוּן אַחֲרָנִין וְאַפִּיקוּ צִיּוּרָא דְּמַשְׁכְּנָא ז' ע'. עַד הָכָא קַיְּימָא וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם ח' כֻּלְּהוּ בְּסִטְרוֹי אָתָא ס' וְאִתְחַבָּר בַּהֲדֵיהּ, כְּדֵין יְהִי אוֹר וַיְהִי אוֹר.</p>\n<p>אִתְגַּלְגְּלוּ אַתְוָון כְּמִלְּקַדְּמִין, אב\"ג ית\"ץ, אַעְדּוּ וְאוֹלִידוּ וְאַפִּיקוּ צִיּוּרָא גּוֹ רָזִין דְּמַשְׁכְּנָא, (ס\"א בכללא) אִתְגַּלְגְּלוּ חֲדָא בְּרָזָא א' ל' ב' ם', דְּהָא אָת א' אַעְדֵּי, וְאוֹלִיד בְּרָזָא דְּחֵילָּא וְתּוּקְפָּא, אָת ל'. אִתְגַּבָּר בְּתוּקְפֵּיהּ, וְאִסְתַּלָּק בִּיקָרֵיהּ, וְאוֹלִיד אָת ב', כְּדֵין אַעְדִּיאוּ וְאוֹלִידוּ אַתְוָון וְאִתְחֲבָּרוּ אַחֲרָנִין אִלֵּין א' אִתְחַבָּר בְּגִלוּפֵיהּ בְּאָת ב', כְּדֵין ט\"ר בְּחִבּוּרָא ט\"ת לְמֶהוֵי אַתְוָון סַלְּקִין בְּאַתְרַיְיהוּ, גּוֹ צֵרוּפָא דְרָזָא דְּמַשְׁכְּנָא. (שמות ל״ה:ט״ז) אֶת הַכִּיּוֹר וְאֶת כַּנוֹ.</p>\n<p>יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, דְּהָא מַיִין סְלִיקוּ וְנַחְתּוּ בְּרָזָא דְּאַתְוָון א\"ל. א' אַפִּיק ו'. ו' אַפִּיק ק'. אָת ל' סָלִיק אִתְגְלִיפוּ אַתְוָון בְּגִלּוּפַיְיהוּ, בְּחִבּוּרָא חֲדָא, (תהילים כ״ט:ג׳) קוֹל יְיָ' עַל הַמָּיִם אֵ\"ל וְכוּ', אִלֵּין אָתְוָון אֵ\"ל, דְּהָא אִלֵּין אַעְדּוּ וְאוֹלִידוּ וְאַפִּיקוּ אַתְוָון, גּוֹ צִיּוּרִין דְּמַשְׁכְּנָא.</p>\n<p>אמ\"ש אַעְדוּ וְאוֹלִידוּ וְאִתְגְּלִיפוּ בְּגִלּוּפֵי רָזִין דְּאַתְוָון, לְאַפָּקָא צִיּוּרִין דְּמַשְׁכְּנָא, א' אַפִּיק ג', ש' <Nonei></i>אַפִּיק ן', לְחַבְּרָא גּוֹ אָת ג' בְּרָזָא גַּן. תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב וְגוֹ'. אִתְגַּלְגְּלוּ אַתְוָון כְּמִלְּקַדְּמִין אמ\"ש, בְּרָזָא ב\"ם בְּאִלֵּין כְּנִישׁוּ מַיָּא לַאֲתָר חַד, דִּכְתִּיב יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד. (עד כאן מצאתי בהעתק)</p>"],[9520011757,"<p>רַבִּי חִיָּיא וְרַבִּי יוֹסִי הֲווֹ אַזְלֵי בְּאָרְחָא, עַד דַּהֲווֹ אַזְלֵי אָמַר רִבִּי יוֹסִי, נִפְתַּח בְּעִידּוּנִין, (נ\"א בעירין ובעידנין) וְנֵימָא מִלֵּי דְּאוֹרַיְיתָא. פָּתַח רִבִּי יוֹסִי בְּמִלֵּי דִּקְרִיאַת שְׁמַע וְאָמַר, כְּתִיב (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלהֵינוּ יְיָ' אֶחָד. וּכְתִיב (דברים כ״ז:ט׳) שְׁמַע יִשְׂרָאֵל הַיּוֹם הַזֶּה נִהְיִיִתָ לְעָם. וּכְתִיב (דברים ט׳:א׳) שְׁמַע יִשְׂרָאֵל אַתָּה עוֹבֵר הַיּוֹם אֶת הַיַּרְדֵּן. כָּל הָנִי שְׁמַע שְׁמַע דְּקָאָמַר מֹשֶׁה אֲמַאי. דְּהָא שְׁמַע יִשְׂרָאֵל דְּיִחוּדָא יֵאוֹת. (דהאי לדרשא קאתי) הָנֵי אַחֲרָנִין אֲמַאי.</p>\n<p>אֶלָּא כֻּלְּהוּ לִדְּרָשָׁא קָאֲתוּ, שְׁמַע יִשְׂרָאֵל דְּיִחוּדָא וַדַּאי הַאי לִדְּרָשָׁא קָא אַתְיָא, וְהָכָא רָמִיז וְאִתְחַזֵּי יִחוּדָא דְּחָכְמְתָא עִלָּאָה. שְׁמַע, ע' מֵאַתְוָון רַבְרְבָן אִיהִי, אֲמַאי. אֶלָּא רֶמֶז קָא רָמִיז בִּכְלָלָא חֲדָא, לְאַכְלְלָא עֵילָּא וְתַתָּא כַּחֲדָא בְּיִחוּדָא חֲדָא, (רט\"ז ע\"א) שְׁמַע: שֵׁם ע'. הָכָא אִתְכְּלִיל הַאי שֵׁם בְּאִינּוּן ע' (ק\"ח ע\"א) שְׁמָהָן עִלָּאִין, לְאַכְלְלָא לוֹן, דְּהָא שֵׁם אִתְבָּרְכָא מִנַּיְיהוּ, וְאִתְכְּלִיל בְּהוּ. וְאִצְטְרִיךְ לְאַכְלְלָא לוֹן כַּחֲדָא בְּיִחוּדָא חַד, וּלְשַׁוָּאָה רְעוּתֵיהּ בְּהוּ.</p>\n<p>דְּהָא וַדַּאי ע' שְׁמָהָן אִינּוּן בְּרָזָא דִּרְתִּיכָא עִלָּאָה, וּמֵהַאי רְתִיכָא עִלָּאָה, אִתְבָּרְכָא הַאי שֵׁם, וְאִתְכְּלִיל בְּגַוַויְיהוּ, וּלְבָתַר יִשְׂרָאֵל בִּכְלָל. אֲבָל הָא תָּנֵינָן, דָּא יִשְׂרָאֵל סָבָא, לְמֶהֱוֵי יִשְׂרָאֵל בִּכְלָלָא חֲדָא, הַהוּא אֲתָר דְּבֵקוּתָא דְּכֹלָּא. וְעַל דָּא שְׁמַע יִשְׂרָאֵל, הַשְׁתָּא אִתְדָּבָקַת אִתְּתָא בְּבַעְלָהּ, וַהֲוֵי כֹּלָּא בִּכְלָלָא חֲדָא, וְדָא שְׁמַע יִשְׂרָאֵל דְּיִחוּדָא. (ישראל) לְבָתַר קָא מְיַחֵד תְּלַת סִטְרִין, יְיָ' אֱלהֵינוּ יְיָ' אֶחָד, לְמֶהֱוֵי כֹּלָּא חַד.</p>\n<p>שְׁמַע יִשְׂרָאֵל דְּכֻלְּהוּ שְׁאַר, לָאו אִינּוּן כְּהַאי גַּוְונָא, אֲבָל כֻּלְּהוּ אַחֲרָנִין לִדְּרָשָׁא קָאֲתוּ, וְכֻלְּהוּ בְּאֲתָר אַחֲרָא אִתְדָּבָקוּ, שְׁמַע יִשְׂרָאֵל אַתָּה עֹבֵר הַיּוֹם. שְׁמַע יִשְׂרָאֵל הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם. וְכֻלְּהוּ בְּדַרְגָּא תַּתָּאָה אִתְדָּבָקוּ.</p>\n<p>שְׁמַע יִשְׂרָאֵל הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם, שְׁמַע יִשְׂרָאֵל יֵאוֹת. הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם מַהוּ. הָיִיתָ מִבָּעֵי לֵיהּ, מַאי נִהְיֵיתָ. אֶלָּא בְּכָל אֲתָר עָם, כַּד אִתְבָּרוּ לִבַּיְיהוּ לְפֻלְחָנָא, כְּמָה דְאַתְּ אָמֵר (דניאל ח׳:כ״ז) נִהְיֵיתִי וְנֶחלֵתִי. וְדָא הוּא דִּכְתִּיב, (דברי הימים א כ״ח:ב׳) שְׁמָעוּנִי אַחַי וְעַמִּי. אִי אַחַי, לָמָּה עַמִּי, וְאִי עַמִּי, לָמָּה אַחַי. אֶלָּא אָמַר דָּוִד, אִי בִּרְעוּתָא אַתּוּן אַחַי, וְאִי לָאו אַתּוּן עַמִּי, לְתַּבְרָא לִבַּיְיכוּ לְפוּלְחָנִי. כַּךְ הַיּוֹם הַזֶּה נִהְיֵיתָ לְעַם, תָּבַרְתְּ לִבְּךָ לְפֻלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>שְׁמַע יִשְׂרָאֵל אַתָּה עוֹבֵר הַיּוֹם אֶת הַיַּרְדֵּן, כֹּלָּא בְּדַרְגָּא תַּתָּאָה, אִיהוּ, וְשָׁמַע יִשְׂרָאֵל דְּיִחוּדָא הוּא דַּרְגָּא עִלָּאָה. מַה בֵּין הַאי לְהַאי. אֶלָּא הַהוּא שְׁמַע יִשְׂרָאֵל דְּיִחוּדָא, לָא הֲוֵי בְּכֻלְּהוּ כְּהַאי גַּוְונָא, דְּהָא אִיהוּ הֲוֵי רָזָא דְּעֵילָּא וְתַתָּא. (כדקא יאות) (נ\"א ובכל אתר רזא לקבל וכו') וְאִיהוּ רָזָא לְקַבְּלָא עָלַיְיהוּ עוֹל מַלְכוּת שָׁמַיִם, בְּכָל סִטְרָא, בְּגִין דְּיִצְטְרִיךְ לֵיהּ לְבַר נָשׁ, לְמֶהֱוֵי זַמִּין (בההוא שמא) בְּהַהִיא שַׁעֲתָא, לְיַחֲדָא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְקַבְּלָא עָלֵיהּ עוֹל מַלְכוּת שָׁמַיִם.</p>\n<p>וּבְשַׁעֲתָא דְּאָתֵי בַּר נָשׁ לְקַבְּלָא עָלֵיהּ עוֹל מַלְכוּת שָׁמַיִם, כְּדֵין שְׁכִינְתָּא אַתְיָא וְשַׁרְיָא עַל רֵישֵׁיהּ, וְקָאִים עָלֵיהּ כְּסָהִיד, לְסָהֲדָא סַהֲדוּתָא קָמֵי מַלְכָּא קַדִּישָׁא, דְּהַאי אִיהוּ דְּקָא מְיַחָד שְׁמֵיהּ תְּרֵי זִמְנִי בְּיוֹמָא, וּשְׁמֵיהּ אִתְּיֵיחַד עֵילָּא וְתַתָּא כְּדְקָא יֵאוֹת. וְעַל דָּא ע' מִשְׁמַע יִשְׂרָאֵל מֵאַתְוָון רַבְרְבָן, וְד' נָמֵי מֵאַתְוָון רַבְרְבָן, לְמֶהֱוֵי עֵד קָמֵי מַלְכָּא קַדִּישָׁא. וְהָא אוּקְמוּהָ, יְדוָֹ\"ד אֱלֹהֵינוּ יְדוָֹ\"ד, וְדָא הוּא רָזָא דְּיִחוּדָא בִּתְלַת סִטְרִין, כְּמָה דְּאוֹקְמֵיהּ בּוּצִינָא קַדִּישָׁא, וְאִתְּעַר בֵּיהּ בְּכַמָּה דּוּכְתֵּי, וְלֵית לָן רְשׁוּ לְאַתְעֲרָא בֵּיהּ יַתִּיר.</p>\n<p>וַדַּאי הַאי בַּר נָשׁ, דְּקָא מְיַחֵד שְׁמָא <Nonei></i>דְּקוּדְשָׁא בְּרִיךְ הוּא עֵילָּא וְתַתָּא כְּדְקָא יֵאוֹת, שְׁכִינְתָּא אַתְיָא וְשַׁרְיָא עַל רֵישֵׁיהּ, וּמְבָרֵךְ לֵיהּ בְּשֶׁבַע בִּרְכָּאן, וְקָרֵי עָלֵיהּ, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.</p>"],[9520011758,"<p>רַבִּי חִיָּיא פָּתַח אֲבַתְרֵיהּ וְאָמַר, (דברים ד׳:ל״ה) אַתָּה הָרְאֵתָ לָדַעַת כִּי יְיָ' הוּא הָאֱלהִים וְגוֹ', הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, אַתָּה הָרְאֵתָ, מַאי הָרְאֵתָ. אֶלָּא כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, לָא הֲווֹ יַדְעֵי בְּרָזָא דִּמְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא כְּלוּם, בְּגִין דְּכֻלְּהוּ הֲווֹ פַּלְחֵי פּוּלְחָנָא נוּכְרָאָה בְּגָלוּתָא, וְאַנְשׁוּ כָּל עִקָּרָא דִּמְהֵימְנוּתָא דְּהֲוָה בְּהוּ בְּקַדְמִיתָא, דְּיָרִיתוּ כָּל אִינּוּן תְּרֵיסַר שְׁבָטִין מֵאֲבוּהוֹן יַעֲקֹב.</p>\n<p>וְכַד אָתָא מֹשֶׁה, אוֹלִיף לוֹן דְּאִית אֱלוֹהַּ עִלָּאָה בְּעָלְמָא, כְּמָה דְּאוּקְמוּהָ. לְבָתַר חָמוּ כָּל אִינּוּן נִסִּין וּגְבוּרָן דְּעַל יַמָא, וְכָל נִסִּין וּגְבוּרָן דְּעָבַד לְהוּ בְּמִצְרַיִם. לְבָתַר חָמוּ כַּמָה גְּבוּרָן, בְּמָנָא וּבְמַיָא וְאִתְיְהִיבַת לוֹן אוֹרַיְיתָא, וְאוֹלִיפוּ אָרְחֵי דְּקוּדְשָׁא בְּרִיךְ הוּא, עַד דְּמָטֵי לְעִדָּנָא דָּא.</p>\n<p>אָמַר לוֹן מֹשֶׁה, עַד הַשְׁתָּא אִצְטְרִיכְנָא לְמֵילַף לְכוּ, כְּמָה דְּיַלְפִין לְרַבְיָּא. (מכאן ולהלאה) וְדָא הוּא אַתָּה הָרְאֵתָ לָדַעַת, וְאוֹלִיפַת עַד הָכָא, לָדַעַת לְמִנְדַּע וּלְאִסְתַּכְּלָא וּלְמֵיעַל בְּרָזָא דִּמְהֵימְנוּתָא. וּמַאי אִיהִי. כִּי יְיָ' הוּא הָאֱלהִי ם.</p>\n<p>אִי תֵּימָא מִלָּה זְעִירָא הִיא לְמִנְדַּע, הָא כְּתִיב וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ כִּי יְיָ' הוּא הָאֱלֹהִים בַּשָׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת אֵין עוֹד. הָכָא תַּלְיָא כָּל רָזָא דִּמְהֵימְנוּתָא, לְמִנְדַּע מִגּוֹ דָּא, רָזָא דְּכָל רָזִין, לְמִנְדַּע סְתִימוּ (נ\"א רזא דכלוכו') דְּכָל סְתִימִין, יְהוָֹ\"ה אֱלהִים שֵׁם מָלֵּא, וְכֹלָּא חַד. אַתָּה הָרְאֵתָ לָדַעַת, הָכָא רָזָא דְּרָזִין לְאִינּוּן יַדְעֵי מִדִּין.</p>"],[9520011759,"<p>זַכָּאִין אִינּוּן כָּל אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. וּבְגִין דְּכַד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, אִסְתָּכַּל בָּהּ בְּאוֹרַיְיתָא, וּבָרָא עָלְמָא, וּבְאוֹרַיְיתָא אִתְבְּרֵי עָלְמָא, כְּמָה דְּאוּקְמוּהָ, דִּכְתִּיב, (משלי ט) וָאֶהְיֶה אֶצְלוֹ אָמוֹן, אַל תִּקְרֵי אָמוֹן אֶלָּא אוּמָן.</p>\n<p>וְכִי אוֹרַיְיתָא אוּמָנָא הֲוָה. אִין. לְמַלְכָּא דְּבָעֵי לְמֶעְבַּד פְלַטְרִין, אִי לָא שַׁוִּי לְגַבֵּיהּ אוּמָנָא, לָא יָכִיל לְמֶעְבַּד פְּלַטְרִין. כֵּיוָן דִּפְלַטְרִין אִתְעָבִידוּ, לָא סָלִיק שְׁמָא, אֶלָּא דְּמַלְכָּא. אִלֵּין פְּלַטְרִין דְּעָבַד מַלְכָּא, מַלְכָּא שַׁוִּי בְּאִינּוּן פְּלַטְרִין מַחֲשָׁבָה.</p>\n<p>כַּךָ קוּדְשָׁא בְּרִיךְ הוּא, בָּעֵי לְמִבְרֵי עָלְמָא, אִסְתָּכַּל בְּאוּמָנָא, וְאַף עַל גַּב דְּאוּמָנָא עֲבַד פְּלַטְרִין, לָא סָלִיק שְׁמָא אֶלָּא דְּמַלְכָּא, אִלֵּין פְּלַטְרִין דַּעֲבַד מַלְכָּא, וַדַּאי מַלְכָּא בָּנָה פְּלַטְרִין. אוֹרַיְיתָא צווַֹחַת וָאֶהְיֶה אֶצְלוֹ אָמוֹן, בִּי בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, דְּעַד (נ\"א אלא עד) (ס\"א לא אתברי) אִתְבְּרֵי עָלְמָא, אַקְדִּימַת אוֹרַיְיתָא תְּרֵין אַלְפֵי שְׁנִין לְעָלְמָא, וְכַד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי עָלְמָא, הֲוָה מִסְתַּכָּל בָּהּ בְּאוֹרַיְיתָא, בְּכָל מִלָּה וּמִלָּה, וְעָבִיד לָקֳבְלָהּ אוּמָנוּתָא דְּעָלְמָא. בְּגִין דְּכָל מִלִּין וְעוֹבָדִין דְּכָל עָלְמִין, בְּאוֹרַיְיתָא אִינּוּן. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא הֲוָה מִסְתָּכַּל בָּהּ, וּבָרָא עָלְמָא.</p>\n<p>לָאו דְּאוֹרַיְיתָא בָּרָא עָלְמָא, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, בְּאִסְתַּכְּלוּתָא דְּאוֹרַיְיתָא בָּרָא עָלְמָא. אִשְׁתְּכַח דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ אוּמָנָא, וְאוֹרַיְיתָא לָקֳבְלֵיהּ וּלְגַבֵּיהּ אוּמָנָא, שֶׁנֶּאֱמַר וָאֶהְיֶה אֶצְלוֹ אָמוֹן, וָאֶהְיֶה אָמוֹן לָא כְּתִיב, אֶלָּא אֶצְלוֹ, הוֹאִיל וְקוּדְשָׁא בְּרִיךְ הוּא אִסְתָּכַּל בָּהּ, אֶצְלוֹ הֲוָה אוּמָנָא.</p>\n<p>וְאִי תֵּימָא מַאן יָכִיל לְמֶהוֵי אוּמָנָא לְגַבֵּיהּ. אֶלָּא אִסְתַּכְּלוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגַוְונָא דָּא, (ד\"א אתעביד בלא עמל ויגיעה דכתיב בדבר יי שמים נעשו וגו'. בגוונא דא באסתכלותא דיליה היא אומנא) בְּאוֹרַיְיתָא, כְּתִיב בָּהּ, (בראשית א׳:א׳) בְּרֵאשִׁית בָּרָא אֱלהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, אִסְתָּכַּל בְּהַאי מִלָּה, וּבָרָא אֶת הַשָּׁמַיִם. בְּאוֹרַיְיתָא כְּתִיב בָּהּ, וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, אִסְתָּכַּל בְּהַאי מִלָּה, וּבָרָא אֶת הָאוֹר. וְכֵן בְּכָל מִלָּה וּמִלָּה דִּכְתִּיב בָּהּ בְּאוֹרַיְיתָא, אִסְתָּכַּל קוּדְשָׁא בְּרִיךְ הוּא, וְעָבִיד הַהִיא מִלָּה, וְעַל דָּא כְּתִיב וָאֶהְיֶה אֶצְלוֹ אָמוֹן. כְּגַוְונָא דָּא כָּל עָלְמָא אִתְבְּרֵי.</p>\n<p>כֵּיוָן דְּאִתְבְּרֵי עָלְמָא, כָּל מִלָּה וּמִלָּה לָא הֲוָה מִתְקַיֵּים, עַד דְּסָלִיק בִּרְעוּתָא לְמִבְרֵי אָדָם, דִּיהֱוֵי מִשְׁתָּדַּל בְּאוֹרַיְיתָא, וּבְגִינָהּ אִתְקְיָּים עָלְמָא. הַשְּׁתָּא <Nonei></i>כָּל מַאן דְּאִסְתָּכַּל בָּהּ בְּאוֹרַיְיתָא, וְאִשְׁתָּדַּל בָּהּ, כִּבְיָכוֹל, הוּא מְקַיֵּים כָּל עָלְמָא. קוּדְשָׁא בְּרִיךְ הוּא אִסְתָּכַּל בְּאוֹרַיְיתָא, וּבָרָא עָלְמָא. בַּר נָשׁ מִסְתַּכֵּל בָּהּ בְּאוֹרַיְיתָא וּמְקַיֵים עָלְמָא. אִשְׁתְּכַח דְּעוֹבָדָא וְקִיּוּמָא דְּכָל עָלְמָא, אוֹרַיְיתָא אִיהִי. בְּגִין כַּךְ זַכָּאָה אִיהוּ בַּר נָשׁ דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, דְּהָא אִיהוּ מְקַיֵּים עָלְמָא.</p>\n<p>בְּשַׁעֲתָא דְּסָלִיק בִּרְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי אָדָם, קָאִים קָמֵיהּ בְּדִיוּקְנִיהּ וְקִיוּמֵיהּ, כְּמָה דְּאִיהוּ בְּהַאי עָלְמָא. וַאֲפִילּוּ כָּל אִינּוּן בְּנֵי עָלְמָא, עַד לָא יֵיתוּן בְּהַאי עָלְמָא, כֻּלְּהוּ קַיְימִין בְּקִיּוּמַיְיהוּ וּבְתִקוּנַיְיהוּ כְּגַוְונָא דְּקַיְימִין בְּהַאי עָלְמָא, בְּחַד אוֹצָר דְּתַמָּן כָּל נִשְׁמָתִין דְּעָלְמָא מִתְלַבְּשָׁן בְּדִּיוּקְנַיְיהוּ.</p>\n<p>וּבְשַׁעֲתָא דִּזְמִינִין לְנַחְתָּא בְּהַאי עָלְמָא, קָרֵי קוּדְשָׁא בְּרִיךְ הוּא לְחַד מְמָנָא, דִּי מָנֵּי קוּדְשָׁא בְּרִיךְ הוּא בִּרְשׁוּתֵיהּ כָּל נִשְׁמָתִין דִּזְמִינִין לְנַחְתָּא לְהַאי עָלְמָא, וְאָמַר לֵיהּ, זִיל אַיְיתֵי לִי רוּחַ פְּלוֹנִי. בְּהַהִיא שַׁעֲתָא אַתְיָא הַהִיא נִשְׁמְתָא, מִתְלַבְּשָׁא בְּדִיּוּקְנָא דְּהַאי עָלְמָא, וְהַהוּא מְמָנָא אַחְזֵי לָהּ קָמֵי מַלְכָּא קַדִּישָׁא.</p>\n<p>קוּדְשָׁא בְּרִיךְ הוּא אָמַר לָהּ, וְאוֹמֵי לָהּ, דְּכַד תֵּיחוֹת לְהַאי עָלְמָא, דְּתִשְׁתָּדַל בְּאוֹרַיְיתָא לְמִנְדַּע לֵיהּ, וּלְמִנְדַּע בְּרָזָא דִּמְהֵימְנוּתָא. דְּכָל מַאן דְּהֲוֵי בְּהַאי עָלְמָא, וְלָא אִשְׁתָּדַּל לְמִנְדַּע לֵיהּ, טָב לֵיהּ דְלָא יִתְבְּרֵי. בְּגִין כָּךְ אִתְחָזֵי קָמֵי מַלְכָּא קַדִּישָׁא, לְמִנְדַּע בְּהַאי עָלְמָא, וּלְאִשְׁתַּדְּלָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, בְּרָזָא דִּמְהֵימְנוּתָא.</p>"],[9520011760,"<p>הֲדָא הוּא דִכְתִיב, (דברים ד׳:ל״ה) אַתָּה הָרְאֵתָ לָדַעַת, אִתְחֲזִיאַת עַל יְדָא דְּהַהוּא מְמָנָא, קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. לָדַעַת לְמִנְדַּע וּלְאִסְתַּכְּלָא בְּהַאי עָלְמָא, בְּרָזָא דִּמְהֵימְנוּתָא, בְּרָזָא דְּאוֹרַיְיתָא. וְכָל מַאן דְּהֲוָה בְּהַאי עָלְמָא, וְלָא אִשְׁתָּדַּל בְּאוֹרַיְיתָא לְמִנְדַּע לֵיהּ, טַב לֵיהּ דְּלָא אִתְבְּרֵי, דְּהָא בְּגִין דָּא אַיְיתֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְבַר נָשׁ בְּהַאי עָלְמָא.</p>\n<p>לָדַעַת כִּי יְיָ' הוּא הָאֱלהִים. דָּא אִיהוּ כְּלָלָא דְּכָל רָזָא דִּמְהֵימְנוּתָא, (נ\"א כללא) דְּכָל אוֹרַיְיתָא, כְּלָלָא דְּעֵילָּא וְתַתָּא, וְרָזָא דָּא אִיהוּ כְּלָלָא דְּכָל רָזָא דִּמְהֵימְנוּתָא, וְהָכִי הוּא וַדַּאי. כְּלָלָא דְּכָל אוֹרַיְיתָא, דָּא אִיהוּ רָזָא דְּתוֹרָה שֶׁבִּכְתָּב, וְדָא אִיהוּ רָזָא דְּתוֹרָה שֶׁבְּעַל פֶּה, וְכֹלָּא חַד, כְּלָלָא דְּרָזָא דִּמְהֵימְנוּתָא, בְּגִין דְּאִיהוּ שֵׁם מָלֵּא, דְּאִיהוּ רָזָא דִּמְהֵימְנוּתָא, וּמַאן אִיהוּ. ה' אֶחָד וּשְׁמוֹ אֶחָד, יְיָ' אֶחָד שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד. דָּא אִיהוּ יִחוּדָא חַד. וּשְׁמוֹ אֶחָד, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, הָא יִחוּדָא אַחֲרָא לְמֶהֱוֵי שְׁמֵיהּ חַד. וְרָזָא דָּא (מלכים א יח) יְיָ' הוּא הָאֱלהִים, דָּא כְּתִיב, כַּד אִינּוּן בְּיִחוּדָא חֲדָא.</p>\n<p>וְאִי תֵּימָא, אִי הָכִי, כְּגַוְונָא דִּכְתִּיב, (זכריה י\"ד) יְיָ' אֶחָד וּשְׁמוֹ אֶחָד, לָאו אִיהוּ יְיָ' הוּא הָאֱלֹהִים, דְּאִי כְּתִיב (נ\"א יי' הוא ושמו אחד) יְיָ' אֶחָד וּשְׁמוֹ הוּא אֶחָד, הֲוָה אֲמֵינָא הָכִי. אֲבָל לָא כְּתִיב, אֶלָּא יְיָ' אֶחָד, וּשְׁמוֹ אֶחָד, וְאִצְטְרִיךְ לְמֵימַר כְּגַוְונָא דָּא יְיָ' הוּא, הָאֱלֹהִים הוּא, וְאִתְחַזֵּי יְיָ' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>אֶלָּא כֹּלָּא חַד, דְּכַד מִתְיַיחֲדָּן תְּרֵין שְׁמָהָן אִלֵּין, דָּא בְּיִחוּדָא חַד, וְדָא בְּיִחוּדָא חַד, כְּדֵין תְּרֵין שְׁמָהָן אִלֵּין אִתְעָבִידוּ חַד, וְאִתְכְּלִילוּ דָּא בְּדָא, וַהֲוִי כֹּלָּא שְׁמָא שְׁלִים, בְּיִחוּדָא חֲדָא, וּבְכֵן יְיָ' הוּא הָאֱלֹהִים, דְּהָא כְּדֵין אִתְכְּלִיל כֹּלָּא דָּא בְּדָא, לְמֶהֱוֵי חַד. וְעַד דְּאִתְיַחֲדוּ כָּל חַד, דָּא בִּלְחוֹדוֹי, וְדָא בִּלְחוֹדוֹי, לָא אִתְכְּלִילוּ דָּא בְּדָא, לְמֶהֱוֵי כֹּלָּא חַד.</p>\n<p>כְּלָלָא דְּכָל אוֹרַיְיתָא הָכִי אִיהוּ וַדַּאי, דְּהָא אוֹרַיְיתָא אִיהִי תּוֹרָה שֶׁבִּכְתָּב, וְאִיהוּ תּוֹרָה שֶׁבְּעַל פֶּה. תּוֹרָה שֶׁבִּכְתָּב, דָּא אִיהוּ דִּכְתִּיב יְיָ'. תּוֹרָה דְבְּעַל פֶּה, דָּא הוּא דִּכְתִּיב הָאֱלהִים. וּבְגִין דְּאוֹרַיְיתָא אִיהוּ רָזָא דִּשְׁמָא קַדִּישָׁא, אִקְרֵי הָכִי תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה דְבְּעַל פֶּה, דָּא כְּלָל, וְדָא פְּרָט. כְּלָל אִצְטְרִיךְ לִפְרָט, וּפְרָט אִצְטְרִיךְ לִכְּלָל, וְאִתְיַיחֲדוּ דָּא בְּדָא, לְמֶהֱוֵי כֹּלָּא חַד.</p>\n<p>וְעַל דָּא, כְּלָלָא דְּאוֹרַיְיתָא אִיהוּ כְּלָלָא דְּעֵילָּא וְתַתָּא, בְּגִין דִּשְׁמָא דָּא לְעֵילָּא, וּשְׁמָא דָּא לְתַתָּא, דָּא רָזָא דְּעָלְמָא עִלָּאָה, וְדָא רָזָא דְּעָלְמָא תַּתָּאָה, וְעַל דָּא כְּתִיב, אַתָּה הָרְאֵתָ לָדַעַת כִּי יְיָ' הוּא <Nonei></i>הָאֱלֹהִים. דָּא אִיהוּ כְּלָלָא דְּכֹלָּא, וְדָא אִצְטְרִיךְ בַּר נָשׁ לְמִנְדַּע בְּהַאי עָלְמָא.</p>\n<p>וְאִי תֵּימָא, פִּקּוּדֵי אוֹרַיְיתָא אָן אִינּוּן הָכָא בִּכְלָלָא דָּא. אֶלָּא דָּא אִיהוּ זָכוֹר, וְדָא אִיהוּ שָׁמוֹר, וְכָל פִּקּוּדֵי אוֹרַיְיתָא בְּהָנֵי כְּלִילָן, בְּרָזָא דְּזָכוֹר וּבְרָזָא דְּשָׁמוֹר, וְכֹלָּא אִיהוּ חַד.</p>"],[9520011761,"<p>פָּתַח רַבִּי יוֹסִי וְאָמַר, הָא דְּתָנֵינָן דִּצְלוֹתָא דְּעַרְבִית חוֹבָה, חוֹבָה אִיהִי וַדַּאי, בְּגִין דִּקְרִיאַת שְׁמַע דְּעַרְבִית חוֹבָה, וְקוּדְשָׁא בְּרִיךְ הוּא אִתְיָחַד בְּלֵילְיָא, כְּמָה דְּאִתְיָחַד בִּימָמָא, וּמִדַּת לֵילְיָא אִתְכְּלִיל בִּימָמָא, וּמִדַּת יְמָמָא אִתְכְּלִיל בְּלֵילְיָא, וְאִתְעָבִיד יִחוּדָא חֲדָא. וּמַאן דְּאָמַר רְשׁוּת, בְּגִין אֵמוּרִין וּפְדָרִין דְּמִתְאֲכְּלֵי בְּלֵילְיָא (ק\"ל ע\"א) וְהָא אוֹקִימְנָא.</p>\n<p>כְּתִיב (דברים ו׳:ה׳) וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ וְגוֹ', הַאי קְרָא אוֹקִימְנָא לֵיהּ, וְאוּקְמוּהָ חַבְרַיָּיא. אֲבָל אִית לְשָׁאֲלָא, אִי בְּהַאי יִחוּדָא דִּשְׁמַע יִשְׂרָאֵל, אִתְכְּלִיל כֹּלָּא, יְמִינָא וּשְׂמָאלָא, אֲמַאי (כתיב) לְבָתַר וְאָהַבְתָּ (דברים יא) וְהָיָה אִם שָׁמוֹעַ, דְּהָא בְּיִחוּדָא אִתְכְּלִילוּ. אֲבָל הָתָם בִּכְלָל, וְהָכָא בִּפְרַט, וְהָכִי אִצְטְרִיךְ.</p>\n<p>וּבְרָזָא דְּיִחוּדָא דָּא אִתְּעַרְנָא בֵּיהּ, יִחוּדָא דָּא אִיהוּ כְּגַוְונָא דִּתְפִלִּין דְּרֵישָׁא, וּתְפִלִּין דִּדְרוֹעָא. בִּתְפִלִין דְּרִישָׁא ד' פָּרְשִׁיָּין, וְהָא אִתְּמַר, וְהָכָא תְּלַת שְׁמָהָן אִינּוּן. הָתָם בִּתְפִילִין דְּרֵישָׁא, ד' פָּרְשִׁיָּין, כָּל חַד וְחַד בִּלְחוֹדוֹי, וְהָכָא תְּלַת שְׁמָהָן, מַה בֵּין הַאי לְהַאי.</p>\n<p>אֶלָּא אִינּוּן ד' פָּרְשִׁיָּין, הָא אִתְּעֲרוּ בְּהוּ, חַד, נְקוּדָה קַדְמָאָה עִלָּאָה. וְחַד, רָזָא דְּעָלְמָא דְּאָתֵי. וְחַד, יְמִינָא. וְחַד, שְׂמָאלָא. אִלֵּין רָזָא דִּתְפִלִּין דְּרֵישָׁא. וְהָכָא, בְּרָזָא דְּיִחוּדָא דָּא, תְּלַת שְׁמָהָן, וְאִינּוּן כְּגַוְונָא דְּאִינּוּן ד' פָּרָשִׁיּוֹת. יְיָ' (ט' ע\"א) קַדְמָאָה, דָּא נְקוּדָה עִלָּאָה, רִאשִׁיתָא דְּכֹלָּא. אֱלהֵינוּ רָזָא דְּעָלְמָא דְּאָתֵי. יְיָ' בַּתְרָאָה, כְּלָלָא דִּימִינָא וּשְׂמָאלָא כַּחֲדָא, בִּכְלָלָא חֲדָא, וְאִלֵּין אִינּוּן תְּפִלִּין דְּרִישָׁא, וְדָא אִיהוּ יִחוּדָא קַדְמָאָה.</p>\n<p>תְּפִלִּין דִּדְרוֹעָא, כְּלָלָא דְּכָל הָנֵי כַּחֲדָא, וְדָא אִיהוּ רָזָא בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. הָכָא כְּלָלָא דְּאִינּוּן תְּפִלִּין דְּרֵישָׁא, דְּאִתְכְּלִילוּ גּוֹ תְּפִלִּין דִּדְרוֹעָא.</p>\n<p>וְרָזָא דָּא, (קל\"ה ע\"ב) בָּרוּךְ: דָּא רָזָא דִּנְקוּדָה עִלָּאָה, דְּאִיהוּ בָּרוּךְ, דְּכָל בִּרְכָאן נַבְעִין מִתַּמָּן. וְאִי תֵּימָא עָלְמָא דְּאָתֵי אִקְרֵי בָּרוּךְ. לָאו הָכִי, דְּהָא נְקוּדָה עִלָּאָה אִיהוּ דְּכַר, עָלְמָא דְּאָתֵי נוּקְבָּא. אִיהוּ בָּרוּךְ וְאִיהִי בְּרָכָה. בָּרוּךְ דְּכָר. בְּרָכָה נוּקְבָּא. וְעַל דָּא בָּרוּךְ אִיהוּ נְקוּדָה עִלָּאָה, (ר' ע\"א) שֵׁם: דָּא עָלְמָא דְּאָתֵי, דְּאִיהוּ שֵׁם גָּדוֹל, כְּמָה דְאַתְּ אָמֵר (יהושע ז׳:ט׳) וּמַה תַּעֲשֵׂה לְשִׁמְךָ הַגָּדוֹל. כְּבוֹד: דָּא כָּבוֹד עִלָּאָה, דְּאִיהוּ יְמִינָא וּשְׂמָאלָא.</p>\n<p>וְכֻלְּהוּ כְּלִילָן בְּהַאי תְּפִלָּה שֶׁל יַד, דְּאִיהוּ מַלְכוּתוֹ, וְנָטִיל כֹּלָּא בְּגַוֵּיהּ, וּבְהַאי מַלְכוּתוֹ אִתְּכְּלִילָן בֵּיהּ עָלְמִין כֻּלְּהוּ, לְמֵיזַן לוֹן, וּלְסַפְּקָא לוֹן, בְּכָל מַה דְּאִצְטְרִיכוּ וְעַל דָּא לְעוֹלָם וָעֶד.</p>\n<p>וְדָא אִיהוּ יִחוּדָא דִּתְפִלִּין דְּרִישָׁא, וּתְפִלִּין דִּדְרוֹעָא, וּכְגַוְונָא דְּרָזָא דְּיִחוּדָא דִּתְפִלִּין, הָכִי אִיהוּ יִחוּדָא דְּכֹלָּא, וְדָא אִיהוּ בְּרִירָא דְּמִלָּה. וְהָא סָדַרְנָא יִחוּדָא דָּא קָמֵי בּוּצִינָא קַדִּישָׁא, וְאָמַר לִי, דְּהָא בְּד' גַּוְונִין אִתְסָדַר יִחוּדָא, וְדָא בְּרִירָא מִכֻּלְּהוּ, וְהָכִי אִיהוּ וַדַּאי, וְכֻלְּהוּ רָזָא דִּמְהֵימְנוּתָא, אֲבָל סִדּוּרָא דִּתְפִלִּין, דָּא אִיהוּ יִחוּדָא עִלָּאָה, כְּדְקָא יֵאוֹת.</p>"],[9520011762,"<p>וּמִגּוֹ דְּאִתְכְּלִילוּ יְמִינָא וּשְׂמָאלָא בְּרָזָא דִּשְׁמָא קַדִּישָׁא בְּאֹרַח כְּלָל, אִצְטְרִיךְ לְבָתַר לְאַפָּקָא לוֹן בְּאֹרַח פְּרָט, אֲבָל לָאו בְּאֹרַח יִחוּדָא, דְּהָא יִחוּדָא בִּקְרָא קַדְמָאָה אִיהוּ, לְמֶהוֵי יְדוָֹ\"ד אֶחָד בִּתְפִלִין דְּרֵישָׁא, וּשְׁמוֹ אֶחָד בִּתְפִלִין דִּדְרוֹעָא, וַהֲוֵי כֹּלָּא חַד. כֵּיוָן דְּיִחוּדָא דָּא אִתְסָדַר כֹּלָּא בִּכְלָלָא מֵרֵישָׁא דִּנְקוּדָה עִלָּאָה, (ס\"א דאיהו ראשיתא דכלא) אִצְטְרִיךְ לְבָתַר לְאַתְעֲרָא מֵרִישָׁא (ס\"א מרזא) דִּנְהוֹרָא קַדְמָאָה, דְּאִיהוּ רִישָׁא דְּכֹלָּא.</p>\n<p>וְאָהַבְתָּ דָּא רֵאשִׁיתָא דִּימִינָא, לְמִרְחַם לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בִּרְחִימוּ דְּאִתְדַּבְּקוּתָא דִּילֵיהּ, וּמַאן אִיהוּ. (נ\"א רחימו דאתער ימינא) יְמִינָא, דְּאִיהוּ אִתְּעַר רְחִימוּ. מַאן דְּרָחִים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ אִתְּעַר יְמִינָא דִּילֵיהּ לְגַבֵּיהּ. וּמְקַבָּל לֵיהּ <Nonei></i>בִּרְחִימוּ. כָּל מִלִּין דְּעָלְמָא לָא תַּלְיָין אֶלָּא בִּרְעוּתָא, רוּחַ אַמְשִׁיךְ רוּחַ וְאַיְיתֵי רוּחַ וְסִימָנָךְ דָּא (איוב לה) אִם יָשִׁים אֵלָיו לִבּוֹ רוּחוֹ וְנִשְׁמָתוֹ אֵלָיו יֶאֱסוֹף.</p>\n<p>כַּד אַתְעַר בַּר נָשׁ רְחִימוּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, אִתְעֲרוּתָא דִּימִינָא לָא אִתְּעַר, אֶלָּא בִּתְלַת גַּוְונִין, כְּמָה דְאַתְּ אָמֵר, (דברים ו׳:ה׳) בְּכָל לְבָבְךָ. וּבְכָל נַפְשְׁךָ. וּבְכָל מְאֹדֶךָ. הָא תְּלַת גַּוְונִין הָכָא. דְּלָא תֵּימָא אוֹ הַאי אוֹ הַאי, דְּהָא לָא כְּתִיב אוֹ בְּכָל לְבָבְךָ, אוֹ בְּכָל נַפְשְׁךָ, אוֹ בְּכָל מְאֹדֶךָ. אֶלָּא כֻּלְּהוּ אִצְטְרִיךְ, לִבָּא וְנַפְשָׁא וּמָמוֹנָא. וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר יְמִינֵיהּ לְגַבֵּיהּ, וּפָשִׁיט לֵיהּ לָקֳבְלֵיהּ, וּמְקַבְּלָא לֵיהּ.</p>\n<p>וְעַל דָּא כְּתִיב, (תהילים ק״י:א׳) נְאֻם יְיָ' לַאדֹנִי שֵׁב לִימִינִי. וְרָזָא דְּהַאי קְרָא, הָא אִתְּעַרְנָא בֵּיהּ, דְּדָוִד מַלְכָּא עַל דַּרְגָּא דִּילֵיהּ קָאָמַר, כַּד אִתְקָשָּׁר בִּימִינָא. תְּלֵיסָר פִּקּוּדִין הָכָא בִּימִינָא, וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ, הָא חֲדָא. בְּכָל לְבָבְךָ, תְּרֵין. וּבְכָל נַפְשְׁךָ, ג'. וּבְכָל מְאֹדֶךָ, אַרְבַּע. וְשִׁנַּנְתָּם לְבָנֶיךָ, חֲמִשָּׁא. וְדִבַּרְתָּ בָּם, הָא שִׁיתָא. בְּשִׁבְתְּךָ בְּבֵיתֶךָ, הָא שִׁבְעָה. וּבְלֶכְתְּךָ בַדֶרֶךְ, תְּמַנְיָא. וּבְשָׁכְבְּךָ, הָא תִּשְׁעָה. וּבְקוּמֶךָ, הָא עֲשָׂרָה. וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךָ, הָא חַד סָר. וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶיךָ, הָא תְּרֵיסָר. וּכְתַבְתָּם עַל מְזוּזוֹת בֵּיתֶךָ וּבִשְׁעָרֶיךָ, הָא תְּלֵיסָר.</p>\n<p>תְּלֵיסָר פִּקּוּדִין אִלֵּין, תַּלְיָין בִּימִינָא, וּשְׂמָאלָא אִתְכְּלִיל בִּימִינָא, וְהָכִי אִצְטְרִיךְ, וּבְכָל זִמְנָא דִּשְׂמָאלָא אִתְעַר, יְמִינָא שָׁארֵי בֵּיהּ בְּרֵישָׁא. וּבְגִין דָּא, אִם יִזְכּוּן, שְׂמָאלָא אִתְכְּלִיל בִּימִינָא. וְאִי לָאו, יְמִינָא אִתְכְּלִיל בִּשְׂמָאלָא, וְשַׁלְטָא שְׂמָאלָא. וְסִימָנָא דָּא, אִם בְּרֵישָׁא, כְּגוֹן (ויקרא כ״ו:ג׳) אִם בְּחוּקוֹתַי תֵּלְכוּ. וּבְכָל אֲתָר, שְׂמָאלָא אִתְּעַר בִּרְחִימוּ בְּרָזָא דִּימִינָא, וּלְבָתַר אִתְתָּקַּף דִּינֵיהּ, כְּמָה דְּאִצְטְרִיךְ. וְכַךְ אִצְטְרִיךְ בְּכָל אֲתָר, וְהָא אִתְּעָרוּ חַבְרַיָּיא, בְּהָנֵי מִלִּין. אָתָא רַבִּי חִיָּיא וּנְשָׁקֵיהּ.</p>"],[9520011763,"<p>פָּתַח וְאָמַר (שמותכו) וְאֶת הַמִּשְׁכָּן תַּעֲשֶׂה עֶשֶׂר יְרִיעוֹת וְגוֹ', הָא הָכָא רָזָא (קל\"ט ע\"ב) דְּיִחוּדָא, דְּהָא תִּקּוּנָא דְּמַשְׁכְּנָא מִכַּמָּה דַּרְגִּין אִיהוּ, דִּכְתִּיב בֵּיהּ וְהָיָה הַמִּשְׁכָּן אֶחָד. לְאִתְחֲזָאָה דְּכָל שַׁיְיפִין דְּגוּפָא, כֻּלְּהוּ רָזָא דְּגוּפָא חַד.</p>\n<p>בְּבַר נָשׁ אִית בֵּיהּ כַּמָה שַׁיְיפִין עִלָּאִין וְתַתָּאִין, אִלֵּין פְּנִימָאִין לְגוֹ, וְאִלֵּין בְּאִתְגַּלְּיָא לְבַר, וְכֻלְּהוּ אִקְרוּן גּוּפָא חֲדָא, וְאִקְרֵי בַּר נָשׁ חַד, בְּחִבּוּרָא חֲדָא. אוּף הָכִי מַשְׁכְּנָא, כֻּלְּהוּ שַׁיְיפִין כְּגַוְונָא דִּלְעֵילָּא, וְכַד אִתְחַבְּרוּ כֹּלָּא כַּחֲדָא, כְּדֵין כְּתִיב וְהָיָה הַמִּשְׁכָּן אֶחָד. (נ\"א כגוונא דאדם)</p>\n<p>פִּקּוּדֵי אוֹרַיְיתָא, כֹּלָּא שַׁיְיפִין וְאֵבָרִין, בְּרָזָא דִּלְעֵילָּא. וְכַד מִתְחַבְּרִין כֻּלְּהוּ כְּחַד, כְּדֵין כֻּלְּהוּ סַלְקָן לְרָזָא חַד. רָזָא דְּמַשְׁכְּנָא, דְּאִיהוּ אֵבָרִין וְשַׁיְיפִין, כֻּלְּהוּ סַלְּקִין לְרָזָא דְּאָדָם, כְּגַוְונָא דְּפִקוּדֵי אוֹרַיְיתָא, דְּהָא פִּקּוּדֵי אוֹרַיְיתָא, כֻּלְּהוּ בְּרָזָא דְּאָדָם, דְּכַר וְנוּקְבָּא, דְּכַד מִתְחַבְּרָן כַּחֲדָא, אִינּוּן חַד, רָזָא דְּאָדָם. מַאן דְּגָרַע אֲפִילּוּ פִּקּוּדָא חֲדָא דְּאוֹרַיְיתָא, כְּאִלּוּ גָּרַע דִּיּוּקְנָא דִּמְהֵימְנוּתָא, דְּהָא כֻּלְּהוּ שַׁיְיפִין וְאֵבָרִין בְּדִיּוּקְנָא דְּאָדָם, וּבְגִין כַּךְ כֹּלָּא סַלְּקָא בְּרָזָא דְּיִחוּדָא.</p>\n<p>וְעַל דָּא, יִשְׂרָאֵל אִינּוּן גּוֹי אֶחָד, דִּכְתִּיב, (יחזקאל לה) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם. וּכְתִיב (שמואל ב ז׳:כ״ג) מִי כְעַמְּךָ כְּיִשְׂרָאֵל וְגוֹ'.</p>"],[9520011764,"<p>רַבִּי יִצְחָק הֲוָה שְׁכִיחַ קָמֵיהּ דְּרַבִּי אֶלְעָזָר, אָמַר לֵיהּ, וַדַּאי רְחִימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּבַר נָשׁ רָחִים לֵיהּ, לָא אִתְּעַר אֶלָּא מִלִּבָּא, בְּגִין דְּלִבָּא אִיהוּ אִתְעָרוּתָא לְאִתְּעָרָא לְגַבֵּיהּ רְחִימוּ, (ורחמנא לבא בעי) אִי הָכִי, אֲמַאי כְּתִיב בְּכָל לְבָבְךָ, וּלְבָתַר וּבְכָל נַפְשְׁךָ. דְּמַשְׁמַע דִּתְרֵין גַּוְונִין אִינּוּן, חַד לִבָּא, וְחַד נַפְשָׁא, אִי לִבָּא הוּא עִקָּרָא, מַאי בָּעֵי נַפְשָׁא. אָמַר לֵיהּ, וַדַּאי לִבָּא וְנַפְשָׁא תְּרֵין אִינּוּן, וְאִתְאַחֲדָן לְחָד. דְּהָא לִבָּא וְנַפְשָׁא וּמָמוֹנָא, כֻּלְּהוּ אִתְאַחֲדָן דָּא בְּדָא, וְלִבָּא אִיהוּ עִקָּרָא וִיסוֹדָא דְּכֹלָּא.</p>\n<p>וְהָא דְּאִתְּמַר בְּכָל לְבָבְךָ, בִּתְרֵין לִיבָּן אִיהוּ, דְּאִינְהוּ תְּרֵין יִצְרִין, חַד יִצְרָא טָבָא, וְחַד יִצְרָא בִּישָׁא, וּתְרֵין אִלֵּין כָּל חַד וְחַד אִקְרֵי לֵב, דָּא <Nonei></i>אִקְרֵי לֵב טוֹב, וְדָא אִקְרֵי לֵב רָע. וּבְגִין כַּךְ אִיהוּ לְבָבְךָ, דְּאִינּוּן תְּרֵין, יֵצֶר הַטּוֹב וְיֵצֶר הָרָע.</p>\n<p>וּבְכָל נַפְשְׁךָ, וּבְנַפְשְׁךָ מִבָּעֵי לֵיהּ, מַאי וּבְכָל נַפְשְׁךָ, הַאי בְּכָל אֲמַאי. אֶלָּא לְאַכְלְלָא נפ\"ש ורו\"ח ונשמ\"ה, דָּא אִיהוּ וּבְכָל נַפְשְׁךָ, בְּכָל מַה דְּאָחִיד הַאי נֶפֶשׁ. וּבְכָל מְאֹדֶךָ, אוּף הָכִי כַּמָה זִינִין אִינּוּן דְּמָמוֹנָא, כֻּלְּהוּ מְשַׁנְיָין אִלֵּין מֵאִלֵּין, וְעַל דָּא כְּתִיב בְּכָל. רְחִימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמִמְסָר לֵיהּ כָּל דָּא, לְמִרְחַם לֵיהּ בְּכָל חַד וְחַד.</p>\n<p>וְאִי תֵּימָא, בְּיֵצֶר הָרָע הֵיךְ יָכִיל בַּר נָשׁ לְמִרְחַם לֵיהּ, דְּהָא יֵצֶר הָרָע מְקַטְרְגָא אִיהוּ, דְּלָא יִקְרַב בַּר נָשׁ לְפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְהֵיךְ יְרָחִים לֵיהּ בֵּיהּ. אֶלָּא, דָּא אִיהוּ פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא יַתִּיר, כַּד הַאי יֵצֶר הָרָע אִתְכַּפְיָא לֵיהּ, בְּגִין רְחִימוּ דְּקָא מִרְחַם לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. דְּכַד הַאי יֵצֶר הָרָע אִתְכַּפְיָא, וְתָבַר לֵיהּ הַהוּא בַּר נָשׁ, דָּא אִיהוּ רְחִימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דִּיְדִיעַ לְקָרְבָא לְהַהוּא יֵצֶר הָרָע, לְפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>הָכָא אִיהוּ רָזָא לְמָארֵי מִדִין. כָּל מַה דַּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא עֵילָּא וְתַתָּא, כֹּלָּא אִיהוּ בְּגִין לְאַחֲזָאָה יְקָרָא דִּילֵיהּ, וְכֹלָּא אִיהוּ לְפוּלְחָנֵיהּ. וְכִי מַאן חָמֵי עַבְדָּא, דְּלֶהוֵי מְקַטְרְגָא דְּמָארֵיהּ, וּבְכָל מַה דִּרְעוּתֵיהּ דְּמָארֵיהּ, אִתְעָבִיד אִיהוּ מְקַטְרְגָא, רְעוּתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דִּיהוֹן בְּנִי נָשָׁא תָּדִיר בְּפוּלְחָנֵיהּ, וְיֵהָכוּן בְּאֹרַח קְשׁוֹט, בְּגִין לְמִזְכֵּי לוֹן בְּכַמָּה טָבִין, הוֹאִיל וּרְעוּתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא בְּהַאי, הֵיךְ אַתְיָא עַבְדָּא בִּישָׁא, וְאִשְׁתְּכַח מְקַטְרְגָא מִגּוֹ רְעוּתֵיהּ דְּמָארֵיהּ, וְאַסְטֵי לִבְנֵי נָשָׁא לְאֹרַח בִּישׁ, וְאַדְחֵי לוֹן מֵאֹרַח טָב, וְעָבִיד לוֹן דְּלָא יַעַבְדוּן רְעוּתָא דְּמָארִיהוֹן, וְאַסְטֵי לִבְנֵי נָשָׁא לְאֹרַח בִּישׁ.</p>\n<p>אֶלָּא, וַדַּאי רְעוּתֵיהּ דְּמָארֵיהּ עָבִיד. לְמַלְכָּא דְּהֲוָה לֵיהּ בַּר יְחִידָאִי, וַהֲוָה רָחִים לֵיהּ יַתִּיר, וּפָקִיד עֲלֵיהּ בִּרְחִימוּ, דְּלָא יִקְרַב גַּרְמֵיהּ לְאִתְּתָא בִּישָׁא, בְּגִין דְּכָל מַאן דְּיִקְרַב לְגַבָּהּ, לָאו כְּדַאי אִיהוּ לְאַעֲלָא גּוֹ פְּלַטְרִין דְּמַלְכָּא. אוֹדֵי לֵיהּ הַהוּא בְּרָא, לְמֶעְבַּד רְעוּתֵיהּ דַּאֲבוֹי בִּרְחִימוּ.</p>\n<p>בְּבֵיתָא דְּמַלְכָּא, לְבַר, הֲוַת חֲדָא זוֹנָה, יָאֶה בְּחֵיזוּ, וּשְׁפִירָא בְּרֵיוָא. לְיוֹמִין אָמַר מַלְכָּא, בְּעֵינָא לְמֵחמֵי רְעוּתֵיהּ דִּבְרִי לְגַבָּאי. קָרָא לָהּ לְהַהִיא זוֹנָה, וְאָמַר לָהּ זִילִי וּתְפַתִּי לִבְרִי, לְמֵחמֵי רְעוּתֵיהּ דִּבְרִי לְגַבָּאי. הַהִיא זוֹנָה מַאִי עַבְדַת, אַזְלַת אֲבַתְרֵיהּ דִּבְרֵיהּ דְּמַלְכָּא שָׁרָאת לְחַבְּקָא לֵיהּ וּלְנַשְּׁקָא לֵיהּ, וּלְפַתֵּי לֵיהּ בְּכַמָּה פִּתּוּיִין. אִי הַהוּא בְּרָא יֵאוֹת, וְאָצִית לְפִקּוּדָא דַּאֲבוֹי, גָּעַר בָּהּ, וְלָא אָצִית לָהּ, וְדָחֵי לָהּ מִנֵּיהּ. כְּדֵין אָבוֹי חַדֵּי בִּבְרֵיהּ, וְאָעִיל לֵיהּ לְגוֹ פַּרְגּוֹדָא דְּהֵיכָלֵיהּ, וְיָהִיב לֵיהּ מַתְּנָן וּנְבִזְבְּזָא וִיקָּר סַגְיָא. מַאן גָּרִים כָּל הַאי יְקָר לְהַאי בְּרָא, הֲוֵי אֵימָא הַהִיא זוֹנָה.</p>\n<p>וְהַהִיא זוֹנָה אִית לָהּ שְׁבָחָא בְּהַאי אוֹ לָאו. וַדַּאי שְׁבָחָא אִית לָהּ מִכָּל סִטְרִין. חַד, דְּעַבְדַּת פִּקּוּדָא דְּמַלְכָּא. וְחַד, דְּגַרְמָת לֵיהּ לְהַהוּא בְּרָא, לְכָל הַהוּא טִיבוּ, לְכָל הַאי רְחִימוּ דְּמַלְכָּא לְגַבֵּיהּ. וְעַל דָּא כְּתִיב, (בראשית א׳:ל״א) וְהִנֵּה טוֹב מְאֹד. וְהִנֵּה טוֹב, דָּא מַלְאָךְ חַיִּים. (ס\"ח ע\"ב) מְאֹד, דָּא מַלְאָךְ הַמָּוֶת, דְּאִיהוּ וַדַּאי טוֹב מְאֹד, לְמַאן דְּאָצִית פִּקּוּדִין דְּמָארֵיהּ. וְתָא חֲזִי, אִי לָא יְהֵא הַאי מְקַטְרְגָא, לָא יַרְתוּן צַדִּיקַיָּא הָנִי גִּנְזְיָא עִלָּאִין, דִּזְמִינִין לְיָרְתָא לְעָלְמָא דְּאָתֵי.</p>\n<p>זַכָּאִין אִינּוּן דְּאִעְרָעוּ בְּהַאי מְקַטְרְגָא, וְזַכָּאִין אִינּוּן דְּלָא אִעֲרָעוּ בֵּיהּ. זַכָּאִין אִינּוּן דְּאִעְרָעוּ בֵּיהּ, וְאִשְׁתְּזִיבוּ מִנֵּיהּ, דִּבְגִינֵיהּ יָרְתִין כָּל אִינּוּן טָבִין, וְכָל אִינּוּן עִדּוּנִין, וְכָל אִינּוּן כִּסוּפִין דְּעָלְמָא דְּאָתֵי, דְּעָלֵיהּ כְּתִיב (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ.</p>\n<p>וְזַכָּאִין אִינּוּן דְּלָא אִעֲרָעוּ בֵּיהּ, דִּבְגִינֵיהּ יָרְתִין גֵּיהִנָּם, וְאִטָרָדּוּ מֵאֶרֶץ הַחַיִּים, דְּהָא אִינּוּן חַיָּיבַיָּא דְּאִעְרָעוּ בֵּיהּ, הֲווֹ צַיְיתִין לֵיהּ, וְאִתְמַשְׁכוּ אֲבַתְרֵיהּ. וְעַל דָּא אִית לְצַדִּיקַיָּא לְמֶחְזַק לֵיהּ טָבִין דְּהָא בְּגִינֵיהּ יָרְתִין כָּל אִינּוּן טָבָאן וְעִדּוּנִין וְכִסּוּפִין לְעָלְמָא דְּאָתֵי.</p>\n<p>תּוֹעַלְתָּא דְּהַאי מְקַטְרְגָא. כַּד חַיָּיבַיָּא צַיְיתִין לֵיהּ <Nonei></i>מַאי אִיהִי. אֶלָּא, אַף עַל גַּב דְּלֵית לֵיהּ תּוֹעַלְתָּא, פִּקּוּדָא דְּמָארֵיהּ אִיהוּ עָבִיד. וְתוּ, דְּהָא אִתְתָּקַּף בְּגִין הַאי, הוֹאִיל וְאִיהוּ רָע, אִתְתָּקַּף כַּד עָבִיד בִּישׁ. חַיָּיבָא לָא אִתְתָּקַּף עַד דְּקָטִיל בַּר נָשׁ, כֵּיוָן דְּקָטִיל בְּנֵי נָשָׁא, כְּדֵין אִתְתָּקַּף וְאִתְגַּבָּר בְּחֵילֵיהּ, וְאִית לֵיהּ נַיְיחָא. כַּךְ הַהוּא מְקַטְרְגָא, דְּאִתְקְרֵי מַלְאָךְ הַמָּוֶת, לָא אִתְגַּבָּר בְּחֵילֵיהּ, עַד דְּאַסְטֵי לִבְנִי נָשָׁא, וּמְקַטְרֵג לוֹן, וְקָטִיל לוֹן, כְּדֵין אִית לֵיהּ נַיְיחָא, וְאִתְתָּקַף וְאִתְגַּבָּר בְּחֵילֵיהּ.</p>\n<p>כְּמָה דְּאִתְתָּקַּף סִטְרָא דְּחַיִּים, כַּד בְּנֵי נָשָׁא טָבִין, וְיֶהֱכוּן בְּאֹרַח מֵישָׁר. אוּף הָכִי, הַאי מְקַטְרְגָא אִתְתָּקַּף וְאִתְגַּבָּר, כַּד חַיָּיבַיָּא צַיְיתִין לֵיהּ, וְשָׁלִיט עָלַיְיהוּ. רַחֲמָנָא לִישֵׁזְבָן. וְזַכָּאִין אִינּוּן דְּזַכָּאָן לְנַצְחָא לֵיהּ, וּלְאַכְפְּיָא לֵיהּ, לְמִזְכֵּי בְּגִינֵיהּ לְעָלְמָא דְּאָתֵי, וְאִתְתָּקַף בַּר נָשׁ בְּמַלְכָּא קַדִּישָׁא תָּדִיר, עַל דָּא וַדַּאי אִתְּמַר, (תהילים פ״ד:ו׳) אַשְׁרֵי אָדָם עוֹז לוֹ בָךְ מְסִלּוֹת בִּלְבָבָם, זַכָּאִין אִינּוּן בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי.</p>"],[9520011765,"<p>רַבִּי יוֹסִי וְרַבִּי יְהוּדָה וְרַבִּי חִיָּיא, הֲווֹ אַזְלֵי בְּאָרְחָא, פָּגַע בְּהוּ רִבִּי אֶלְעָזָר, עַד דְּחָמוּ לֵיהּ, נָחְתוּ מִן חֲמָרֵי כֻּלְּהוּ. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי אַנְפֵּי שְׁכִינְתָּא חֲמֵינָא, דְּהָא כַּד חָמֵי בַּר נָשׁ צַדִּיקַיָּא, אוֹ זַכָּאִין דִּי בְּדָרָא, וְאִעֲרַע בְּהוּ, וַדַּאי אִינּוּן אַנְפֵּי שְׁכִינְתָּא. וַאֲמַאי אִקְרוּן אַנְפֵּי שְׁכִינְתָּא. בְּגִין דִּשְׁכִינְתָּא אִסְתָּתָּרַת בְּגַּוַּויְיהוּ, אִיהִי בִּסְתִימוּ, וְאִינּוּן בְּאִתְגַּלְּיָא. בְּגִין דִּשְׁכִינְתָּא אִינּוּן דִּקְרִיבִין לָהּ, אִקְרוּן פָּנִים דִּילָהּ. וּמַאן אִינּוּן. אִינּוּן דְּאִיהִי אִתְתַּקְנַת בַּהֲדַיְיהוּ, לְאִתְחֲזָאָה לְגַבֵּי מַלְכָּא עִלָּאָה. וְהוֹאִיל וְאַתּוּן הָכָא, וַדַּאי שְׁכִינְתָּא אִתְתַּקְנַת עָלַיְיכוּ, וְאַתּוּן פָּנִים דִּילָהּ. (ס\"א ואערע בהו ודאי חמי אנפי שכינתא בגין דשכינתא אסתתר בגוייהו איהי בסתימו ואינון באתגלייא ואיהי אתתקנת בהדייהו לאתחזאה קמי מלכא והואיל ואתון הכא תלתא ודאי שכינתא אתתקנת עלייכו ושרייא בגווייכו)</p>"],[9520011766,"<p>פָּתַח וְאָמַר, (בראשית ל״ג:י״א) קַח נָא אֶת בִּרְכָתִי אֲשֶׁר הוּבָאת לָךָ וְגוֹ', כַּד חָמָא יַעֲקֹב לְסָמָאֵל, מְקַטְרְגָא בְּהַהוּא לֵילְיָא, חָמָא לֵיהּ בְּהַהוּא דִּיּוּקְנָא דְּעֵשָׂו, וְלָא אִשְׁתְּמוֹדָע בֵּיהּ עַד דְּסָלִיק צַפְרָא. כֵּיוָן דְּסָלִיק צַפְרָא, וְאַשְׁגַּח בֵּיהּ, חָמָא לֵיהּ בְּאַנְפִּין סְתִימִין וְאִתְגַּלְיָין. אִסְתָּכַּל בְּהַהוּא דִּיּוּקְנָא, דְּהֲוָה כְּדִּיוּקְנָא דְּעֵשָׂו, מִיַּד אַשְׁגַּח וְיָדַע דְּהֲוָה מְמָנָא דְּעֵשָׂו. אַתְקִיף בֵּיהּ מַה כְּתִיב, (בראשית ל״ב:כ״ז) וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר. וְחַבְרַיָּיא אִתְּעֲרוּ, דִּבְגִין דְּמָטָא זִמְנֵיהּ לְזַמְּרָא וּלְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא כִּי עָלָה הַשָּׁחַר.</p>\n<p>וְהָכָא אִית לְאִסְתַּכְּלָא, דְּוַדַּאי שֻׁלְטָנוּתָא דִּילֵיהּ לָאו אִיהוּ אֶלָּא בְּלֵילְיָא, גּוֹ חֲשׁוֹכָא, וְרָזָא דָּא (שיר השירים ג׳:ח׳) מִפַּחַד בַּלֵּילוֹת דָּא פַּחְדָּא דְּגֵיהִנָּם. וּמַה דְּאָמַר בַּלֵּילוֹת. רְצוֹנוֹ לאמָר אִיהוּ וְנוּקְבֵיהּ. וּבְגִינֵי כַּךְ לָא שַׁלִּיט אֶלָּא בְּלֵילְיָא.</p>\n<p>וְדָא דְּאָמַר וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר. מַאי כִּי עָלָה הַשָּׁחַר. בְּגִין דְּכַד אָתֵי צַפְרָא, וְאִתְעֲבָר שֻׁלְטָנוּ דְּחַשׁוֹכָא דְּלֵילְיָא, כְּדֵין עָאל אִיהוּ וְאֹכְלוּסֵיהּ בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא, דְּלִסְטַר צָפוֹן, עַד דְּעָאל לֵילְיָא, וְאִשְׁתְּרוּ כַּלְבֵּי, וְשַׁלְטֵי וּמְשַׁטְטֵי בְּלֵילְיָא, (ד\"א בעלמא) עַד דְּאָתֵי צַפְרָא. וְעַל דָּא הֲוָה דָּחִיק לוֹמַר, שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר, דְּהָא לָא שַׁלִּיט בִּימָמָא.</p>\n<p>כְּגַוְונָא דָּא גָּלוּתָא דְּיִשְׂרָאֵל, דְּאִיהוּ בְּלֵילְיָא, וְאִקְרֵי לַיְלָה. מַלְכָּא עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת חַיָּיבָא שַׁלְטָא עָלַיְיהוּ דְּיִשְׂרָאֵל, עַד דְּיֵיתֵי צַפְרָא וְיַנְהִיר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְיִתְעֲבָר שֻׁלְטָנֵיהוֹן, וְעַל דָּא כִּי עָלָה הַשָּׁחַר, דָּחִיק הֲוָה בִּידֵיהּ, וְתָשַׁשׁ חֵילֵיהּ, דְּהָא אִתְעַבָר לֵילְיָא וְעַל דָּא אִתְתָּקַּף יַעֲקֹב בֵּיהּ, וְחָמָא דִּיּוּקְנֵיהּ כְּדִּיוּקְנָא דְּעֵשָׂו, אֲבָל לָא בְּאִתְגַּלְּיָא כָּל כַּךְ. וּכְדֵין אוֹדֵי לֵיהּ עַל בִּרְכָּאן.</p>\n<p>מַה כְּתִיב לְבָתַר, (בראשית ל״ג:י׳) כִּי עַל כֵּן רָאִיתִי פָנֶיךָ כִּרְאוֹת פְּנֵי אֱלהִים וַתִּרְצֵנִי. דְּחָמָא בְּאִינּוּן אַנְפִּין דְּעֵשָׂו כְּדִּיוּקְנָא דְּאִתְחָזֵי לֵיהּ סָמָאֵ\"ל מַמָּשׁ, דְּהָא בְּכָל אֲתָר דְּבַּר נָשׁ אִתְקָשַּׁר, הָכִי אִתְחָזֵי בְּאַנְפּוֹי. וְאַתּוּן קַדִּישֵׁי עֶלְיוֹנִין שְׁכִינְתָּא בַּהֲדַיְיכוּ, וְאַנְפִּין דִּלְכוֹן כְּאִינּוּן אַנְפִּין דִּילָהּ, זַכָּאִין אַתוּן. אָמַר אִי אָרְחָא חֲדָא הֲוֵינָא אַזְלֵי בַּהֲדַיְיכוּ, הֲוֵינָא יַתְבֵי עִמְּכוֹן, הַשְּׁתָּא דְּאַתּוּן לְאָרְחַיְיכוּ, וַאֲנָא לְאָרְחִי, אִתְפְּרַשׁ מִנַּיְיכוּ בְּמִילֵּי <Nonei></i>דְּאוֹרַיְיתָא.</p>"],[9520011767,"<p>פָּתַח וְאָמַר (תהילים קכ״ז:א׳) שִׁיר הַמַּעֲלוֹת (וישלח קע\"ב ע\"א) לִשְׁלֹמֹה אִם יְיָ' לא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ אִם יְיָ' לא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. וְכִי שְׁלמֹה אָמַר תּוּשַׁבַּחְתָּא דָּא כַּד בָּנָה בֵּי מַקְדְּשָׁא. לָאו הָכִי, דְּהָא דָּוִד מַלְכָּא אֲמַר לֵיהּ בְּגִין שְׁלמֹה מַלְכָּא בְּרֵיהּ, כַּד אָתָא נָתָן לְגַבֵּיהּ, וְאֲמַר לֵיהּ עַל שְׁלֹמֹה דְּאִיהוּ יִבְנִי בֵּי מַקְדְּשָׁא. וּלְבָתַר דָּוִד מַלְכָּא אַחְזֵי לִשְׁלֹמֹה בְּרֵיהּ דִּיּוּקְנָא דְּבֵי מַקְדְּשָׁא. כֵּיוָן דְּחָמָא דָּוִד דִּיּוּקְנָא דְּבֵי מַקְדְּשָׁא, וְכָל תִּקּוּנוֹי, אָמַר שִׁירָתָא עַל שְׁלמֹה בְּרֵיהּ, וְאָמַר אִם יְיָ' לא יִבְנֶה בַיִת וְגוֹ'.</p>\n<p>דָּבָר אַחֵר שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה, לְמַלְכָּא דִּשְׁלָמָא דִּילֵיהּ. וְהַאי שִׁירָתָא אִיהוּ שִׁירָתָא וְתוּשְׁבַּחְתָּא עַל כָּל שְׁאַר שִׁירָתָא, וְשִׁירָתָא הֲדָא סַלְּקָא עַל כֻּלְּהוּ. אִם יְיָ' לא יִבְנְה בַיִת, דְּחָמָא דָּוִד מַלְכָּא, כָּל אִינּוּן עַמּוּדִין שִׁבְעָה, דְּהַאי בַּיִת קָאִים עָלַיְיהוּ, דְּאִינּוּן קַיְימֵי שׁוּרִין שׁוּרִין, לְמִבְנִי הַאי בַּיִת. לְעֵילָּא מְכֻּלְּהוּ קַיְּימָא מָארֵיהּ דְּבֵיתָא דְּאָזִיל עַל גַּבַּיְיהוּ, וְיָהִיב לוֹן חֵילָא וְתּוּקְפָּא, לְכָל חַד וְחַד כְּדְקָא יֵאוֹת.</p>\n<p>וְעַל דָּא אָמַר דָּוִד, אִי הַאי מַלְכָּא דִּשְׁלָמָא כֹּלָּא דִּילֵיהּ, דְּאִיהוּ מָארֵיהּ דְּבֵיתָא, לָא בָּנֵי לְהַאי בֵּיתָא, שָׁוְא עָמְלוּ בוֹנָיו בּוֹ, אִינּוּן (פי' עמודים) קַיָּימִין דְּקַיְימִין לְמִבְנִי עַל הַאי בֵּיתָא. אִם יְיָ' לֹא יִשְׁמָר עִיר, דָּא מַלְכָּא דִּשְׁלָמָא כֹּלָּא דִּילֵיהּ. שָׁוְא שָׁקַד שׁוֹמֵר, דָּא אִיהוּ חַד קַיָּימָא דְּעָלְמָא אִתְתָּקַּן עָלֵיהּ, וּמַנּוּ. צַדִּיק, דְּהָא אִיהוּ נָטִיר לָהּ לְהַאי עִיר.</p>\n<p>מַשְׁכְּנָא דְּעָבַד מֹשֶׁה, יְהוֹשֻׁעַ הֲוָה קָאִים תָּדִיר וְנָטִיר לֵיהּ, דְּהָא לֵית נְטִירוּ דִּילֵיהּ בַּר בֵּיהּ דְּאִקְרֵי נַעַר, דִּכְתִּיב, (שמות ל״ג:י״א) וּמְשָׁרַתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל. לְבָתַר הַאי מַשְׁכְּנָא לָא הֲוָה נָטִיר, אֶלָּא בְּגִין נַעַר אַחֲרָא, דִּכְתִּיב, (שמואל א ג׳:א׳) וְהַנַּעַר שְׁמוּאֵל מְשָׁרֵת, (והוה מסדר תמן) בְּגִין דְּלֵית נְטִירוּ דְּמַשְׁכְּנָא, אֶלָּא בְּנַעַר. (אבל בי מקדשא לאו הכי דלא נטירו דיליה אלא בקודשא בריך הוא דכתיב אם יי לא ישמור עיר שוא שקד שומר) וּמַאן אִיהוּ שׁוֹמֵר (ק\"א ע\"א) דָּא. הַהוּא דְּנָטִיר מַשְׁכְּנָא דְּאִקְרֵי הָכִי נַעַר מְטַטְרוֹ\"ן.</p>\n<p>אֲבָל אַתוּן קַדִּישֵׁי עֶלְיוֹנִין, לָאו נְטִירוּ דִּלְכוֹן כִּנְטִירוּ דְּמַשְׁכְּנָא, אֶלָּא נְטִירוּ דִּלְכוֹן כִּנְטִירוּ דְּבֵי מַקְדְּשָׁא, קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, דִּכְתִּיב אִם יְיָ' לא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר, דְּהָא בְּכָל זִמְנָא דְּצַדִּיקַיָּא אַזְלֵי בְּאָרְחָא, קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן תָּדִיר, דִּכְתִּיב, (תהילים קכ״א:ח׳) יְיָ' יִשְׁמָר צֵאתְךָ וּבוֹאֶךָ.</p>\n<p>אַזְלוּ אֲבַתְרֵיהּ, וְאוֹזְפוּהוּ תְּלַת מִלִּין, וְאָהַדְרוּ לְאָרְחַיְיהוּ קָרוּ עָלֵיהּ, (תהילים צ״א:י״א-י״ב) כִּי מַלְאָכָיו (ויקרא רס\"ב ע\"א) יְצַוֶּה לָךָ לִשְׁמָרְךָ בְּכָל דְּרָכֶיךָ, עַל כַּפַּיִם יִשָּׂאוּנְךָ וְגוֹ'. (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְאִמֶּךָ וְתָגֵל יוֹלַדְתֶּךָ.</p>"],[9520011768,"<p>(שמות כ״ו:א׳) וְאֶת הַמִּשְׁכָּן תַּעֲשֶׂה עֶשֶׂר יְרִיעֹת וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (משלי י״ד:כ״ח) בְּרָב עַם הַדְרַת מֶלֶךְ וּבְאֶפֶס לְאֹם מְחִתַּת רָזוֹן. בְּרָב עָם הַדְרַת מֶלֶךְ, אִלֵּין אִינּוּן יִשְׂרָאֵל, דִּכְתִּיב בְּהוּ (דברים ז׳:ו׳) כִּי עַם קָדוֹשׁ אַתָּה לַיְיָ' אֱלֹהֶיךָ. וְאִינּוּן עַמָּא דְּסַלְּקִין לְכַמָּה אַלְפִין, וּלְכַמָה רִבְּוָון, וְכַד אִינּוּן סַגִּיאִין בְּחוּשְׁבָּנֵיהוֹן, יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ. דְּהָא עִלָּאִין וְתַתָּאִין מְשַׁבְּחָן שְׁמֵיהּ דְּמַלְכָּא עִלָּאָה, וּמְשַׁבְּחָן לֵיהּ בְּגִין עַמָּא קַדִּישָׁא דָּא. הֲדָא הוּא דִכְתִיב, (דברים ד׳:ו׳) רַק עַם חָכָם וְנָבוֹן הַגּוֹי הַגָּדוֹל הַזֶּה.</p>\n<p>וְאִי תֵּימָא, הָא כְּתִיב, (דברים ז׳:ז׳) כִּי אַתֶּם הַמְעַט מִכָּל הָעַמִּים, אֶלָּא, מִכָּל הָעַמִּים וַדַּאי, אֲבָל מֵעַמָּא חַד יַתִּיר סַגִּיאִין אִינּוּן. דְּהָא לֵית עַמָּא בְּכָל עָלְמָא רַב וְסַגִּי כְּיִשְׂרָאֵל. וְאִי תֵּימָא הָא בְּנֵי יִשְׁמָעֵאל, וְהָא בְּנֵי אֱדוֹם, הָא כַּמָּה אִינּוּן. וַדַּאי הָכִי סַגִּיאִין אִינּוּן, אֲבָל כָּל שְׁאַר עַמִּין כֻּלְּהוּ מִתְעָרְבֵי אִלֵּין בְּאִלֵּין, בְּנִין אִית לְעָם דָּא, בְּעָם דָּא, וּלְאִלֵּין בְּנִין בְּעָם אַחֲרָא, וְאִלֵּין בְּאַחֲרָא. וּבְּגִין כָּךְ לֵית עַמָּא בְּכָל עָלְמָא, רַב סַגִּי כְּיִשְׂרָאֵל, עַמָּא בְּרִירָא וִיחִידָאָה, אִלֵּין בְּאִלֵּין, בְּלָא עִרְבּוּבְיָא אַחֲרָא כְּלַל, דִּכְתִּיב כִּי עַם קָדוֹשׁ אַתָּה לַיְיָ' אֱלהֶיךָ, וּבְךָ בָּחַר יְיָ', וְעַל דָּא בְּרָב עָם הַדְרַת מֶלֶךְ, הִדּוּרָא אִיהוּ דְּמַלְכָּא עִלָּאָה קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>תּוּ בְּזִמְנָא <Nonei></i>דְּקוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְבֵי כְּנִישְׁתָּא, (דאיהו מקדש מעט) וְכָל עַמָּא אַתְיָין כַּחֲדָא, וּמְצַלָאן, וְאוֹדָן, וּמְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, כְּדֵין הִדּוּרָא דְּמֶלֶךְ אִיהוּ, דְּמֶלֶךְ סְתָם דָּא מַלְכָּא קַדִּישָׁא. (ד\"א משיחא) דְּאִתְתָּקַּן בִּשְׁפִירוּ וּבְתִקּוּנָא לְסַלְּקָא לְעֵילָּא.</p>\n<p>וּבְאֶפֶס לְאֹם מְחִתַּת רָזוֹן, וְכַד אִיהוּ אַקְדִּים לְבֵי כְּנִישְׁתָּא, וְעַמָּא לָא אַתְיָין לְצַלָּאָה וּלְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, כְּדֵין כָּל הַהוּא שֻׁלְטָנוּתָא דִּלְעֵילָּא, וְכָל אִינּוּן מְמָנָן וּמַשִּׁרְיָין עִלָּאִין, כֻּלְּהוּ אִתְבָּרוּ (ס\"א אתעברו) מֵהַהוּא עִלּוּיָא דְּמִתַּתְקְנֵי בְּתִקּוּנֵי הַהוּא מֶלֶךְ.</p>\n<p>מַאי טַעְמָא. בְּגִין דִּבְהַהִיא שַׁעֲתָּא, דְּיִשְׂרָאֵל לְתַתָּא קָא מְסַדְּרֵי צְלוֹתְהוֹן וּבָעוּתְהוֹן, וּמְשַׁבְּחָן לְמַלְכָּא עִלָּאָה. כָּל אִינּוּן מַשִּׁרְיָין עִלָּאִין, מְסַדְּרִין שְׁבָחִין, וּמְתַּתְקְנָן בְּהַהוּא תִּקּוּנָא קַדִּישָׁא, בְּגִין דְּמַשִּׁרְיָין עִלָּאִין כֻּלְּהוּ חֲבֵרִין אִינּוּן בְּיִשְׂרָאֵל לְתַתָּא, לְשַׁבְּחָא לְקוּדְשָׁא בְּרִיךְ הוּא כַּחֲדָא, לְמֶהוֵי סִלּוּקָא דְּקוּדְשָׁא בְּרִיךְ הוּא עֵילָּא וְתַתָּא כַּחֲדָא.</p>\n<p>וְכַד אִינּוּן מִזְדַּמְּנָן לְמֶהֱוֵי חֲבֵרִים בְּהוּ בְּיִשְׂרָאֵל, וְיִשְׂרָאֵל לְתַתָּא לָא אַתְיָין לְסַדְּרָא צְלוֹתְהוֹן וּבָעוּתְהוֹן וּלְשַׁבְּחָא לְמָארֵיהוֹן, כֻּלְּהוּ מַשִּׁרְיָין קַדִּישִׁין, שֻׁלְטָנוּתָא עִלָּאָה אִתְבָּרוּ (אתעברו) מִתִּקּוּנֵיהוֹן, דְּהָא לָא סַלְּקִין בְּסִלוּקָא, וְלָא יַכְלִין לְשַׁבְּחָא לְמָארֵיהוֹן כְּדְקָא יֵאוֹת. בְּגִין דִּשְׁבָחֵי דְּקוּדְשָׁא בְּרִיךְ הוּא, אִצְטְרִיךְ לְמֶהוֵי כַּחֲדָא עֵילָּא וְתַתָּא, עִלָּאִין וְתַתָּאִין בְּשַׁעֲתָּא חֲדָא, וְעַל דָּא מְחִתַּת רָזוֹן וְלָא מְחִתַּת מֶלֶךְ.</p>\n<p>וַאֲפִילּוּ דְּלָא אַסְגִּיאוּ בְּבֵי כְּנִישְׁתָּא, אֶלָּא עֲשָׂרָה, בְּאִינּוּן עֲשָׂרָה מִזְדַּמְנָן מַשִּׁרְיָין עִלָּאִין, לְמֶהוֵי עִמְּהוֹן חֲבֵרִים. מַאי טַעְמָא בְּגִין דְּכָל תִּקּוּנֵי דְּהַהוּא מֶלֶךְ, אִינּוּן בַּעֲשָׂרָה, וְעַל דָּא דַּי בַּעֲשָׂרָה, אִי לָאו אִינּוּן יַתִּיר.</p>"],[9520011769,"<p>וְתָּא חֲזֵי בַּמִשְׁכָּן מָה כְּתִיב, (שמות כ״ו:א׳) וְאֶת הַמִּשְׁכָּן תַּעֲשֶׂה עֶשֶׂר יְרִיעוֹת, עֶשֶׂר: בְּגִין דְּתִקּוּנָא דְּמַשְׁכְּנָא, (נ\"א דשכינתא) בַּעֲשָׂרָה אִיהוּ, לְמֶהֱוֵי כְּדְקָא יֵאוֹת. עֶשֶׂר, מַאי טַעְמָא עֶשֶׂר, וְלָא עֲשָׂרָה. אֶלָּא עֶשֶׂר, בְּכָל אֲתָר אִיהוּ בְּלָא שְׁכִינְתָּא, דְּלָאו אִיהִי בְּחוּשְׁבָּנָא כְּגַוְונָא דָּא (מלכים א ז׳:כ״ה) עוֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר, שְׁכִינְתָּא לָאו אִיהִי בְּחוּשְׁבָּנָא, דְּהָא אִיהִי קַיְּימָא לְעֵילָּא, דִּכְתִּיב, (מלכים א ז׳:כ״ה) וְהַיָּם עֲלֵיהֶם מִלְמָעְלָה. וּבְאִלֵּין דּוּכְתֵּי דִּרְמִיזֵי לְרָזָא דִּלְעֵילָּא דְּחָסֵר מִנְּהוֹן, (ס\"א ה') הָא שְׁכִינְתָּא יַתִּיר עַל הַהוּא חוּשְׁבָּנָא, דְּלָאו אִיהִי בְּחוּשְׁבָּנָא.</p>\n<p>לְסִטְרָא אַחֲרָא, יָהֲבֵי חוּשְׁבָּנָא יַתִּיר, וְאִיהִי בְּמִנְיָינָא בִּגְרִיעוּ, (ד\"א לא תימא חושבנא יתיר אלא תוספת את וחושבנא בגריעו) כְּגוֹן עַשְׁתֵּי, וְהָא אוּקְמוּהָ. וּבְכָל אֲתָר דְּאַתְוָון אִתּוֹסְפָן, כְּגַוְונָא דָּא, אִיהוּ לִגְּרִיעוּתָא. כְּגוֹן (שמואל ב י״ג:כ׳) הַאֲמִינוֹן אָחִיךְ, דְּסַגְיָא אַמְנוֹן. וּבְסִטְרָא דִּקְדוּשָׁא, גָּרַע אָת וְאִיהוּ תּוֹסֶפֶת.</p>"],[9520011770,"<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים ק״ד:ב׳-ג׳) עוֹטֶה אוֹר כַּשַּׂלְמָה נוֹטֶה שָׁמַיִם כַּיְרִיעָה. הַאי קְרָא אוּקְמוּהָ, דְּכַד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, (פנחס רמ\"ה ע\"ב) אִתְעֲטָף בְּהַהוּא אוֹר קַדְמָאָה, וּבָרָא בֵּיהּ שָׁמַיִם.</p>\n<p>וְתָּא חֲזֵי, אוֹר וְחֹשֶׁךְ (ד\"א לאו) כַּחֲדָא הֲווֹ. אוֹר מִסִּטְרָא דִּימִינָא, וְחֹשֶׁךְ מִסִּטְרָא דִּשְׂמָאלָא. מַאי עֲבַד קוּדְשָׁא בְּרִיךְ הוּא, שִׁתֵּף לוֹן כַּחֲדָא, וּבָרָא מִנְהוֹן שָׁמַיִם. מַאי שָׁמַיִם. אֵשׁ וּמַיִם. שִׁתְפָן כַּחֲדָא, וְעָבִיד שְׁלָם בֵּינַיְיהוּ.</p>\n<p>וְכַד אִתְכְּלִילוּ כַּחֲדָא, וּמָתַח לוֹן, כַּיְרִיעָה מָתַח לוֹן, וְעָבִיד מִנְהוֹן אָת ו' וְדָא אִקְרֵי יְרִיעָה. יְרִיעוֹת, דְּהָא אָת דָּא אִתְפָּשִׁיט מִנֵּיהּ נְהִירוּ, וְאִתְעָבִידוּ יְרִיעוֹת, הֲדָא הוּא דִכְתִיב וְאֶת הַמִּשְׁכָּן תַּעֲשֶׂה עֶשֶׂר יְרִיעוֹת.</p>\n<p>וְשֶׁבַע רְקִיעִין אִינּוּן מְתִיחִין, גְּנִיזִין בִּגְנִיזוּ עִלָּאָה, כְּמָה דְּאוּקְמוּהָ. וְחַד רְקִיעָא דְּקַיְּימָא עָלַיְיהוּ, וְהַהוּא רָקִיעַ לֵית בֵּיהּ גּוָֹון, וְלֵית לֵיהּ אֲתָר בְּאִתְגַּלְּיָא וְלָא קַיָּימָא לְאִסְתַּכְּלָא בֵּיהּ, (ס\"א אלא בסוכלתנו) וְהַאי רָקִיעַ אִיהוּ גָּנִיז, וְנָהִיר לְכֻלְּהוּ, וְנָטִיל לוֹן בְּמַטְלָנֵיהוֹן, כָּל חַד וְחַד כַּדְקָא חֲזִי לֵיהּ. אֶלָּא קַיָּימָא בְּסוּכְלְתָנוּ.</p>\n<p>מֵהַאי רָקִיעַ וּלְהָלְאָה, לֵית מַאן דְּיֵדַע וְיִשְׁגַח, וְאִית לֵיהּ לְבַר נָשׁ לְמִסְתַּם פּוּמֵיהּ, וּדְלָא לְמַלְּלָא וּלְאִסְתַּכְּלָא בְּסוּכְלְתָנוּ. מַאן דְּיִסְתָּכַּל אַהְדָּר לַאֲחוֹרָא, דְּלֵית מַאן דְּיָכִיל לְמִנְדַּע.</p>\n<p>עֶשֶׂר יְרִיעוֹת אִינּוּן, דְּאִינּוּן עֲשָׂרָה רְקִיעִין. וּמַאן אִינּוּן יְרִיעוֹת דְּמַשְׁכְּנָא דְּאִינּוּן עֶשֶׂר. וְקַיְימָן לְמִנְדַּע לְחַכִּימֵי לִבָּא. מַאן דְּיִנְדַּע בְּהוּ, אִסְתָּכַל בְּחָכְמְתָא סַגְיָא, וּבְרָזִין דְּעָלְמָא, וְאִסְתָּכַּל <Nonei></i>לְעֵילָּא בְּהַהוּא אֲתָר, דְּכָל חַד וְחַד אִתְדַּבָּק בֵּיהּ, בַּר תְּרֵין אִינּוּן דְּקַיְימָן בִּימִינָא וּבִשְׂמָאלָא, וְאִינּוּן גְּנִיזִין בַּהֲדֵי שְׁכִינְתָּא.</p>\n<p>רַבִּי יוֹסִי אָמַר תֵּשַׁע רְקִיעִין אִינּוּן, וּשְׁכִינְתָּא אִיהִי עֲשִׁירָאָה. דְּאִי תֵּימָא בְּגִין דִּכְתִּיב עֶשֶׂר, בַּר מִשְּׁכִינְתָּא אִיהוּ. אִי הָכִי, שְׁכִינְתָּא חַד סָרֵי אִיהִי דְּקַיְּימָא עַל עֶשֶׂר. אֶלָּא וַדַּאי תֵּשַׁע אִינּוּן, וְאִינּוּן תֵּשַׁע יוֹמִין שְׁבֵּין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים, וְאִיהִי עֲשִׁירָאָה. כְּגַוְונָא דָּא, מִשְׁכָּן אִיהוּ עֶשֶׂר יְרִיעוֹת.</p>\n<p>אִינּוּן עֶשֶׂר רְקִיעִין רָזָא דְּרָזִין דְּלָא אִתְמְסָר בַּר לְאִינּוּן דְּיַדְעֵי חָכְמְתָא, וְכֹלָּא אִיהוּ בְּרָזִין דְּבוּצִינָא קַדִּישָׁא, דְּאִיהוּ גַּלֵּי רָזָא דְּכָל רְקִיעָא וּרְקִיעָא, וְאִינּוּן שַׁמָּשִׁין דִּמְשַׁמְשֵׁי בְּכָל חַד וְחַד. שֶׁבַע רְקִיעִין אִינּוּן לְעֵילָּא, שֶׁבַע רְקִיעִין אִינּוּן לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא. שֶׁבַע רְקִיעִין אִינּוּן, דְּבְּהוּ כֹּכָבַיָא וּמַזָּלֵי לְאַנְהָגָא עָלְמָא דָּא כְּפוּם אָרְחֵיהּ, כְּמָה דְּאִצְטְרִיךְ לֵיהּ.</p>"],[9520011771,"<p>בְּכֻלְּהוּ שְׁבִיעָאָה עָדִיף, בַּר תְּמִינָאָה, דְּקָא מַדְבַּר לְכֻלְּהוּ, וְקַיְּימָא עַל כֻּלְּהוּ. כְּתִיב (תהילים ס״ח:ה׳) סֹלּוּ לָרוֹכֵב בָּעֲרָבוֹת, מַאן רוֹכֵב בָּעֲרָבוֹת, וּמַאן אִינּוּן עֲרָבוֹת. אֶלָּא, עֲרָבוֹת דָּא רְקִיעָא שְׁבִיעָאָה, אֲמַאי אִתְקְרֵי עֲרָבוֹת. עַל דְּאִיהוּ כָּלִיל מֵאֶשָּׁא וּמַיָא כַּחֲדָא, וּמִסִּטְרָא דְּדָרוֹם, וּמִסִּטְרָא דְּצָפוֹן, וְאִיהוּ מְעוּרָב מִתְּרֵין סִטְרִין.</p>\n<p>וְאִי תֵּימָא, אִי הָכִי, שְׁתֵּי עֲרָבוֹת דְּקָא מִתְחַבְּרָן בְּלוּלָב, וְתָנֵינָן עֲרָבוֹת, הֲדָא הוּא דִּכְתִּיב סֹלּוּ לָרוֹכֵב בָּעֲרָבוֹת. אִי הָכִי, מַאן יָהִיב יַרְכִּין בְּגוּפָא, אוֹ גּוּפָא בְּיַרְכִּין, דְּהָא דָּא עָבִיד פֵּרִין וְאֵיבִין, וְדָא (קס\"ט ע\"ב) לָא עָבִיד פֵּרִין וְאֵיבִין.</p>\n<p>אֶלָּא, וַדַּאי כֹּלָּא הוּא רָזָא דַּעֲרָבוֹת דְּבַלוּלָב, אִינּוּן עֲרָבוֹת דְּבַלוּלָב, חַד אֵשׁ, וְחַד מַיִם. בְּרָזָא דָּא דְּכֻלְּהוּ, וְאִיהוּ שְׁבִיעָאָה אִיהוּ אֵשׁ וּמַיִם כָּלִיל כַּחֲדָא, בְּרָזָא חֲדָא, וּבְגִין דַּעֲרָבוֹת אִיהוּ רָזָא כְּלָלָא דְּכֻלְּהוּ שִׁית אַחֲרָנִין, אִיהוּ רָזָא דִּרְתִיכָא עִלָּאָה, וְקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהַאי רְקִיעָ, יַתִּיר מְכֻּלְּהוּ רְקִיעִין, וְתִיאוּבְתֵיהּ תָּדִיר לְאַתְקְנָא לְהַהוּא רְקִיעָא, בִּשְׁפִירוּ עִלָּאָה. וְעַל דָּא, סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת לְהַהוּא דְּרֹכֵב בָּעֲרָבוֹת. וּמַאן אִיהוּ. הַהוּא רָקִיעַ טָמִיר וְגָנִיז, דְּקַיְּימָא עַל גַּבֵּי חֵיוָתָא, דְּאִיהוּ רֹכֵב בָּעֲרָבוֹת.</p>\n<p>וְעִלְזוּ (ק\"ע ע\"ב) לְפָנָיו. מִלְּפָנָיו לָא כְּתִיב, אֶלָּא לְפָנָיו, דְּהָא לֵית מַאן דְּיִנְדַּע בֵּיהּ כְּלוּם. אֲבָל לְפָנָיו, מַאן דְּעָיִיל לְקָמֵיהּ דְּהַאי רְקִיעָ, אִצְטְרִיךְ לְמֵיעַל בְּחֶדְוָה, וְלָא בַּעֲצִיבוּ כְּלַל, בְּגִין דְּהַאי רְקִיעָא גָּרִים, דְּתַמָּן לָא שַׁרְיָא עֲצִיבוּ וְרוּגְזָא כְּלַל, דְּהָא תַּמָּן כֹּלָּא אִיהוּ בְּחֶדְוָה.</p>\n<p>וְעַל דָּא, כֹּהֵן גָּדוֹל דְּקַיְּימָא לְקָמֵיהּ, לָא הֲוָה עָאל לְבֵי קוּדְשָׁא, בַּר בְּחֶדְוָה, וּלְאַחֲזָאָה חֶדְוָה, דְּהָא אַתְרָא גָּרִים. וְעַל דָּא כְּתִיב, (תהילים ק׳:ב׳) עִבְדוּ אֶת יְיָ' בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. דְּהָא אִצְטְרִיךְ דְּלָא לְאַחֲזָאָה בָּהּ עֲצִיבוּ.</p>\n<p>וְאִי תֵּימָא, אִי הָכִי, הַאי מַאן דְּאִיהוּ בְּצַעֲרָא וּבְדוֹחְקָא, דְּלָא יָכִיל לְמֶחְדֵּי לִבֵּיהּ, וּמִגּוֹ דּוֹחֲקֵיהּ אִית לֵיהּ לְמִתְבַּע רַחֲמִין, קָמֵי מַלְכָּא עִלָּאָה, אִי הָכִי, לָא יִצְלֵי צְלוֹתָא כְּלַל, וְלָא יִיִעוּל בַּעֲצִיבוּ כְּלַל, דְּהָא לָא יָכִיל לְמֵחדֵי לִבֵּיהּ, וּלְאַעֲלָא קָמֵיהּ בְּחֶדְוָה, מַאי תִּקּוּנָא אִית לֵיהּ לְהַאי בַּר נָשׁ.</p>\n<p>אֶלָּא וַדַּאי הָא תָּנֵינָן, כָּל תַּרְעִין נִנְעָלוּ וְאַסְגִּירוּ, וְתַרְעִין דִּדְמָעִין לָא אַסְגִּירוּ, וְלֵית דִּמְעָה אֶלָּא מִגּוֹ צַעֲרָא וְעָצִיבוּ. וְכָל אִינּוּן דִּמְמָנָן עַל אִינּוּן תַּרְעִין, כֻּלְּהוּ מְתָבְּרִין גְּזִּיזִין וּמַנְעוּלִין, וְעַיְילִין אִינּוּן דִּמְעִין, וְהַהִיא צְלוֹתָא עָאלַת קָמֵי מַלְכָּא קַדִּישָׁא.</p>\n<p>כְּדֵין הַהוּא אֲתָר אִית לֵיהּ דּוֹחֲקָא, מֵהַהוּא עֲצִיבוּ וְדוֹחֲקָא דְּהַהוּא בַּר נָשׁ, כְּמָה דְאַתְּ אָמֵר (ישעיה סג) בְּכָל צָרָתָם לא צָר. תִּיאוּבְתֵּיהּ דְּהַהוּא עָלְמָא עִלָּאָה, לְגַבֵּי הַאי אֲתָר, כִּדְכוּרָא דְּתִיאוּבְתֵּיה תָּדִיר לְגַבָּהּ דְּנוּקְבָּא. כַּד מַלְכָּא עָאל לְגַבֵּי מַטְרוֹנִיתָא, אַשְׁכַּח לָהּ בַּעֲצִיבוּ, כְּדֵין כָּל מָה דְּאִיהִי בָּעָאת, בִּידָהָא אִתְמְסָר, וְהַהוּא בַּר נָשׁ, וְהַהִיא צְלוֹתָא, לָא אַהְדָּר בְּרֵיקָנַיָּא, וְקוּדְשָׁא בְּרִיךְ הוּא חַיִּיס <Nonei></i>עָלֵיהּ. זַכָּאָה חוּלָקֵיהּ דְּהַהוּא בַּר נָשׁ, דְּאוֹשִׁיד דִּמְעִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בִּצְלוֹתֵיהּ.</p>\n<p>כְּגַוְונָא דָּא בְּשַׁבָּת, מַאן דְּיָתִיב בְּתַעֲנִיתָא בְּשַׁבָּת, מִגּוֹ צַעְרֵיהּ אַחְזֵי עֲצִיבָא, וּבְשַׁבָּת שַׁלְטָא הַהוּא רְקִיעָא עִלָּאָה, הַהוּא דְּאִתְחָזֵי בְּחֶדְוָה, וְאִיהוּ חֶדְוָה וְחַדֵּי לְכֹלָּא. הַהוּא דְּיָתִיב בַּעֲצִיבוּ, בְּגִין דְּאִיהוּ שַׁלְטָא, אַפִּיק לְהַהוּא בַּר נָשׁ מֵהַהוּא עוֹנְשָׁא דְּאִתְגְּזַר עָלֵיהּ, וְהָא אִתְּמַר, סֹלּוּ: הָבוּ יְקָר, וְרוֹמְמוּ לְהַהוּא דְּרוֹכֵב בָּעֲרָבוֹת, דְּאִיהוּ חֶדְוָה וְחַדֵּי כֹּלָּא, רְקִיעָא עַל גַּבֵּי חֵיוָתָא בְּיָ\"הּ שְׁמוֹ וַדַּאי, דְּהָא בְּהַהוּא אֲתָר שְׁמָא דָּא אִתְכְּלִיל. וְעִלְזוּ לְפָנָיו, בְּגִין דְּלָא אִצְטְרִיךְ לְאַחֲזָאָה קָמֵיהּ עֲצִיבוּ, כְּמָה דְּאִתְּמַר.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, הַאי קְרָא, הָכִי אִצְטְרִיךְ לְמֵימַר, סֹלּוּ לָרוֹכֵב עַל עֲרָבוֹת, מַאי בָּעֲרָבוֹת. בְּיָהּ שְׁמוֹ, בְּיָהּ הוּא מִבָּעֵי לֵיהּ, מַאי שְׁמוֹ. אֶלָּא הַאי קְרָא, עַל סְתִימָא דְּכָל סְתִימִין, עַתִּיקָא דְּכָל עַתִּיקִין אִתְּמַר. הַהוּא דְּלָא אִתְגַּלְיָא, וְלָא אִתְיְדַע כְּלַל, דְּאִיהוּ רוֹכֵב בָּעֲרָבוֹת. וְאִי תֵּימָא, דְּאִיהוּ אַתְיָא וְרָכִיב בֵּיהּ, אִי הָכִי, אַף עַל גַּב דְּסָתִים הוּא בְּאֲתָר דָּא קַיְּימָא לְאִתְגַּלְיָא.</p>\n<p>אֶלָּא סוֹלּוּ לָרוֹכֵב בָּעֲרָבוֹת, דָּא אִיהוּ עַתִּיקָא דְּכָל עַתִּיקִין, סְתִימָא דְּכָל סְתִימִין, דְּלָא יְדִיעַ. וּבַמֶּה אִיהוּ רוֹכֵב, בַּעֲרָבוֹת, בְּיָ\"הּ, דְּאִיהוּ רָזָא קַדְמָאָה דְּנָפִיק קַמֵּיהּ (ד\"א מניה) וְדָא אִיהוּ שְׁמֵיהּ, מֵהַהוּא סְתִימָא, דְּלָא יְדִיעַ, שְׁמָא (ויקרא כ\"ט) דִּילֵיהּ הוּא יָ\"הּ. לָאו דְּאִיהוּ הוּא, אֶלָּא אִיהוּ הוּא, בְּגִין דְּהַהוּא פָּרוֹכְתָּא (ויקרא קכ\"ח) דְּאִתְפָּרְסָא וְנָפִיק מִקָּמֵיהּ. אֲבָל הַאי פָּרוֹכְתָּא אִיהוּ שְׁמוֹ, וְדָא אִיהוּ רְתִיכָא דִּילֵיהּ, וְלָא אִתְיְדַע כְּלַל.</p>\n<p>וְדָא אִיהוּ שְׁמוֹ הַגָּדוֹל, בְּגִין דְּאִית שְׁמֵיהּ דְּלָאו אִיהוּ כָּל כַּךְ גָּדוֹל, כְּהַאי אַף עַל גַּב דְּאִית בֵּיהּ תּוֹסֶפֶת אַתְוָון. דָּא אִיהוּ שְׁמָא רַבָּא, וְעַל דָּא בְּהַאי שְׁמָא, אֲנָן מְפִיקִין אָמֵן, דְּאִיהוּ מִנֵּיהּ. בְּהַאי אַזְלָא אָמֵן בְּכָל זִמְנָא, וּבִשְׁמָא אַחֲרָא לָאו הָכִי.</p>\n<p>אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ, דְּכַד הַאי שְׁמָא אִתְתָּקַּן, כֹּלָּא אִיהוּ בִּשְׁלִימוּ, וְכָל עָלְמִין חַדָּאן בְּחִדוּ. בְּהַאי שְׁמָא, כְּלִילָן עִלָּאִין וְתַתָּאִין. בְּהַאי שְׁמָא, כְּלִילָן שִׁית מֵאָה וּתְלֵיסָר פִּקּוּדֵי אוֹרַיְיתָא, דְּאִינּוּן כְּלָלָא דְּכָל רָזִין עִלָּאִין וְתַתָּאִין. כְּלָלָא דְּעָלְמָא דִּדְכוּרָא לְעֵילָּא, וּכְלָלָא דְּעָלְמָא דְּנוּקְבָּא לְתַתָּא.</p>\n<p>וְכֻלְּהוּ פִּקּוּדִין, כֻּלְּהוּ שַׁיְיפִין וְאֵבָרִין, לְאִתְחֲזָאָה בְּהוּ רָזָא דִּמְהֵימְנוּתָא. מַאן דְּלָא יַשְׁגַּח וְלָא אִסְתָּכַּל בְּרָזִין דְּפִקוּדֵי אוֹרַיְיתָא, לָא יְדַע, וְלָא אִסְתָּכַל, הֵיךְ מְתַּתְקְנָן שַׁיְיפִין בְּרָזָא עִלָּאָה. שַׁיְיפִין דְּגוּפָא כֻּלְּהוּ, מִתְתַּקְּנָן עַל רָזָא דְּפִקוּדֵי אוֹרַיְיתָא, וְאַף עַל גַּב דְּאִית שַׁיְיפִין, דְּאִינּוּן רַבְרְבִין וְעִלָּאִין, כֻּלְּהוּ זְעִירִין וְרַבְרְבִין, אִי אִתְנְטִיל חַד מִנַּיְיהוּ, אֲפִילּוּ זְעִירָא דְּבַר נָשׁ, אִקְרֵי מָארֵיהּ דְּמוּמָא, כָּל שֶׁכֵּן וְכָּל שֶׁכֵּן הַהוּא דְּגָרַע אֲפִילּוּ חַד פִּקּוּדָא מֵאִינּוּן פִּקּוּדֵי אוֹרַיְיתָא, דְּאָטִיל מוּמָא בְּאֲתָר דְּלָא אִצְטְרִיךְ.</p>\n<p>תָּא חֲזִי, מַה כְּתִיב, (בראשית ב׳:ט״ו) וַיִּקַּח יְיָ' אֱלֹהִים אֶת הָאָדָם וַיַּנִּיחֵהוּ בְגַן עֵדֶן לְעָבְדָהּ וּלְשָׁמְרָהּ. וְתָנֵינָן, לְעָבְדָהּ וּלְשָׁמְרָהּ אִלֵּין קָרְבָּנִין, וְכֹלָּא חַד. אֲבָל דָּא רָזָא דְּפִקוּדֵי אוֹרַיְיתָא, לְעָבְדָהּ: אִלֵּין רמ\"ח שַׁיְיפִין עִלָּאִין. וּלְשָׁמְרָהּ: אִלֵּין תְּלָת מְאָה וְשִׁתִּין וְחָמֵשׁ שַׁיְיפִין תַּתָּאִין. אִלֵּין עִלָּאִין דְּזָכוֹר. וְאִלֵּין תַּתָּאִין דְּשָׁמוֹר, וְכֹלָּא חַד.</p>\n<p>זַכָּאָה אִיהוּ מַאן דְּזָכֵי לְאַשְׁלָמָא לוֹן. פִּקּוּדִין דְּאוֹרַיְיתָא, גָּרִים לְבַר נָשׁ לְאַשְׁלָמָא רוּחֵיהּ וְנִשְׁמָתֵיהּ בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי. אוֹרַיְיתָא מְזַכָּה לְבַר נָשׁ, לְאַחְסְנָא תְּרֵין עָלְמִין, עָלְמָא דָּא וְעָלְמָא דְּאָתֵי. כָּל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, אִשְׁתְּדַּל בַּחַיִּים. חַיִּים בְּהַאי עָלְמָא, וְחַיִּים בְּעָלְמָא דְּאָתֵי. אִשְׁתְּזִיב מִכָּל עוֹנָשִׁין בִּישִׁין, דְּלָא יַכְלִין לְשַׁלְּטָאָה עָלֵיהּ. אִי בְּאִשְׁתַּדְּלוּתָא הָכִי. כָּל שֶׁכֵּן מַאן דְּעָבִיד עוֹבָדָא.</p>\n<p>רַבִּי חִיָּיא וְרִבִּי אַבָּא, שָׁרוּ בְּבֵי אוּשְׁפִּיזַיְיהוּ, קָמוּ בְּפַלְגוּת לֵילְיָא, <Nonei></i>לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא. בְּרַתֵיהּ דְּאוּשְׁפִיזָא, קָמַת וְאַנְהִירַת לוֹן שַׁרְגָּא, וּלְבָתַר קַיְּימַת אֲבַתְרַיְיהוּ לְמִשְׁמַע מִלִּין דְּאוֹרַיְיתָא.</p>"],[9520011772,"<p>פָּתַח רַבִּי יוֹסִי וְאָמַר, (משלי ו׳:כ״ג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. כִּי נִר מִצְוָה, כָּל מַאן דְּאִשְׁתָּדַּל בְּהַאי עָלְמָא, בְּאִינּוּן פִּקּוּדִין דְּאוֹרַיְיתָא, אִתְסָדַר קָמֵיהּ בְּכָל פִּקּוּדָא וּפִקּוּדָא חַד שַׁרְגָּא, לְאַנְהָרָא לֵיהּ בְּהַהוּא עָלְמָא. וְתוֹרָה אוֹר, מַאן דְּאִתְעַסָּק בְּאוֹרַיְיתָא, זָכֵי לְהַהוּא נְהוֹרָא עִלָּאָה, דְּאַדְלִיקַת שַׁרְגָּא מִנֵּיהּ, דְּהָא שַׁרְגָּא בְּלָא נְהוֹרָא לָא כְּלוּם. נְהוֹרָא בְּלָא שַׁרְגָּא, אוּף הָכִי לָא יָכִיל לְאַנְהָרָא. אִשְׁתְּכַח דְּכֹלָּא דָּא לְדָא אִצְטְרִיךְ. אִצְטְרִיךְ עוֹבָדָא לְאַתְקְנָא שַׁרְגָּא. וְאִצְטְרִיךְ לְמִלְעֵי בְּאוֹרַיְיתָא, לְאַנְהָרָא שַׁרְגָּא. זַכָּאָה אִיהוּ מַאן דְּאִתְעַסָּק בָּהּ בִּנְהוֹרָא וּבְשַׁרְגָּא.</p>\n<p>וְדֶרֶךָ חַיִּים תּוֹכְחוֹת מוּסָר, אֹרַח חַיִּים לְאָעָלָא בֵּיהּ לְעָלְמָא דְּאָתֵי, אִינּוּן תּוֹכָחוֹת, דִּמְקַבֵּל בַּר נָשׁ לְאַעֲדָאָה גַּרְמֵיהּ מֵאֹרַח בִּישׁ, וּלְמֵיהַךְ בְּאָרְחָא טָבָא. תּוּ וְדֶרֶךְ חַיִּים, אִינּוּן תּוֹכְחוֹת מוּסָר, דְּאַיְיתֵי קוּדְשָׁא בְּרִיךְ הוּא עָלֵיהּ דְּבַר נָשׁ, לְדַכְּאָה לֵיהּ מֵחוֹבוֹי בְּאִינּוּן תּוֹכָחוֹת. זַכָּאָה אִיהוּ מַאן דְּקַבִּיל לְהוּ בִּרְעוּ דְּלִבָּא.</p>\n<p>דָּבָר אַחֵר כִּי נֵר מִצְוָה, (תקונא דשרגא) דָּא שַׁרְגָּא בּוּצִינָא דְּדָוִד, דְּאִיהוּ נִר מִצְוָה אוֹרַיְיתָא דִּבְעַל פֶּה, דְּאִצְטְרִיךְ לְאִתְתָּקְנָא תָּדִיר, וְאִיהִי לָא נַהֲרָא אֶלָּא מִגּוֹ תּוֹרָה שֶׁבִּכְתָב, דְּהָא אוֹרַיְיתָא דִּבְעַל פֶּה לֵית לָהּ נְהִירוּ, אֶלָּא מִגּוֹ תּוֹרָה שֶׁבִּכְתָב, דְּאִיהִי אוֹר לְאַנְהָרָא.</p>\n<p>אַשְׁגַּח אֲבַתְרֵיהּ, וְחָמָא בְּרָתֵיהּ דְּאוּשְׁפִּיזָא קַיְּימָא אֲבַתְרַיְיהוּ, אָמַר כִּי נֵר מִצְוָה, מַאי נֵר. דָּא נֵר דְּאִיהִי מִצְוָה דְּנָשִׁין זַכְיָין בֵּיהּ, וְאִיהִי נִר דְּשַׁבָּת, דְּאַף עַל גַּב דְּנָשִׁין לָא זָכָּאן בְּאוֹרַיְיתָא, הָא גּוּבְרִין זַכְיָין בְּאוֹרַיְיתָא, וְנָהֲרִין לְהַאי שַׁרְגָּא, דְּנָשִׁין מְתַּתְקְנָן בְּהַאי מִצְוָה. נָשִׁין בְּתִקּוּנָא דְּהַאי נֵר. גּוּבְרִין בְּאוֹרַיְיתָא, לְאַנְהָרָא לְהַאי נֵר, תִּקּוּנָא דְּמִצְוָה דְּנָשִׁין אִתְחָיְיבוּ בְּהוּ.</p>\n<p>שַׁמְעָת הַהִיא אִתְּתָא וּבָכָאת, אַדְּהָכִי קָם אֲבוּהָ דְּאִתְּתָא, דַּהֲוָת תַּמָּן, וְעָאל בֵּינַיְיהוּ, וְחָמָא בְּרָתֵיהּ קַיְּימַת אֲבַתְרַיְיהוּ וּבָכָאת, שָׁאִיל לָהּ אֲבוּהָ. סָחַת לֵיהּ (רבי אבא) עוֹבָדָא. שָׁאֲרִי אֲבוּהָ דְּאִתְּתָא אוּף אִיהוּ וּבָכָה. אָמַר לֵיהּ רַבִּי יוֹסִי, דִּילְמָא חֲתָנָךְ בַּעְלָהּ דִּבְּרָתִיךְ, לָא זָכָה בְּאוֹרַיְיתָא. אָמַר לֵיהּ וַדַּאי הָכִי הוּא, וְעַל דָּא וַדַּאי בָּכִינָן, אֲנָא וּבְרָתִי תָּדִיר.</p>\n<p>וּבְגִין דַּחֲמֵינָא, לֵיהּ יוֹמָא חַד, דְּדָלִּיג מֵאִגְרָא דָּא, לְמִשְׁמַע קַדִּישׁ בַּהֲדֵי צִבּוּרָא, סָלִיק בִּרְעוּתָא דִּילִי, לְמֵיהַב לֵיהּ בְּרָתִי, וְתֵּכֶף דְּנַפְקוּ צִבּוּרָא מִבֵּי כְּנִישְׁתָּא, יָהִיבְנָא לֵיהּ בְּרָתִי. דַּאֲמֵינָא בְּדִלוּגָא דָּא דְּאָתָא לְמִשְׁמַע קַדִּישׁ, גַּבְרָא רַבָּא לִיהֲוֵי בְּאוֹרַיְיתָא, וְאַף עַל גַּב דְּאִיהוּ רַבְיָא, וְלָא יְדַעְנָא בֵּיהּ מִקַּדְמַת דְּנָא. וְהַשְׁתָּא אֲפִילּוּ בִּרְכַּת מְזוֹנָא לָא יָדַע, וְלָא יָכִילְנָא בַּהֲדֵיהּ לְמִלְעֵי בֵּין חַבְרַיָּיא, דְּיוֹלִיף קְרִיאַת שְׁמַע, אוֹ בִּרְכַּת מְזוֹנָא.</p>\n<p>אָמַר לֵיהּ אַעְבָּר לֵיהּ בְּאַחֲרָא, אוֹ דִּלְמָא בְּרָא יוֹלִיד דְּלִהוֵי גַּבְרָא רַבָּא. אַדְּהָכִי קָם אִיהוּ, וְדִלֵג עֲלַיְיהוּ וְיָתִיב לְקָמַיְיהוּ. אִסְתָּכַּל בֵּיהּ רַבִּי יוֹסִי, אָמַר, וַדַּאי אֲנָא חֲמֵינָא בְּהַאי רַבְיָא, דִּנְהוֹרָא דְּאוֹרַיְיתָא יִפּוּק לְעָלְמָא מִנֵּיהּ. אוֹ בְּרָא דְּיוֹקִים מִנֵּיהּ. חָיִּיךָ הַהוּא רַבְיָא, וְאָמַר, רַבּוֹתַי אֵימָא קָמַיְיכוּ חַד מִלָּה.</p>\n<p>פָּתַח וְאָמַר (איוב ל״ב:ו׳) צָעִיר אֲנִי לְיָמִים וְאַתֶּם יְשִׁישִׁים עַל כֵּן זָחַלְתִּי וָאִירָא מֵחַוֹת דֵּעִי אֶתְכֶם. הַאי קְרָא אִתְּעָרוּ בֵּיהּ עַמּוּדֵי עָלְמָא. אֲבָל אֱלִיהוּא דִּכְתִּיב בֵּיהּ מִמִשְׁפַּחַת רָם, אִתְעָרוֹ, דְּהָא מִזַּרְעָא דְּאַבְרָהָם קָאֲתָא. וְשַׁפִּיר. אֲבָל אֱלִיהוּא כַּהֲנָא הֲוָה, וּמִזַּרְעָא דִּיְחֶזְקֵאל נְבִיאָה הֲוָה, כְּתִיב הָכָא בֶן בַּרַכְאֵל הַבּוּזִי, וּכְתִיב הָתָם (יחזקאל א׳:ג׳) יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן.</p>\n<p>וְאִי תֵּימָא בְּגִין דִּכְתִּיב בּוּזִי, (איוב ל״א:ל״ד) בּוּז מִשְׁפְּחוֹת הֲוָה. לָאו הָכִי, הָדָר וְאָמַר מִמִשְׁפַּחַת רָם, עִלָּאָה עַל כֹּלָּא. אֲמַאי אִקְרֵי בּוּזִי. עַל דְּמֵבַזֶה גַּרְמֵיהּ לְגַבֵּי מַאן <Nonei></i>דְּגָּדוֹל מִנֵּיהּ, וְעַל דָּא סָלִיק בִּשְׁמָא עִלָּאָה, בּוּזִי, דָּא דְּאִקְרֵי אָדָם שְׁלֵימָא בְּכֹלָּא, מַה דְּלָא אִקְרֵי הָכִי בַּר נָשׁ אַחֲרָא, הֲדָא הוּא דִּכְתִּיב, (יחזקאל ב) וְאַתָּה בֶן אָדָם, וְעַל דְּסָלִיק בִּשְׁמָא דָּא, אִקְרֵי רָם, עִלָּאָה עַל כֹּלָּא.</p>\n<p>וְעַל דָּא אָמַר צָעִיר אֲנִי לְיָמִים. לְיָמִים, מִיָמִים מִבָּעֵי לֵיהּ, מַאי לְיָמִים. אֶלָּא אָמַר צָעִיר אֲנִי, וְאַזְעִירְנָא גַּרְמָי לְיָמִים, לְגַבֵּי בַּר נָשׁ דְּאִית לֵיהּ יוֹמִין סַגִּיאִין. מַאי טַעְמָא. בְּגִין דְּאָמַרְתִּי דְּיָמִים יְדַבֵּרוּ, וְעַל דָּא צָעִיר אֲנִי, וְאַזְעִירְנָא גַּרְמֵי לְגַבֵּי יָמִים. וְאַתֶּם יְשִׁישִׁים, חֲמֵינָא לְכוּ יְשִׁישִׁים. עַל כֵּן זָחַלְתִּי וָאִירָא מֵחַוֹת דֵּעִי אֶתְכֶם. אוּף אֲנָא, אָמַרְתִּי יָמִים יְדַבֵּרוּ וְרַב שָׁנִים יוֹדִיעוּ חָכְמָה. וַדַּאי. אָכֵן רוּחַ הִיא בֶאֱנוֹשׁ וְנִשְׁמַת שַׁדַּי תְּבִינֵם. וְעַל דָּא בְּגִין דַּאֲנָא רַבְיָא, שַׁוֵינָא בִּרְעוּתִי דְּלָא לְמַלְּלָא עַד תְּרֵין יַרְחִין, וְעַד יוֹמָא דָּא אִשְׁתְּלִימוּ. וְהַשְׁתָּא דְּאַתּוּן הָכָא, אִית לְמִפְתַּח בְּאוֹרַיְיתָא קָמַיְיכוּ.</p>\n<p>פָּתַח וְאָמַר, (משלי ו׳:כ״ג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. כִּי נֵר מִצְוָה דָּא אִיהִי מִשְׁנָה, כְּמָה דְאַתְּ אָמֵר (שמות כד) וְהַתּוֹרָה וְהַמִּצְוָה. וְהַתּוֹרָה: זוֹ תּוֹרָה שֶׁבִּכְתָּב. וְהַמִּצְוָה: זוֹ מִשְׁנָה. דְּאִיהִי נִר שַׁרְגָּא, דְּקַיְּימָא לְאַדְלְקָא.</p>\n<p>נֵר אֲמַאי אִקְרֵי נֵר. אֶלָּא כַּד מְקַבְּלָא מֵבִין תְּרֵין דְּרוֹעִין, רמ\"ח שַׁיְיפִין עִלָּאִין, אִיהוּ פָּתְחַת לְגַבַּיְיהוּ תְּרֵין דְּרוֹעִין דִּילָהּ, כְּדֵין אִתְכְּלִילוּ אִלֵּין תְּרֵין דְּרוֹעִין בְּהוּ, וְאִקְרֵי נִר. וְתוֹרָה אוֹר, דְּקָא נָהִיר לְהַהוּא נֵר וְאַדְלִיקַת מִנֵּיהּ מִסִּטְרָא דְּאוֹר קַדְמָאָה, דְּאִיהוּ יְמִינָא. דְּהָא אוֹרַיְיתָא מֵהַהוּא סִטְרָא דִּימִינָא דְּאוֹר קַדְמָאָה אִתְיְהִיבַת, דִּכְתִּיב, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, מִסִּטְרָא דִּימִינָא אִתְיְהִיבַת, (מ\"ד ע\"א) אַף עַל גַּב דְּאִתְכְּלִיל בֵּיהּ שְׂמָאלָא, דְּהָא כְּדֵין אִיהוּ שְׁלִימוּ דְּכֹלָּא.</p>"],[9520011773,"<p>אוֹר דָּא אִתְכְּלִיל בְּמָאתָן וְשִׁבְעָה עָלְמִין, דְּאִינּוּן גְּנִיזִין בְּסִטְרָא דְּהַהוּא אוֹר, וְאִתְפָּשַּׁט בְּכֻלְּהוּ. תְּחוֹת כּוּרְסְיָיא עִלָּאָה טְמִירָא, שַׁרְיָין אִינּוּן עוֹלָמוֹת, מִסִּטְרָא דְּהַהוּא יְמִינָא. תְּלַת מֵאָה וָעֶשֶׁר אִינּוּן, מָאתָן וְשֶׁבַע, אִינּוּן בְּסִטְרָא דִּימִינָא. מֵאָה וּתְלַת, אִינּוּן בְּסִטְרָא דִּשְׂמָאלָא. וְאִינּוּן תְּלַת מֵאָה וָעֶשֶׁר. וְאִלֵּין אִינּוּן דְּקוּדְשָׁא בְּרִיךְ הוּא מְתַקֵּן תָּדִיר לְצַדִּיקַיָּא, וּמֵאִלֵּין מִתְפַּשְּׁטָן כַּמָה וְכַמָּה אוֹצְרֵי חֶמְדָּה, וְכֻלְּהוּ גְּנִיזִין לְאִתְעַדְנָא מִנְהוֹן צַדִּיקַיָּא לְעָלְמָא דְּאָתֵי וְעַל אִלֵּין כְּתִיב (משלי ח׳:כ״א) לְהַנְּחִיל אוֹהֲבַי יֵשׁ וְאוֹצְרוֹתֵיהֶם אֲמַלֵּא וְעַל אִלֵּין כְּתִיב (ישעיהו ס״ד:ג׳) עַיִן לא רָאָתָה אֱלהִים זוּלָתְךָ וְגוֹ'.</p>\n<p>י\"ש: אִלֵּין, תְּלַת מֵאָה וָעֶשֶׁר עוֹלָמוֹת, גְּנִיזִין תְּחוֹת עָלְמָא דְּאָתֵי, (ועל) אִינּוּן מָאתָן וְשֶׁבַע דְּאִינּוּן מִסִּטְרָא דִּימִינָא, אִקְרוּן אוֹר קַדְמָאָה. בְּגִין דְּאֲפִילּוּ אוֹר שְׂמָאלָא אִקְרֵי אוֹר. אֲבָל אוֹר קַדְמָאָה אִיהוּ זַמִין לְמֶעְבַּד תּוֹלָדִין לְעָלְמָא דְּאָתֵי. וְאִי תֵּימָא לְעָלְמָא דְּאָתֵי וְלָא יַתִּיר. אֶלָּא אֲפִילּוּ בְּכָל יוֹמָא וְיוֹמָא דְּאִי לָא הֲוָה הַאי אוֹר, עָלְמָא לָא יָכִיל לְמֵיקָם, דִּכְתִּיב, (תהילים פ״ט:ג׳) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנְה.</p>"],[9520011774,"<p>הַאי אוֹר זָרַע לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּגִנְתָּא דְּעִדָּנוֹי, וְעָבִיד לֵיהּ שׁוּרִין שׁוּרִין, עַל יְדוֹי דְּהַאי צַדִּיק, דְּאִיהוּ גָּנָּנָא דְּגִנְתָּא, וְנָטִיל לְהַאי אוֹר, וְזָרַע לֵיהּ זְרוּעָא דִּקְשׁוֹט. וְעָבִיד לֵיהּ שׁוּרִין שׁוּרִין בְּגִנְתָּא וְאוֹלִיד וְאַצְמַח וְעָבִיד פֵּרִין, וּמִנַּיְיהוּ אִתְּזַן עָלְמָא, הֲדָא הוּא דִכְתִיב, (תהילים צ״ז:י״א) אוֹר זָרוּעַ לַצַּדִּיק וְגוֹ'.</p>\n<p>וּכְתִיב (ישעיהו ס״א:י״א) וּכְגַנָּה זֵרוּעֶיהָ תַצְמִיחַ. מַאן זֵרוּעֶיהָ. אִלֵּין זְרוּעֵי דְּאוֹר קַדְמָאָה, דְּאִיהוּ זָרוּעַ תָּדִיר, הַשְׁתָּא אוֹלִיד וְעָבִיד אֵיבִין, וְהַשְׁתָּא זָרוּעַ אִיהוּ, בְּקַדְמִיתָא, עַד לָא יֵיכוּל עָלְמָא אִיבָּא דָּא, אוֹלִיד זְרוּעָא דָּא וְיָהִיב אִיבָּא וְלָא שָׁכִיךְ. וְעַל דָּא, כָּל עָלְמִין אִתְּזָנוּ בְּסִפּוּקָא דְּהַהוּא גָּנָּנָא, דְּאִקְרֵי צַדִּיק, דְּלָא שָׁכִיךְ וְלָא פָּסִיק לְעָלְמִין.</p>\n<p>בַּר בְּזִמְנָא דְּיִשְׂרָאֵל בְּגָלוּתָא. וְאִי תֵּימָא בְּזִמְנָא דְּגָלוּתָא כְּתִיב, (איוב י״ד:י״א) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחרָב וְיָבֵשׁ, הֵיךְ עָבִיד תּוֹלָדִין. אֶלָּא כְּתִיב זָרוּעַ, זָרוּעַ אִיהוּ תָּדִיר, וּמִיּוֹמָא דְּאַפְסִיק הַהוּא נָהָר. בְּגִנְתָּא (ס\"א בגנתא) לָא עָאל <Nonei></i>בֵּיהּ הַהוּא גָּנָּנָא. וְהַהוּא אוֹר דְּאִיהוּ זָרוּעַ תָּדִיר, עָבִיד אֵיבִין וּמִנֵּיהּ וּמִגַּרְמֵיהּ אִזְדְּרַע כְּקַדְמִיתָא, וְלָא שָׁכִיךְ תָּדִיר. כְּגִנְתָּא דְּעָבִיד תּוֹלָדִין, וּמֵהַהוּא זָרוּעַ נָפִיל בֵּיהּ בְּאַתְרֵיהּ, וּמִגַּרְמֵיהּ עָבִיד תּוֹלָדִין כְּדִבְקַדְמֵיתָא. וְאִי תֵּימָא, דְּאִינּוּן תּוֹלָדִין וְאֵיבִין הֲווֹ כְּמָה דְּהֲוָה בְּזִמְנָא דְּגָנָנָא תַּמָּן. לָאו הָכִי. אֲבָל לָא אִתְמָנַּע זָרוּעַ דָּא לְעָלְמִין.</p>\n<p>כְּגַוְונָא דָּא וְתוֹרָה אוֹר, אוֹרַיְיתָא דְּאִתְיְהִיבַת מִסִּטְרָא דְּהַהוּא אוֹר קַדְמָאָה, הָכִי אִזְדְּרַע תָּדִיר בְּעָלְמָא, וְעָבִיד תּוֹלָדִין וְאֵיבִין, וְלָא שָׁכִיךְ לְעָלְמִין, וּמֵהַהוּא אִיבָּא דִּילֵיהּ אִתְּזָן עָלְמָא.</p>\n<p>וְדֶרְךָ חַיִּים תּוֹכְחוֹת מוּסָר. תְּרֵין אָרְחִין אִינּוּן, חַד אֹרַח חַיִּים, וְחַד בְּהִפּוּכָא מִנֵּיהּ. סִימָנָא דְּאֹרַח חַיִּים מַאן אִיהוּ. תּוֹכְחוֹת מוּסָר. דְּכָד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְנַטְרָא לְהַאי אֹרַח חַיִּים, שַׁוֵּי עָלֵיהּ הַהוּא דְּאַלְקֵי, וְעָבִיד תּוֹכְחוֹת מוּסָר לִבְנֵי עָלְמָא. וּמַאן אִיהוּ. הַאי דִּכְתִּיב, (בראשית ג׳:כ״ד) וְאֵת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים וְעַל דָּא, דֶּרֶךְ חַיִּים אִיהוּ תּוֹכְחוֹת מוּסָר. וּמַאן דְּאִית בֵּיהּ תּוֹכָחוֹת, וַדַּאי דְּמִתְעָרֵי לֵיהּ לְמֵהַךְ בְּהַהוּא אֹרַח חַיִּים, דְּשָׁארִי תַּמָּן תּוֹכְחוֹת מוּסָר.</p>\n<p>הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. אֶלָּא כֹּלָּא רָזָא דִּמְהֵימְנוּתָא דְּהַאי קְרָא. כִּי נֵר מִצְוָה, דָּא רָזָא דְּשָׁמוֹר. וְתוֹרָה אוֹר, דָּא רָזָא דְּזָכוֹר, וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר, אִלֵּין גִּזְרִין וְעוֹנָשִׁין דְּאוֹרַיְיתָא, וְכֹלָּא רָזָא דִּמְהֵימְנוּתָא. וְאִצְטְרִיךְ דָּא לְדָא, וּלְמֶהֱוֵי רָזָא דְּכֹלָּא כַּדְקָא יֵאוֹת.</p>"],[9520011775,"<p>וְעַל רָזָא דָּא דְּהַאי אוֹר, דְּדָלִיק וְנָהִיר לְהַאי נִר, כְּתִיב בֵּיהּ בְּאַהֲרֹן, (במדבר ח׳:ב׳) בְּהַעֲלוֹתְךָ אֶת הַנֵּרוֹת, בְּגִין דְּהוּא אָתֵי מִסִּטְרָא דְּהַאי אוֹר. אוֹר דָּא כְּתִיב בֵּיהּ, (בראשית א׳:ג׳) יְהִי אוֹר וַיְהִי אוֹר. כֵּיוָן דְּאָמַר יְהִי אוֹר, אֲמַאי כְּתִיב וַיְהִי אוֹר, דְּהָא בְּוַיְהִי כֵן סַגְיָא. אֶלָּא, יְהִי אוֹר, דָּא אוֹר קַדְמָאָה, דְּאִיהוּ יְמִינָא, וְאִיהוּ לְקֵץ הַיָּמִין. וַיְהִי אוֹר, דְּמִימִינָא נָפִק שְׂמָאלָא, וּמֵרָזָא דִּימִינָא נָפִק שְׂמָאלָא, וְעַל דָּא וַיְהִי אוֹר, דָּא שְׂמָאלָא.</p>\n<p>מִכָּאן דְּוַיְהִי קַדְמָאָה דְּאוֹרַיְיתָא, בְּסִטְרָא דִּשְׂמָאלָא הֲוָה. וּבְגִין כַּךְ לָאו אִיהוּ סִימָן בְּרָכָה. מַאי טַעְמָא. בְּגִין דְּבֵיהּ (נ\"א דמניה) נָפַק הַהוּא חֹשֶׁךְ דְּאַחֲשִׁיךְ אַנְפֵּי עָלְמָא. וְסִימָנָא דָּא כַּד אִתְגְּלֵי רָזָא דְּעֵשָׂו וְעוֹבָדוֹי, בְּהַאי וַיְהִי הֲוָה, דִּכְתִּיב (בראשית כ״ה:כ״ז) וַיְהִי עֵשָׂו אִישׁ יוֹדֵעַ צַיִד. אִתְקָיָּים בְּוַיְהִי אִישׁ יוֹדֵעַ צַיִד, לְפַתָּאָה בְּנֵי עָלְמָא, דְּלָא יַהֲכוּן בְּאֹרַח מֵישָׁר.</p>\n<p>וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, דָּא אִיהוּ עַמּוּדָא דְּקָאִים בְּאֶמְצָעִיתָא, וְקָאִים וְאָחִיד בְּסִטְרָא דָּא, וּבְסִטְרָא דָּא. כַּד הֲוָה שְׁלִימוּ דִּתְלַת סִטְרִין, כְּתִיב בֵּיהּ כִּי טוֹב, מָה דְּלָא הֲוָה בְּהָנֵי אַחֲרָנִין, בְּגִין דְּלָא הֲוָה שְׁלִימוּ עַד אוֹר תְּלִיתָאָה, דְּאַשְׁלִים לְכָל סִטְרִין, וְכֵיוָן דְּאָתָא תְּלִיתָאָה דָּא, כְּדֵין אַפְרִישׁ מַחֲלוֹקֶת דִּימִינָא וּשְׂמָאלָא, דִּכְתִּיב וַיַּבְדֵּל אֱלהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ.</p>\n<p>וְעַל דְּאִינּוּן חֲמֵשׁ דַּרְגִּין, דְּאִתְפְּרָשׁוּ וְאִתְמְשָׁכוּ מֵהַאי אוֹר קַדְמָאָה, כְּתִיב (תצא ר\"פ ע\"א) אוֹר חָמֵשׁ זִמְנִין, וְכֻלְּהוּ הֲווֹ מִסִּטְרָא דִּימִינָא, וְאִתְכְּלִילוּ בֵּיהּ, וְכַד אִתְכְּלִילוּ בִּסְטַר שְׂמָאלָא, אִתְכְּלִילוּ בְּרָזָא דְּמַיִם, דְּנָטִיל בִּימִינָא (ס\"א מימינא') וּבְגִין כַּךְ כְּתִיב מַיִם חָמֵשׁ זִמְנִין. וְכַד אִשְׁתְּלִימוּ בְּרָזָא דְּאֶמְצָעִיתָא, כְּתִיב רָקִיעַ חֲמֵשׁ זִמְנִין, וְעַל דָּא תְּלַת אִינּוּן אוֹר. מַיִם. רְקִיעָ. לָקֳבֵל תְּלַת דַּרְגִּין אִלֵּין, דְּכֻלְּהוּ חֲמֵשׁ דַּרְגִּין אִתְכְּלִילוּ בְּהוּ, וְעַל דָּא בְּכֻלְּהוּ כְּתִיב חֲמֵשׁ זִמְנִין, בְּכָל חַד וְחַד.</p>\n<p>הָכָא רָזָא דְּרָזִין, בְּאִלֵּין תְּלָתָא, אִתְצָיַּיר וְאִתְגְלִיף בְּגִלּוּפֵי רָזָא דִּיּוּקְנָא דְּאָדָם, דְּאִיהוּ אוֹר בְּקַדְמִיתָא, לְבָתַר מַיִם, לְבָתַר אִתְפָּשַׁט בְּגַּוַּויְיהוּ רָקִיעַ, דְּאִיהוּ גְּלִיפָא דִּגְלִּיפוּ דִּיּוּקְנָא דְּאָדָם.</p>\n<p>כְּגַוְונָא דִּגְלִּיפוּ צִיּוּרָא דְּדִיּוּקְנָא דְּאָדָם בְּתוּלְדָתֵיהּ. דְּהָא בְּתוּלְדָתָא דְּבַר נָשׁ, בְּקַדְמִיתָא זֶרַע, דְּאִיהוּ אוֹר, דְּהָא נְהִירוּ דְּכָל שַׁיְיפֵי גּוּפָא, אִיהוּ הַהוּא זֶרַע, וּבְגִין כַּךְ אִיהוּ אוֹר, וְהַהוּא אוֹר אִקְרֵי זֶרַע, דִּכְתִּיב אוֹר זָרוּעַ, הַהוּא זֶרַע מַמָּשׁ. לְבָתַר הַהוּא זֶרַע דְּאִיהוּ אוֹר אִתְפָּשַׁט וְאִתְעָבִיד <Nonei></i>מַיִם, בְּלָחוּתָא דִּילֵיהּ, אַגְלִיף יַתִּיר, וְאִתְפָּשַּׁט פְּשִׁיטוּ גּוֹ אִינּוּן מַיִם, פְּשִׁיטוּ דְּגוּפָא לְכָל סִטְרִין. כֵּיוָן דְּאִתְצַיָּיר, וְאִגְּלִיף צִיּוּרָא וּדְיוּקְנָא דְּגוּפָא, אַקְרִישׁ הַהוּא פְּשִׁיטוּ, וְאִקְרֵי רָקִיעַ. וְדָא אִיהוּ רָקִיעַ בְּתוֹךְ הַמַּיִם. וּלְבָתַר דְּאַקְרִישׁ, כְּתִיב וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָׁמָיִם. דְּהָא אַקְרִישׁ הַהוּא לָחוּתָא (ד\"א דאנגיד ואשתאר ההוא פסולת) דְּגוּפָא, דְּהֲוָה גּוֹ אִינּוּן מַיִם.</p>\n<p>כֵּיוָן דְּאִבְרִיר גּוּפָא, וְאִנָקֵי בִּנְקִיוּ, הַהוּא לָחוּתָא דְּאִתְנְגִיד וְאִשְׁתְּאַר, הֲוָה פְּסוֹלֶת דְּקָא אִתְעֲבָד גּוֹ הִתּוּכָא, וְאִינּוּן מַיִם הָרָעִים עֲכוּרִין, וּמִנְּהוֹן אִתְעָבִיד פְּסוֹלֶת, מְקַטְרְגָא לְכָל עָלְמָא, דְּכַר וְנוּקְבָּא. לְבָתַר כַּד נַחְתּוּ אִינּוּן מַיִם עֲכוּרִין, וְאִתְהַתְּכוּ לְתַתָּא בִּסְטַר שְׂמָאלָא, נָפְקוּ (ס\"א דאתנגיד ואשתאר אתעביד פסולת מקטרגא לכל עלמא דכר ונוקבא ואינון מים הרעים עכורין. לבתר כד נחתו אינון מים עכורין אתהתכו לתתא בסטר שמאלא ונפקו) לְקַטְרְגָא כָּל עָלְמָא. זַכָּאָה אִיהוּ מַאן דְּאִשְׁתְּזִיב מִנְּהוֹן.</p>\n<p>כֵּיוָן דְּנָפִיק מְקַטְרְגָא, כְּתִיב יְהִי מְאֹרֹת חָסֵר ו' וְאִתְמַשְּׁכָא אַסְכָּרָה בְּרַבְיֵי, וְחָסֵר נְהוֹרָא דְּסִיהֲרָא. לְבָתַר וְהָיוּ לִמְאוֹרוֹת, בִּשְׁלִימוּ תַּרְוַויְיהוּ כַּחֲדָא. בְּמַאן. בְּהַהוּא רְקִיעַ הַשָּׁמַיִם, דְּהָא כַּד סַלְּקָא וְאִתְחַבְּרָא בְּהַהוּא רְקִיעַ הַשָּׁמַיִם, כְּדֵין וְהָיוּ לִמְאוֹרוֹת, נְהוֹרִין שְׁלֵימִין תַּרְוַויְיהוּ כַּחֲדָא דְּלָא פְּגִימֵי כְּלַל.</p>\n<p>שַׁארִי חָיִּיךָ הַאי רַבְיָא וְחַדֵּי. אָמַר לוֹן הַאי דַּאֲמֵינָא דְּאִתְבְּרִיר הָכָא רָזָא דְּאָדָם, בְּאוֹר דְּהַהוּא (ד\"א דאיהו) זֶרַע, וּלְבָתַר אִתְעָבִיד מַיִם, וּמִגּוֹ אִינּוּן מַיִם, אִתְפָּשַׁט רָקִיעַ, דִּיּוּקְנָא דְּאָדָם כְּמָה דְּאִתְּעַרְנָא. תִּינַח כַּד אִתְעָבִיד דָּא לְגוֹ מֵעוֹי דְּאִתְּתָא, דְּהָא לָא אִתְצָיַּיר זַרְעָא, אֶלָּא בְּגוֹ מֵעוֹי דְּנוּקְבָּא, לְאִתְפָּשְׁטָא בָּהּ דִּיּוּקְנָא דְּאָדָם, וְהָכָא אִי אִלֵּין חָמֵשׁ דַּרְגִּין, אִינּוּן דִּיּוּקְנָא דְּאָדָם, בְּאָן אֲתָר אִתְצָיַּיר וְאִתְפָּשַּׁט הַאי דִּיּוּקְנָא, בְּגוֹ אִינּוּן מַיִם.</p>\n<p>אִי תֵּימָא גּוֹ נוּקְבָּא הֲווֹ, דָּא עָלְמָא דְּאָתֵי, לָאו הָכִי, דְּהָא לָא אִתְצָיַּיר צִיּוּרָא וּדְיוּקְנָא, עַד דְּנַפְקוּ אַתְוָון לְבַר, וּלְבָתַר אִתְגְּלִימוּ. וְתוּ דְּהָא עָלְמָא דְּאָתֵי הֲוָה אוּמָנָא, דִּכְתִּיב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ, הָא אוּמָנָא הֲוָה.</p>\n<p>אִי תֵּימָא בְּנוּקְבָּא דִּלְתַתָּא, לָאו הָכִי, דְּהָא עַד לָא הֲוָות, וְכַד נָפַק הַאי דִּיּוּקְנָא דְּאָדָם, נוּקְבֵיהּ נַפְקַת בַּהֲדֵיהּ. הָא לָא אִתְצָיַּיר דִּיּוּקְנָא דְּאָדָם בָּהּ. אִי הָכִי, בְּאָן אֲתָר אִתְצָיַּיר וְאִתְגְלִיף הַאי זֶרַע, לְמֶהוֵי גְּלִיפוּ דִּיּוּקְנָא דְּאָדָם.</p>\n<p>אֶלָּא דָּא רָזָא עִלָּאָה, אָדָם קַדְמָאָה אִתְצָיַּיר וְאִתְגְלִיף בְּלָא נוּקְבָּא. אָדָם תִּנְיָינָא, מֵחֵילָא וְזַרְעָא דְּהַאי, אַגְלִיף וְאִתְצָיַּיר גּוֹ נוּקְבָּא.</p>\n<p>אָדָם קַדְמָאָה, גְּלִיפוּ דְּצִיּוּרָא וּדְיוּקְנָא דְּגוּפָא, לָא הֲוָה בְּנוּקְבָּא, וּבְלָא צִיּוּרָא כְּלַל הֲוָה. וְאִתְצָיַיר וְאִגְּלִיף לְתַתָּא מֵעָלְמָא דְּאָתֵי, בְּלָא דְּכוּרָא, וּבְלָא נוּקְבָּא, אִינּוּן אַתְוָון אַגְלִימוּ גּוֹ מִשְׁחָתָא, וְאִתְצָיַיר וְאִגְּלִיף בְּהוּ רָזָא דְּאָדָם. וְאַתְוָון בְּאֹרַח מֵישָׁר, בְּסִדּוּרָא דִּלְהוֹן, מֵרָזָא דְּאוֹר קַדְמָאָה, שָׁרִיאוּ לְאִתְגָלְפָא וּלְאִתְצָיְּירָא, (אתוון) וְאִזְדְּרַע הַאי אוֹר בְּגַוֵּיהּ גּוֹ מִשְׁחָתָא. כַּד מָטָא גּוֹ מִשְׁחָתָא, אִתְהַדָּר מַיָּא, גּוֹ מַיָּא, אִתְפָּשַׁט רָקִיעַ צִיּוּרָא דְּאָדָם, דִּיּוּקְנָא כַּדְקָא חֲזִי.</p>\n<p>לְבָתַר דְּאִתְקַשְּׁטַת נוּקְבָּא לְגַבֵּיהּ, וְאִתְהַדְּרוּ אַנְפִּין בְּאַנְפִּין, הַאי דִּיּוּקְנָא דְּאָדָם, עָאל בְּתִיאוּבְתָּא לְגַבֵּי נוּקְבָּא, וְתַמָּן אַגְלִיף וְאִתְצָיָיר כְּגַוְונָא דִּילֵיהּ, וְעָלֵיהּ כְּתִיב (בראשית ה׳:ג׳) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וְגוֹ', הַאי אִתְצָיַּיר גּוֹ נוּקְבָּא, מַה דְּלָא הֲוָה הַהוּא קַדְמָאָה, דְּאִתְצַיָּיר (ד\"א ל\"ג גו) הַהוּא קַדְמָאָה בְּגַוֵּיהּ בִּמְדִּידוּ גּוֹ מִשְׁחָתָא כְּמָה דְּאִתְּמַר.</p>"],[9520011776,"<p>כְּגַוְונָא דָּא לְתַתָּא. לְתַתָּא מַה כְּתִיב, (בראשית ד׳:א׳) וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן, שָׁרִיאַת קוֹף לְאוֹלָדָא, בִּמְעָהָא, בְּחֵילָא וְסִיוּעָא (רל\"א ע\"א) דְּאָדָם לְבָתַר דְּהָא קַבִּילַת (קמ\"ח ע\"ב) זוּהֲמָא מִגּוֹ הַאי קוֹף. וְעַל דָּא לָא כְּתִיב הָכָא וַיּוֹלֶד, אֶלָּא יָדַע וַתַּהַר וַתֵּלֶד, וְנָפַק פְּסוֹלֶת גּוֹ נוּקְבָּא.</p>\n<p>וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל, וּבְהַאי נָמֵי לָא כְּתִיב וַיּוֹלֶד, וְאַף עַל גַּב דְּמִסְטְרָא דִּדְכוּרָא הֲוָה. אֲבָל מְקַטְרְגָא תָּשַׁשׁ וְתָבַר חֵילֵיהּ, דְּהָא בְּאָת קוֹף שָׁרִיאוּ <Nonei></i>אַתְוָון לְאוֹלָדָא.</p>\n<p>כֵּיוָן דְּאִתְבְּרִיר פְּסוֹלֶת, שָׁרִיאוּ אַתְוָון לְאוֹלָדָא מֵרָזָא דְּאָת ש\"ת. תִּקּוּנָא דְּכַר וְנוּקְבָּא. בְּאִסְתַּכְּמוּתָא כַּחֲדָא. וּכְדֵין כְּתִיב וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת, וְלָא כְּתִיב וַתִּקְרָא. וַיִּקְרָא אִיהוּ, וְלָא אִיהִי. אִיהוּ קָרָא שְׁמֵיהּ שֵׁת, תִּקּוּנָא דְּכַר וְנוּקְבָּא כַּחֲדָא, דַּהֲווֹ בְּאִסְתַּכְּמוּתָא חֲדָא.</p>\n<p>תּוּ אִתְגַּלְגָּלוּ אַתְוָון, וְאָהַדְרוּ לְאוֹלָדָא אָלֶף דְּאָדָם, וְאִינּוּן אַתְוָון בַּאֲתָר דְּאִיהוּ סִיּוּם שְׁמֵיהּ. וּמַאן אִיהוּ. נ', וּלְבָתַר ו' לָא ה', דְּהָא אִתְעֲדִיאַת (נ\"א אתיילידת) בְּהֶבֶל. בְּגִין כַּךְ נָטִיל אָת אַחֲרָא אֲבַתְרֵיהּ ו', סִיֵּים בְּשֵׁירוּתָא דְּשֵׁת ש', וְאִקְרֵי אֱנוֹשׁ.</p>\n<p>אֱנוֹשׁ מָה בֵּין שְׁמָא דָּא לִשְׁמָא דְּאָדָם. אֶלָּא אֱנוֹשׁ לָאו אִיהוּ בְּתֻּקְפָּא הֲוָה, תִּקּוּנָא דְּקַדְמָאֵי הֲוָה, (תהילים ח׳:ה׳) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ. וּכְתִיב (איוב ז׳:י״ח) מָה אֱנוֹשׁ כִּי תְּגַּדְלֶנּו וְגוֹ', וַתִּפְקְדֶנּוּ לִבְקָרִים לִרְגָּעִים תִּבְחָנְנּוּ. וְעַל דָּא כְּתִיב (ישעיהו נ״ג:י׳) וַיְיָ' חָפֵץ דַּכְּאוֹ הֶחֱלִי, תְּבִירוּ דְּגוּפָא, וְתֻּקְפָּא דְּנַפְשָׁא, אוֹרִית שֵׁת לְאֱנוֹשׁ יְרוּתָא דְּהֲוָה לֵיהּ לְקַבְּלָא. וְאִיהוּ אוּף הָכִי אוֹרִית לִבְנוֹ.</p>\n<p>תּוּ אִתְגַּלְגָּלוּ אַתְוָון לְאַתְקְנָא עֲקִימָא, וְאִתְהַדְּרוּ לְאוֹלָדָא. קֵינָן. הַאי תִּקּוּנָא דְּקַיִן, וְאִתְתָּקַּן תְּחוֹתֵיהּ, וְאִתְהַדְּרוּ אַתְוָון לְבַסְּמָא עָלְמָא מֵעֲקִימוּ דְּהֲוָה. מַהֲלַלְאֵל מ' סוֹפָא דְּאַתְוָון דְּאָדָם. ה' ול' תִּקּוּנָא דְּאַתְוָון דְּהֶבֶל, וּבְגִין דְּלָא הֲוָה חַיָּיבָא כְּקַיִן, לָא אִתְחַלָּפוּ אַתְוָון מִשְּׁמֵיהּ בַּר חַד. דִּבַאֲתָר ב' הֲוָה א' לְמֶהֱוֵי תִּקּוּנָא יַתִּיר.</p>\n<p>עַד הָכָא אִתְבְּסָם עָלְמָא, וְאִתְתָּקַּן עֲקִימָא מֵשֵּׁירוּתָא דֶּאֱנוֹשׁ. בַּר חוֹבָא דְּאָדָם, דְּלָא אִתְבְּסָם, עַד דְּקַיְימוּ יִשְׂרָאֵל בְּטוּרָא דְּסִינַי, אֲבָל תִּקּוּנָא דְּעֲקִימוּ דְּקַיִן וְהֶבֶל אִתְתָּקַּן וְאִתְבָּסַם, אֲבָל עָלְמָא הֲוָה בְּצַעֲרָא וְעִצְבוֹנָא, עַד דְּאָתָא נֹחַ דִּכְתִּיב, (בראשית ה׳:כ״ט) זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂנוּ וּמֵעִצְּבוֹן יָדֵינוּ מִן הָאֲדָמָה אֲשֶׁר אֲרֵרָהּ יְיָ'. וְחוֹבָא דְּאָדָם לָא אִתְבְּסָם, עַד דְּקַיְימוּ יִשְׂרָאֵל עַל טוּרָא דְּסִינַי, וְקַבִּילוּ אוֹרַיְיתָא, וְכַד יִשְׂרָאֵל קַבִּילוּ אוֹרַיְיתָא, כְּדֵין נֵר וְאוֹר אִתְתַּקַּן כַּחֲדָא.</p>\n<p>וְהַשְׁתָּא רַבּוֹתַי, אֲנָא מִבָּבֶל, וּבְרָא דְּרַב סַפְרָא אֲנָא, וְלָא זָכֵינָא לְאִשְׁתְּמוֹדְעָא לְאַבָּא, וְאַטְרִידְנָא הָכָא, וְדָחִילְנָא, דְּהָא יַתְבֵי אַרְעָא דָּא, אִינּוּן אַרְיְיוָון בְּאוֹרַיְיתָא, וְשַׁוֵינָא עָלַי דְּלָא אֵימָא מִילֵּי דְּאוֹרַיְיתָא קָמֵי בַּר נָשׁ, עַד תְּרֵין יַרְחִין, וְיוֹמָא דָּא אִשְׁתְּלִימוּ. זַכָּאָה חוּלָקִי דְּאִתְעַרְעְתוּן הָכָא. אָרִים רַבִּי יוֹסִי קָלֵיהּ וּבָכֵי, וְקָמוּ כֻּלְּהוּ וּנְשָׁקוּהוּ בְּרֵישֵׁיהּ. אָמַר רַבִּי יוֹסִי זַכָּאָה חוּלָקָנָא דְּזָכֵינָא בְּהַאי אָרְחָא, לְמִשְׁמַע מִלֵּי דְּעַתִּיק יוֹמִין מִפּוּמָךְ, מַה דְּלָא זָכֵינָן לְמִשְׁמַע עַד הַשְׁתָּא.</p>\n<p>יָתִיבוּ כֻּלְּהוּ, אָמַר לוֹן רַבּוֹתַי, מִדְּחָמֵינָא צַעֲרָא דְּהַאי חָמִי וּבְרָתֵיהּ, דְּדַחֲקֵי וּמִצְטַעֲרֵי בְּנַפְשַׁיְיהוּ, דְּלָא יְדַעְנָא בִּרְכַּת מְזוֹנָא. אֲמֵינָא לוֹן, דְּעַד דְּאֶנְדַע בִּרְכַּת מְזוֹנָא, לָא אִתְחֲבָּר בְּאִנְתְּתִי, כְּאֹרַח כָּל בְּנֵי עָלְמָא, וְאַף עַל גַּב דְּיָכִילְנָא לְשַׁמְּשָׁא בָּהּ בְּלָא חוֹבָה, לָא בְּעֵינָא לְמֶעְבַּר עַל דַּעְתַּיְיהוּ, הוֹאִיל וְלָא הֲוֵינָא יָכִיל לְמֵימַר מִדִי, עַד תְּרֵין יַרְחִין. חֲדוּ רַבִּי יוֹסִי וְרַבִּי חִיָּיא וְחַמוֹי וּבְרָתֵיהּ, וּבָכוּ מִסְגִיאוּ חֶדְוָה. אָמַר רַבִּי יוֹסִי, בְּמָטוּ מִינָךְ, כֵּיוָן דִּשְׁרִיאַת, אַנְהִיר לָן יְמָמָא, זַכָּאָה חוּלָקָנָא בְּאֹרַח דָּא.</p>"],[9520011777,"<p>פָּתַח הַהוּא רַבְיָא בְּבִרְכַּת מְזוֹנָא וְאָמַר, כָּתוּב אֶחָד אוֹמֵר (דברים י״ד:כ״ג) וְאָכַלְתָּ לִפְנִי יְיָ' אֱלֹהֶיךָ, וְכָתוּב אֶחָד אוֹמֵר (דברים כ״ז:ז׳) וְשָׂמַחְתָּ לִפְנֵי יְיָ' אֱלֹהֶיךָ. הָנֵי קְרָאֵי כַּד יִשְׂרָאֵל הֲווֹ שָׁרָאן בְּאַרְעָא קַדִּישָׁא, וְאִתְחָזוּן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּבֵי מַקְדְּשָׁא, הֲווֹ מִתְקַיְּימֵּי. הַשְּׁתָּא הֵיךְ מִתְקַיְּימֵּי, מַאן יָכִיל לְמֵיכַל לִפְנֵי יְיָ' וּלְמֵחֱדֵי לִפְנֵי יְיָ'.</p>\n<p>אֶלָּא וַדַּאי הָכִי הוּא, בְּקַדְמִיתָא כַּד יָתִיב בַּר נָשׁ עַל פָּתוֹרֵיהּ לְמֵיכַל, מְבָרֵךְ עַל נַהֲמָא הַמּוֹצִיא. מַאי טַעֲמָא הַמּוֹצִיא, וְלָא מוֹצִיא, דְּהָא כְּתִיב (ישעיהו מ״ב:ה׳) בּוֹרֵא הַשָּׁמַיִם, וְלָא כְּתִיב הַבּוֹרֵא. (ירמיהו י׳:י״ב) עוֹשֶׂה אֶרֶץ, וְלָא כְּתִיב הָעוֹשֶׂה אֶרֶץ. מַאי טַעֲמָא הָכָא הַמּוֹצִיא.</p>\n<p>אֶלָּא כָּל מִלִּין דְּאִינּוּן מֵרָזָא דְּעָלְמָא עִלָּאָה סְתִירָא, אִסְתַּתְּרָא ה' מִתַּמָּן, לְאִתְחֲזָאָה דְּהָא מֵעָלְמָא גְּנִיזָא וּסְתִירָא אִיהוּ. <Nonei></i>וְכָל מִלִּין דְּאִינּוּן מֵעָלְמָא תַּתָּאָה דְּאִתְגַּלְיָא יַתִּיר, כְּתִיב בה', דִּכְתִּיב, (ישעיהו מ׳:כ״ו) הַמּוֹצִיא בְּמִסְפָּר צְבָאָם (עמוס ה׳:ח׳) הַקּוֹרֵא לְמֵי הַיָּם, כֻּלְּהוּ מֵרָזָא דְּעָלְמָא תַּתָּאָה אִיהוּ, וְאִי (רל\"א ע\"ב) אַכְתִּיב בִּשְׁמָא אִיהוּ בה', כְּגוֹן הָאֵל הַגָּדוֹל, וְהָכָא דְּאִיהוּ בְּאֹרַח סָתִים (נ\"א באתגליא) מֵרָזָא דְּעָלְמָא תַּתָּאָה אִיהוּ, כֵּיוָן דִּמְבָרֵךְ בַּר נָשׁ, שְׁכִינְתָּא אַתְיָא קָמֵיהּ.</p>\n<p>וּמַה דְּאָמַר וְאָכַלְתָּ לִפְנֵי יְיָ' אֱלֹהֶיךָ. הָכָא אִתְכְּלִיל לְמַלְּלָא בְּמִלֵּי דְּאוֹרַיְיתָא, דְּהָכִי אִצְטְרִיךְ הוֹאִיל וְקוּדְשָׁא בְּרִיךְ הוּא קָמֵיהּ, לְקַיְּימָא דִּכְתִּיב, (יחזקאל מ״א:כ״ב) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יְיָ'. וּכְתִיב (דברים י״ד:כ״ו) וְאָכַלְתָּ שָׁם לִפְנֵי יְיָ' אֱלהֶיךָ.</p>\n<p>הוֹאִיל וְקָאִים בַּר נָשׁ קָמֵי מָארֵיהּ, אִצְטְרִיךְ נָמֵי לְמֵיחַן לְמִסְכְּנֵי, לְמֵיתַן לוֹן, כְּמָה דְּאִיהוּ יָהִיב לֵיהּ לְמֵיכַל. (ס\"א ומאן דאכיל קמיה מלכא קדישא אצטריך וכו') כְּמַאן דְּאָכִיל קָמֵי מַלְכָּא קַדִּישָׁא וְאִצְטְרִיךְ דְּלָא יִשְׁתְּכַח בַּלְעָן עַל פָּתוֹרֵיהּ, דְּהָא בִּלְעֲנוּ מִסִּטְרָא אַחֲרָא הֲוֵי, וְרָזָא דָּא (בראשית כ״ה:ל׳) הַלְעִיטֵנִי נָא, אֹרַח בַּלְעֲנוּ, וְהָכִי אִצְטְרִיךְ לְסִטְרָא אַחֲרָא, וּכְתִיב (משלי י״ג:כ״ה) וּבֶטֶן רְשָׁעִים תֶחְסָר. וְעַל דָּא וְאָכַלְתָּ לִפְנִי יְיָ' אֱלֹהֶיךָ כְּתִיב, וְלָא לִפְנֵי סִטְרָא אַחֲרָא. וְאִצְטְרִיךְ דְּלָא יִתְעַסֵּק בְּמִלִּין בְּטֵלִין, וּבְצָרְכֵי סְעוּדָה (שפיר) וְאִצְטְרִיךְ לְאִתְעַסְּקָא בְּמִלִּין דְּאוֹרַיְיתָא, דְּהָא כַּד מִלִּין דְּאוֹרַיְיתָא אִתְּמָרוּ עַל פָּתוֹרָא, יָהִיב הַהוּא בַּר נָשׁ תֻּקְפָּא לְמָארֵיהּ.</p>\n<p>וְשָׂמַחְתָּ לִפְנִי יְיָ' אֱלֹהֶיךָ, דָּא אִיהוּ בְּכוֹס שֶׁל בְּרָכָה, כַּד בָּרִיךְ בַּר נָשׁ בְּכוֹס שֶׁל בְּרָכָה, אִצְטְרִיךְ לְמֵחדֵי וּלְאַחֲזָאָה חֶדְוָה וְלָא עֲצִיבוּ כְּלַל, כֵּיוָן דְּנָטִיל בַּר נָשׁ כּוֹס שֶׁל בְּרָכָה, קוּדְשָׁא בְּרִיךְ הוּא קָאִים עַל גַּבֵּיהּ, וְאִיהוּ אִצְטְרִיךְ לְאַעְטָפָא רֵישֵׁיהּ בְּחֶדְוָה. וּלְבָרְכָא עַל הַכּוֹס בְּמוֹתָב תְּלָתָא, נְבָרֵךְ שֶׁאָכַלְנוּ מִשֶׁלוֹ.</p>\n<p>וּבְטוּבוֹ חָיִּינוּ, דָּא אִצְטְרִיךְ רְעוּתָא לְעֵילָּא לְגַבֵּי עַתִּיקָא דְּעַתִּיקִין, וְעַל דָּא אִיהִי בְּאֹרַח סָתִים. וּבְטוּבוֹ, וְלָא מִטּוּבוֹ, וּבְטוּבוֹ: דָּא יְמִינָא (ד\"א זינה) עִלָּאָה. וּמִטּוּבוֹ: דָּא דַּרְגָּא אַחֲרָא, דְּאָתֵי מִסִּטְרָא דִּימִינָא, וְאִיהוּ דַּרְגָּא לְתַתָּא מִנֵּיהּ, בְּגִין דִּבְהַהוּא טוֹב אִתְבְּנִי עָלְמָא, וּבֵיהּ אִתְּזָן.</p>\n<p>אֲמַאי אִקְרֵי טוֹב וַאֲמַאי אִקְרֵי חֶסֶד. טוֹב אִיהוּ, כַּד כָּלִיל כֹּלָּא בְּגַוֵּיהּ, וְלָא אִתְפָּשַׁט לְנַחְתָּא לְתַתָּא. חֶסֶד כַּד נַחְתָּא לְתַתָּא. וְעָבִיד טִיבוּ בְּכָל בִּרְיָין, בְּצַדִּיקֵי וּבְרַשִׁיעֵי וְלָא חָיִישׁ, וְאַף עַל גַּב דְּדַרְגָא חַד הוּא. מְנָלָן דִּכְתִּיב, (תהילים כ״ג:ו׳) אַךְ טוֹב וְחֶסֶד יִרְדְפוּנִי, אִי טוֹב לָמָּה חֶסֶד, וְאִי חֶסֶד לָמָּה טוֹב, דְּהָא בְּחַד סַגְיָא אֶלָּא טוֹב כָּלִיל כֹּלָּא בְּגַוֵּיהּ, וְלָא אִתְפָּשַׁט לְתַתָּא. חֶסֶד נָחִית (ק\"ט ע\"א) וְאִתְפָּשַּׁט לְתַתָּא, וְזָן כֹּלָּא צַדִּיקֵי וְרַשִׁיעֵי כַּחֲדָא.</p>\n<p>וְהָכָא כֵּיוָן דְּאָמַר וּבְטוּבוֹ חָיִּינוּ, הָדָר וְאָמַר הַזָּן אֶת הָעוֹלָם כֻּלּוֹ בְּטוּבוֹ בְּחֶסֶד, הֲדָא הוּא דִכְתִיב, (תהילים קל״ו:כ״ה) נוֹתֵן לֶחֶם לְכָל בָּשָׂר כִּי לְעוֹלָם חַסְדּוֹ. וְעַל דָּא הַזָּן אֶת הַכֹּל, לְצַּדִיקֵי וּלְרַשִׁיעֵי לְכֹלָּא. דָּא אִקְרֵי בִּרְכַּת יָמִין. שְׂמֹאל לָאו אִיהוּ בְּבִרְכַּת מְזוֹנָא. וּבְגִין כַּךְ שְׂמָאלָא לָא תְּסַיֵּיעַ לִימִינָא.</p>\n<p>דְּכֵיוָן דְּבָרִיךְ בִּרְכַּת יָמִין (נ\"א היין), אִצְטְרִיךְ לְדַבְּקָא אֶרֶץ הַחַיִּים בַּיָּמִין, לְאִתְּזָנָא מִתַּמָּן, וּלְפַרְנָסָא וּלְמֵיהַב מְזוֹנָא לְכֹלָּא, וְעַל דָּא תִּנְיָינָא בִּרְכַּת הָאָרֶץ, וְאִצְטְרִיךְ לְאַדְכְּרָא בָּהּ בְּרִית וְתוֹרָה, עַל בְּרִיתְךָ שֶׁחָתַמְתָּ בִּבְשָׂרֵנוּ, וְעַל תּוֹרָתְךָ שֶׁלִמַדְתָּנוּ, לְאַחֲזָאָה דְּמֵהַהוּא טוֹב אִתְּזָן בְּרִית וְתוֹרָה, דְּאִיהוּ תִּקּוּנָא דְּהַאי טוֹב.</p>\n<p>מִכָּאן אוֹלִיפְנָא, דְּנָשִׁים פְּטוּרוֹת מִבִּרְכַּת מְזוֹנָא לְאַפָּקָא יְדֵי חוֹבָה, דְּהָא לֵית בְּהוּ תּוֹרָה וּבְרִית. וְלַחֲתוֹם עַל הָאָרֶץ וְעַל הַמָּזוֹן, הָא דִּדְבֵקוּתָא כַּחֲדָא בְּחֶסֶד, עַל הָאָרֶץ דָּא אִיהִי אֶרֶץ הַחַיִּים. וְעַל הַמָּזוֹן דָּא אִיהוּ חֶסֶד, הָא כְּלִילוּ דָּא בְּדָא בִּדְבֵיקוּתָא חֲדָא.</p>\n<p>אִתְפַּשְּׁטוּתָא דְּטוֹב אִיהוּ הוֹדָאָה דְּאִקְרֵי חֶסֶ\"ד, וְעַל דָּא אִיהוּ אוֹמֵר, נוֹדֶה לְךָ, עַל כַּךְ וְעַל כַּךְ נִסִּין וְאָתִין דְּאִתְעָבִידּוּ מִסִּטְרָא דְּטוֹב. וְאִי תֵּימָא וְהָא כְּתִיב (תהילים ט״ז:י״א) נְעִימוֹת בִּימִינְךָ, נֶצַח, הָא אִיהוּ מִסִּטְרָא דְּיָמִין. לָאו הָכִי, אֶלָּא כָּל חַד וְחַד אַחְזֵי עַל הַהוּא אֲתָר דְּנָפִיק מִנֵּיהּ.</p>\n<p>וְאִי תֵּימָא נֶצַח בַּיָּמִין, הָא כְּתִיב נְעִימוֹת, וּכְתִיב (שמואל ב כ״ג:א׳) וּנְעִים זְמִירוֹת יִשְׂרָאֵל, (בראשית כ\"א ע\"ב) (ד\"א בימינך נצח) וְדָא שְׂמָאלָא. <Nonei></i>וְכָל שְׂמָאלָא אִתְכְּלִיל בְּרָזָא דִּימִינָא. אֲבָל הוֹדָאָה אוֹדֵי עַל יְמִינָא, לְאַחֲזָאָה דְּהָא מִנֵּיהּ נָפְקָא, וְדָא פְּשִׁיטוּ דְּטוֹב, דְּאִתְפָּשַּׁט בְּאֶרֶץ הַחַיִּים.</p>\n<p>מַאי טַעְמָא לֵית הָכָא שְׂמָאלָא, בְּגִין דְּלֵית חוּלָקָא לְסִטְרָא אַחֲרָא בִּמְזוֹנָא דְּיִשְׂרָאֵל. וְאִי אִתְּעַר שְׂמָאלָא, סִטְרָא אַחֲרָא יִתְּעַר עִמֵּיהּ, וְהָא אִיהוּ זַבִּין בְּכֵרוּתֵיהּ וְחוּלָקֵיהּ לְיַעֲקֹב אֲבוּנָא. (ויקרא כ\"א ע\"א) וְהָא אֲנַן יָהִיבְנָא לֵיהּ חוּלָקֵיהּ, לְהַהוּא מְקַטְרְגָא בְּזוּהֲמָא דְּמַיִין בַּתְרָאִין, וְאִי לֵית זוּהֲמָא, הָא חוּלָקֵיהּ דְּהַהוּא מֵיכְלָא, דְּקָרִיבוּ בֵּיהּ יְדִין.</p>\n<p>וְעַל דָּא לֵית לֵיהּ חוּלָקָא בַּהֲדָן. וְהוֹאִיל וְלֵית לֵיהּ חוּלָקָא בַּהֲדָן, דְּהָא נָטַל חוּלָקֵיהּ, לֵית לָן לְאִתְּעֲרָא שְׂמָאלָא כְּלַל. דְּלָא יִתְּעַר מְקַטְרְגָא וְיִטּוֹל תְּרֵין חוּלָקִין, חַד לְתַתָּא, וְחַד לְעֵילָּא, כַּבְּכוֹר. דְּהָא זַבִּין בְּכֵרוּתֵיהּ לְיַעֲקֹב אֲבוּנָא. חוּלָקֵיהּ אִיהוּ לְתַתָּא, וְלֵית לֵיהּ לְעֵילָּא כְּלוּם. יִשְׂרָאֵל נַטְלֵי לְעֵילָּא, וְעֵשָׂו נָטִיל לְתַתָּא, וְעַל דָּא לָא יִתְקְרַב שְׂמָאלָא כְּלָל, בְּבִרְכַּת מְזוֹנָא.</p>\n<p>כֵּיוָן דְּמִתְבָּרְכָא הַאי אֶרֶץ הַחַיִּים מִסִּטְרָא דִּימִינָא, וּמְקַבֵּל מְזוֹנָא, כְּדֵין בָּעֵינָן רַחֲמִין עַל כֹּלָּא. רַחֵם יְיָ' אֱלֹהֵינוּ עַל יִשְׂרָאֵל עַמָךְ וְעַל יְרוּשָׁלַיִם עִירָךְ וְגוֹ', דְּהָא מֵהַהוּא מְזוֹנָא וְסִפּוּקָא דְּאֶרֶץ הַחַיִּים, נִזְכֵּי בָּהּ אֲנָן וּבֵי מַקְדְּשָׁא. דְּיִתְבְּנֵי בֵּי מַקְדְּשָׁא לְתַתָּא בְּאִינּוּן רַחֲמִים.</p>\n<p>וּבְשַׁבָּת דְּלָא אִשְׁתְּכַח דִּינָא, לְמֶהֱוֵי נֶצַח וְהוֹד כְּלַל חֲסָדִים, אוֹמֵר רְצֵה וְהַחֲלִיצֵנוּ לְמֶהֱוֵי (ויחי רי\"ט ע\"א) תַּרְוַיְיהוּ, (ישעיהו נ״ה:ג׳) חַסְדֵּי דָּוִד הַנְּאֱמָנִים, וְעַל דָּא אַל תְּהִי צָרָה וְיָגוֹן וְכוּ', דְּהָא רְצֵה וּמוֹדִים, אִינּוּן חֲסְדֵי דָּוִד, וְשִׂים שָׁלוֹם דְּקָאָמַרָן בִּצְלוֹתָא, בְּבִרְכַּת עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו הוּא בְּרַחֲמָיו יַעֲשֶׂה שָׁלוֹם עָלֵינוּ.</p>\n<p>הַטּוֹב וְהַמֵּטִיב, דְּכֹלָּא אָתֵי מִסִּטְרָא דִּימִינָא, וְלָא מִסְטַר שְׂמָאלָא כְּלוּם. מַאן דִּמְבָרֵךְ בִּרְכַּת מְזוֹנָא, אִיהוּ נָטִיל בִּרְכָאן בְּקַדְמִיתָא מְכֻּלְּהוּ, וְאִתְבְּרַךְ בִּכְלָל בִּרְכַּת מְזוֹנָא, וְעַל דָּא אִית לֵיהּ אַרְכָּא דְּחַיִּין. מַאן דְּנָטִיל כּוֹס שֶׁל בְּרָכָה, וְקָא מְבָרֵךְ עָלֵיהּ, כְּתִיב (תהילים קט״ז:י״ג) כּוֹס (בראשית א' ע\"א, רכ\"ג ע\"א) יְשׁוּעוֹת אֶשָׂא. מַאן יְשׁוּעוֹת דָּא יְמִינָא, דְּאִיהוּ מוֹשִׁיעַ מִכָּל מְקַטְרְגִין דְּעָלְמָא, דִּכְתִּיב (נ\"א הושיעה לו ימינו) וַתּוֹשַׁע לוֹ יְמִינוֹ, וּכְתִיב (תהילים ס׳:ז׳) הוֹשִׁיעָה יְמִינְךָ וַעֲנֵנִי.</p>\n<p>אַדְהָכִי הֲוָה נָהִיר יְמָמָא, קָמוּ כֻּלְּהוּ וּנְשָׁקוּהוּ. אָמַר רִבִּי יוֹסִי, וַדַּאי הִלוּלָא אִיהוּ יוֹמָא דָּא, וְלָא נֵיפוּק מֵהָכָא, עַד דְּיִתְעֲבִיד הִלוּלָא בְּכָל אַנְשֵׁי מָתָא, דָּא הוּא הִלוּלָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בֵּיהּ. נַטְלוּ לָהּ לְאִנְתְּתֵיהּ, וּבָרִיכוּ לָהּ בְּכַמָּה בִּרְכָאן, עַבְדוּ דַּאֲבוּהָ יְתַקֵּן בֵּיתָא אַחֲרָא לְחֶדְוָה, כְּנִישׁוּ כָּל אַנְשֵׁי מָתָא לְהַהִיא חֶדְוָתָא, וְקָרְאוּ לָהּ כַּלָּה. וְחַדּוּ עִמְּהוֹן כָּל הַהוּא יוֹמָא, וְאִיהוּ חַדֵּי עִמְּהוֹן בְּמִלֵּי דְּאוֹרַיְיתָא.</p>"],[9520011778,"<p>פָּתַח אִיהוּ עַל פָּתוֹרָא וְאָמַר, (שמותכו) וְעָשִׂיתָ אֶת הַקְּרָשִׁים לַמִּשְׁכָּן עֲצֵי שִׁטִּים עוֹמְדִים. כְּתִיב הָכָא עוֹמְדִים. וּכְתִיב הָתָם (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים. מַה לְּהַלָּן שְׂרָפִים, אוּף הָכָא נָמֵי שְׂרָפִים. אִלֵּין קְרָשִׁים קַיְימָן בְּתִקּוּנֵי דְּכַלָּה, וְסָחֲרָן סָחֲרָנָא דְּחוּפָּה, לְמִשְׁרֵי בְּהַהִיא חוּפָּה רוּחַ עִלָּאָה, (נ\"א רזא עלאה) כְּגַוְונָא דָּא כַּלָּה לְתַתָּא, אִצְטְרִיךְ לְתַקְּנָא חוּפָּה לְחוּפָאָה בְּתִקִינוֹ שָׁפִירוּ, לִיקָרָא דְּכַלָּה אַחֲרָא, דְּאַתְיָא לְמִשְׁרֵי תַּמָּן בְּחֶדְוָה, לְכַלָּה תַּתָּאָה.</p>\n<p>וּבְגִין יְקָרָא דְּהַהִיא כַּלָּה עִלָּאָה, אִצְטְרִיךְ לְמֶעְבַּד חוּפָּאָה דִּשְׁפִּירוּ, בְּכָל תִּקּוּנֵי דִּשְׁפִּירוּ, לְזִמְנָא לְכַלָּה עִלָּאָה, לְהַהִיא חֶדְוָה. כְּגַוְונָא דָּא בְּכָל גְּזִירוּ דִּבְרִית לְתַתָּא, אִצְטְרִיךְ לְאַתְקְנָא כִּסֵּא אַחֲרָא בִּשְׁפִירוּ, (הקדמה י\"ג ע\"א) לְמָארֵי קִנְאָה דִּבְרִית קַיָּימָא דְּאָתֵי תַּמָּן. אוּף הָכָא בְּכָל חוּפָּה, אִצְטְרִיךְ תִּקּוּנֵי שְׁפִירוּ, לְחוּפָאָה לְחוּפָּה לִיקָרָא דְּכַלָּה סְתָם.</p>\n<p>דְּהָא דָּא, כְּגַוְונָא דְּדָא קַיְּימָא. דָּא סַלְּקָא בְּשֶׁבַע בִּרְכָאן, וְדָא סַלְּקָא בְּשֶׁבַע בִּרְכָאן. וְכַד סַלְּקָא בְּשֶׁבַע בִּרְכָאן כְּדֵין אִקְרֵי כַּלָּה. וְעַל דָּא אָסִיר לְשַׁמְּשָׁא בָּהּ עַד דְּאִתְכְּלִילַת בְּאִינּוּן שֶׁבַע בִּרְכָאן, כְּגַוְונָא עִלָּאָה.</p>\n<p>אִינּוּן שֶׁבַע בִּרְכָאן, יָרְתָא כַּלָּה, מֵרוּחָא (נ\"א מרזא) עִלָּאָה, <Nonei></i>אֲתָר דְּכָל בִּרְכָאן נַגְדִּין מִתַּמָּן. שִׁית בִּרְכָאן אִינּוּן דְּכַלָּה אִתְבָּרְכָא מִנַּיְיהוּ, וְאַתְּ אַמָרְתְּ דְּאִינּוּן שֶׁבַע. אֶלָּא שְׁבִיעָאָה אִיהוּ דְּקָא מְקַיֵּים כֹּלָּא.</p>\n<p>רוּבָּא דְּבִרְכָּאָן עַל הַיַּיִן אֲמַאי. אֶלָּא דְּאִיהוּ סִטְרָא דְּחַדֵּי לְכֹלָּא, עַל הַהוּא יַיִן דְּאִתְנְטִיר בָּעֲנָבוֹי תָּדִיר. וּבְגִין כַּךְ בְּרָכָה קַדְמָאָה דְּאִינּוּן שֶׁבַע, אִיהוּ רָזָא דְּיַיִן, יַיִן עָבִיד פְּרִי (ס\"א חידו) בֵּין לְעֵילָּא בֵּין לְתַתָּא. גֶּפֶן נָטִיל כֹּלָּא, וְאַפִּיק אִיבָּא לְעָלְמָא, וְאַתְּעֲרוּ דְּחֶדְוָה שְׂמָאלָא אִיהוּ, דִּכְתִּיב, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וּלְבָתַר וִימִינוֹ תְּחַבְּקֵנִי. וְהַהוּא אִילָנָא דְּחַיֵּי עָבִיד פֵּירִין וְאֵיבִין (ס\"א בההוא גפן) בְּאִתְעָרוּתָא דָּא, וְדָא אִיהִי בְּרָכָה קַדְמָאָה דְּכֹלָּא. (בורא פרי הגפן).</p>\n<p>תִּנְיָינָא שֶׁהַכֹּל בָּרָא לִכְבוֹדוֹ, רָזָא דִּבְרִית קַדִּישָׁא, חֶדְוָה דְּחִבּוּרָא, דְּנָטִיל כָּל בִּרְכָאן מֵרָזָא דִּימִינָא, לְמֶעְבַּד אֵיבִין בְּהַהוּא גֶּפֶן, דְּהָא בְּקַדְמִיתָא הַהוּא פְּרִי (נ\"א חידו) נָחִית מִלְּעֵילָּא, אֹרַח שַׁיְיפִין, וְנָגִיד לִבְרִית קַדִּישָׁא, לְנַגְדָּא לֵיהּ בְּהַהוּא גֶּפֶן, וְדָא מִסִּטְרָא דִּימִינָא, דְּהָא לֵית אִיבָּא מִשְׁתַּכְחָא אֶלָּא בִּימִינָא. שְׂמָאלָא אִתְעַר וִימִינָא עָבִיד.</p>\n<p>לְבָתַר כָּלִיל שְׂמָאלָא בִּימִינָא, וִימִינָא בִּשְׂמָאלָא, לְמֶהוֵי רָזָא דְּאָדָם. וּבְגִין כַּךְ תְּלִיתָאָה אִיהוּ יוֹצֵר הָאָדָם. וְעַל דָּא יַעֲקֹב, דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא, דִּיּוּקְנָא דְּאָדָם הֲוָה.</p>\n<p>רְבִיעָאָה, אִיהוּ עַמּוּדָא חֲדָא, דְּיַרְכָּא יְמִינָא. חֲמִישָׁאָה, שׂוֹשׂ תָּשִׂישׂ וְתָגֵל עֲקָרָה דְּבֵיתָא, בְּחֶדְוָה בְּקִבּוּץ וּכְנִישׁוּ דִּבְנָהָא, מֵאַרְבַּע סִטְרֵי עָלְמָא, וְדָא רָזָא דְּיַרְכָּא אַחֲרָא, דְּאִתְחַבָּר בְּיַרְכָא שְׂמָאלָא, לְמֵיזָל וּלְמִיכְנַשׁ לְכָל סִטְרִין, וּכְנִישׁוּ דִּבְנִין, וּרְחִימוּ, לְמֵיעַל לוֹן בֵּין בִּרְכִּין.</p>\n<p>וּבְאִינּוּן תְּרֵין, דִּנְבִיאִים שַׁרְיָין בְּגַּוַּויְיהוּ, חֶדְוָה דְעִקָרָא דְּבֵיתָא. מַאי טַעְמָא. בְּגִין דְּהָא שְׁתֵּי עֲרָבוֹת, לָא עַבְדִּין אֵיבָא וּפֵירִין, וּכְנִישׁוּ דִּבְנִין לְגַבַּיְיהוּ, אִינּוּן פֵּירִין וְאֵיבִין דִּלְהוֹן, וְלָא אַתְּעֲרוּ כְּנִישׁוּ דִּבְנָהָא לְגַבָּהָא, בַּר בַּנְבִיאִים.</p>\n<p>שְׁתִּיתָאָה שָׂמֵחַ תְּשַׂמַּח רֵעִים הָאֲהוּבִים, אֲתָר דִּרְעוּתָא וְחֶדְוָה וְאַחְוָה אִשְׁתְּכַח, עַמּוּדָא דְּכָל עָלְמָא דְּאִקְרֵי צַדִּיק, וְצַדִּיק וְצֶדֶק רֵעִים וַאֲהוּבִים אִינּוּן, דְּלָא אִתְעֲדוּן דָּא מִן דָּא. עַד הָכָא שִׁית בִּרְכָאן, דְּכַלָּה אִתְבָּרְכַת מִנַּיְיהוּ.</p>\n<p>שְׁבִיעָאָה אִיהוּ מְקַיֵּים כֹּלָּא, וּמֵהַאי שְׁבִיעָאָה מִתְבָּרְכָאן כֹּלָּא וַדַּאי, כְּלָלָא דְּעֶשֶׂר אֲמִירָן, בְּגִין דְּדָא, כָּלִיל עֵילָּא וְתַתָּא. וְעַל דָּא כָּלִיל בְּהַאי, י' זִינֵי דְּחֶדְוָה, שָׂשׂוֹן, שִׂמְחָה, חָתָן, (ס\"א וכלה, גילה, דיצה, אהבה, ואחוה, שלום') וְכַלָּה, אַהֲבָה, אַחְוָה, גִּילָה, רִינָּה דִּיצָה, חֶדְוָה, שָׁלוֹם וְרֵיעוּת, לְמֶהוֵי כַּלָּה שְׁלִימוּ דְּכֹלָּא.</p>\n<p>זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּאִינּוּן זָכוּ לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא. עָלַיְיהוּ כְּתִיב, (שמואל ב ז׳:כ״ג) וּמִי כְעַמְּךָ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. חֲדוּ כֻּלְּהוּ כָּל הַהוּא יוֹמָא בְּמִלִּין דְּאוֹרַיְיתָא, וְכָל בְּנֵי מָתָא עַבְדוּ לֵיהּ רֵישָׁא עָלַיְיהוּ. לְיוֹמָא אַחֲרָא, קָמוּ רַבִּי יוֹסִי וְרַבִּי חִיָּיא וּבָרְכוּ לוֹן, וְאָזְלוּ לְאָרְחַיְיהוּ.</p>\n<p>כַּד מָטוּ לְגַבֵּיהּ דְּרַבִּי שִׁמְעוֹן, זָקַף עֵינוֹי וְחָמָא לוֹן. אָמַר לוֹן מִסְתַּכֵּל הֲוֵינָא בְּכוּ יוֹמָא דָּא, וַחֲמֵינָא לְכוּ תְּרֵין יוֹמִין וְחַד לֵילְיָא, דַּהֲוֵיתוֹן לְגַבֵּי מַשְׁכְּנָא דְּהַהוּא נַעַר מְטַטְרוֹן, וְהַהוּא נַעַר הֲוָה אוֹלִיף לְכוּ רָזִין עִלָּאִין בְּחֶדְוָה דְּאוֹרַיְיתָא, זַכָּאָה חוּלָקֵכוֹן בָּנַי.</p>\n<p>סִדְּרוּ מִלִּין כֻּלְּהוּ קָמֵיהּ, וְסָחוּ לֵיהּ עוֹבָדָא, אָמַר לוֹן זַכָּאִין אַתּוּן, וְזַכָּאָה חוּלָקִי, דְּהָא אַדְכַּרְנָא יוֹמָא חַד דְּהֲוָה אָזִיל עִמִּי בְּאָרְחָא רַב סַפְרָא אֲבוֹי, וּבָרִיכִית לֵיהּ כַּד אִתְפְּרַשׁ מִנִּי, דִּיּהֵא לֵיהּ בַּר אַרְיָא בְּאוֹרַיְיתָא, וְלָא בָּרִיכִית לֵיהּ דְּאִיהוּ יִזְכֵּי בֵּיהּ. זַכָּאָה חוּלָקֵכוֹן בָּנַי, עָלַיְיכוּ כְּתִיב (ישעיהו נ״ד:י״ג) וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ'.</p>\n<p>דָּבָר אַחֵר וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ'. וְכִי כָּל בְּנִין דְּאִינּוּן דְּיִשְׂרָאֵל, כֻּלְּהוּ אוֹלִיף לוֹן קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא. אִין. דְּהָא בְּשַׁעֲתָא דְּאִינּוּן יַנוּקֵי לָעָאן בְּאוֹרַיְיתָא, שְׁכִינְתָּא אַתְיָא וְיָהִיב לוֹן חֵילָא וְתֻּקְפָּא לְמִלְעֵי בְּאוֹרַיְיתָא, דְּאִלְמָלֵא סִיּוּעָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לָא יַכְלִין אִינּוּן יַנוּקֵי לְמִסְבַּל.</p>"],[9520011779,"<p>רַבִּי שִׁמְעוֹן הֲוָה שְׁכִיחַ יוֹמָא חַד גַּבֵּי פִּתְחָא דְלוּד, וְרַבִּי חִיָּיא בַּהֲדֵיהּ, פָּגַע בֵּיהּ חַד יַנוּקָא, אָמַר רַבִּי שִׁמְעוֹן וַדַּאי דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי (נ\"א אתער) בְּעָלְמָא הַשְׁתָּא לְיוֹמִין זְעִירִין, גִּלְגּוּלָא רַבָּא לְמַלְכֵי אַרְעָא אִלֵּין בְּאִלֵּין. <Nonei></i>וַדַּאי בְּעוֹד דְּאִינּוּן מְקַטְרְגִין אִלֵּין עַל אִלֵּין, יִשְׂרָאֵל יְהוֹן גּוֹ רְוָוחָא.</p>\n<p>אָמַר הַהוּא יַנוּקָא, וְהָא בְּיוֹמָא דָּא שַׁאֲרִי אִתְּעָרוּתָא דָּא, דְּהָא בְּהַאי יוֹמָא דָּמִין סַגִּיאִין אוֹשְׁדִין בְּעָלְמָא. אֲמַר לֵיהּ רַבִּי חִיָּיא, מְנָא לֵיהּ לְהַאי יַנוּקָא. אָמַר רַבִּי שִׁמְעוֹן, לְזִמְנִין נְבוּאָה נָפִיל בְּפוּם יַנוּקָן, וּמִתְנַבְּאֵי יַתִּיר מֵחַד נְבִיאָה.</p>\n<p>אָמַר הַהוּא יַנוּקָא, וְכִי תַּוָוהָא אִיהוּ בְּיַנוּקֵי לְמֶהֱוֵי לוֹן נְבוּאָה, וְהָא קְרָא שְׁלִים אִיהוּ. מְנָלָן. דִּכְתִּיב וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ'. אִינּוּן וַדַּאי לִמּוּדֵי יְיָ', וּנְבוּאָה מִנְּהוֹן נָפְקָא, מַה דְּלֵית הָכִי לְכָל עָלְמָא, אֶלָּא לְיִשְׂרָאֵל בִּלְחוֹדוֹי, דִּכְתִּיב בְּהוּ וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ', וּבְגִינֵי כַּךְ מִנְּהוֹן נָפְקָא נְבוּאָה. אָתָא רַבִּי שִׁמְעוֹן וּנְשָׁקֵיהּ אָמַר מִיוּמָאִי לָא שְׁמַעְנָא דָּא, בַּר הַשְׁתָּא.</p>"],[9520011780,"<p>דָּא פִּקּוּדָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה: (שמות כ״ו:ט״ו) וְעָשִׂיתָ אֶת הַקְּרָשִׁים לַמִּשְׁכָּן עֲצֵי שִׁטִּים עוֹמְדִים. (כלא כגוונא עלאה) (ד\"א ל\"ג פתח רבי יצחק) וּכְתִיב (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם וְגוֹ', עוֹבָדָא דְּמַשְׁכְּנָא בְּאִינּוּן קְרָשִׁים, כְּגַוְונָא דְּאִינּוּן שְׂרָפִים, (בהאי אתר) אִלֵּין עוֹמְדִים, וְאִלֵּין עוֹמְדִים.</p>\n<p>וְאִי תֵּימָא, וְהָא כָּל חַיָּילֵי שְׁמַיָא אִינּוּן עוֹמְדִים כֻּלְּהוּ, כְּמָה דְאַתְּ אָמֵר (זכריה ג׳:ז׳) וְנָתַתִּי לְךָ מַהְלְכִים בֵּין הָעוֹמְדִים הָאֵלֶּה, וּכְתִיב (מלכים א כ״ב:י״ט) וְכָל צְבָא הַשָּׁמַיִם עוֹמְדִים עָלָיו וְגוֹ', דְּהָא כֻּלְּהוּ מַשִּׁרְיָין עִלָּאִין לֵית לְהוּ קְפִיצִין, וְכֻלְּהוּ קַיְימֵי בְּקִימָה. אֶלָּא וַדַּאי כֻּלְּהוּ קַיְימִין, וּלְזִמְנִין אִלֵּין אִקְרוּן שְׂרָפִים, וּלְזִמְנִין סַלְּקִין בִּשְׁמָא אַחֲרָא, אֲבָל אִלֵּין כֻּלְּהוּ בְּחַד שְׁמָא קַיְימֵי.</p>"],[9520011781,"<p>וְהַאי קְרָא אוּקְמוּהָ, (נ\"א רבי יצחק פתח) כְּתִיב (תהילים כ״ג:א׳) מִזְמוֹר לְדָוִד יְיָ' רֹעִי לָא אֶחְסָר. הָא (נ' ע\"א) אִתְּמַר, מָה בֵּין מִזְמוֹר לְדָוִד, וּבֵין לְדָוִד מִזְמוֹר. וְהָכָא, שְׁכִינְתָּא קַדְמָא וְאַתְיָא, וְשָׁרָאת עָלֵיהּ בְּקַדְמִיתָא. יְיָ' רֹעִי, וְכִי אֲמַּאי שְׁכִינְתָּא קַדְמָא הָכָא, וְהָא דָּוִד אִצְטְרִיךְ לְאַקְדְּמָא (ס\"א לאתערא) אִיהוּ בְּקַדְמִיתָא, הוֹאִיל וּבָעֵי מְזוֹנֵיהּ מֵעִם קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אֶלָּא, וַדַּאי שְׁכִינְתָּא קַדְמָא וְאַתְיָא, וְשָׁרָאת עָלֵיהּ, וְאַתְעֲרַת לֵיהּ לְשַׁבְּחָא לְמַלְכָּא שְׁבָחָא דָּא, וּלְמִבָּעֵי מְזוֹנִי מִקָּמֵי מַלְכָּא, דְּהָא הָכִי אִצְטְרִיךְ עַל מִלָּה דִּמְזוֹנָא דְּבַעְיָא אִיהִי וּרְעוּתָא דִּילָהּ, דְּכָל בְּנֵי עָלְמָא יִבְעוּן מְזוֹנֵי. בְּגִין דְּכַד קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְנַחְתָּא מְזוֹנֵי לְעָלְמָא, אִיהִי נַטְלָא בְּקַדְמִיתָא, וְעָלָה נַחְתֵּי מְזוֹנִי לְעָלְמִין כֻּלְּהוּ. וּבְגִינֵי כַּךְ אִיהִי אַקְדִּימַת לְמִלָּה דָּא דִּמְזוֹנֵי, וְשָׁרַאת עָלֵיהּ דְּדָוִד.</p>\n<p>יְיָ' רֹעִי, יְיָ' רַעְיָא דִּילִי, כְּהַאי רַעְיָא דְּמַדְבַּר עָאנָא דִּילֵיהּ בְּאֲתָר דִּדְּשָׁאִין וַעֲשָׂבִין, דְּלָא מִחְסַר בֵּיהּ כָּל מִדְּעַם. אוּף הָכִי קוּדְשָׁא בְּרִיךְ הוּא, הוּא אִיהוּ רַעְיָא דִּילִי, לְמֵיזָן לִי בְּכָל מָה דַּאֲנָא אִצְטְרִיךְ. דָּבָר אַחֵר יְיָ' רֹעִי, תָּנֵינָן, דְּקָשִׁין מְזוֹנוֹתָיו דְּבַּר נָשׁ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, כִּקְרִיעַת יַם סוּף. הָכָא תְּרֵין גַּוְונִין אִינּוּן, וְתַרְוַויְיהוּ בְּאֹרַח קְשׁוֹט.</p>"],[9520011782,"<p>חַד בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא כָּל עוֹבָדוֹי בְּדִינָא וּקְשׁוֹט, וְעַל דִּינָא וּקְשׁוֹט אִתְקָיָּים כָּל עָלְמָא. וּבְכָל יוֹמָא וְיוֹמָא, וּבְכָל זִמְנָא וְזִמְנָא, דָּן כָּל עָלְמָא בְּדִינָא לְצַּדִיקֵי וְלִרְשִׁיעֵי וּלְכָל בְּנֵי עָלְמָא, כְּמָה דְאַתְּ אָמֵר (תהילים י״א:ז׳) כִּי צַדִּיק יְיָ' צְדָקוֹת אָהֵב. וְכַד אִיהוּ דָּן בְּנִי נָשָׁא, וְחָמֵי בְּנִי נָשָׁא כַּמָה חַיָּיבִין, וְכַמָּה חֲטָאִין קָמֵיהּ, כְּדֵין קְשֵׁה בְּעֵינוֹי לְמֵיהַב לוֹן מְזוֹנָא בְּכָל זִמְנָא, בְּגִין דְּאִית לֵיהּ לְמֵיזָן חַיָּיבַיָּא, וּלְאִינּוּן דְּחֲטָאן.</p>\n<p>וְאִיהוּ עָבִיד עִמְּהוֹן לְגוֹ מִשּׁוּרַת הַדִּין, וְזָן וּמְפַרְנֵס לוֹן כְּפוּם חֶסֶד עִלָּאָה, דְּאִתְמְשָׁךְ (קס\"ח ע\"ב) וְאִתְנְגִיד עַל כָּל (ס\"א עמין ובני) בְּנִי עָלְמָא, וּבֵיהּ אִיהוּ זָן וּמְפַרְנֵס לְכֹלָּא, לְצַּדִיקֵי וּלְחַסִידֵּי וְלִרְשִׁיעֵי, וּלְכָל אִינּוּן בְּנֵי עָלְמָא, וּלְכָל חֵיוָן וּבְעִירֵי חַקְלָא, וְעוֹפֵי שְׁמַיָא, מִקַּרְנֵי רְאֵמִים עַד בֵּיצֵי כְּלָמֵי, וְלָא אִשְׁתְּאַר בְּעָלְמָא, דְּאִיהוּ לָא זָן וּמְפַרְנֵס לְכֹלָּא, אַף עַל גַּב דִּקְשֵׁה קַמֵּיהּ, לְפוּם עוֹבָדִין דִּבְנִי עָלְמָא, כִּקְרִיעַת יַם סוּף.</p>\n<p>וְכִי קְרִיעַת יַם סוּף קְשֵׁה קַמֵּיהּ, וְהָכְתִיב (נחום א׳:ד׳) גּוֹעֵר בַּיָּם וַיַבְּשֵׁהוּ, (עמוס ה׳:ח׳) הַקּוֹרֵא לְמֵי הַיָּם וַיִשְׁפְּכֵם עַל פְּנִי הָאָרֶץ, וְהָא כֵּיוָן דְּסָלִיק <Nonei></i>רְעוּתָא קַמֵּיהּ, כֹּלָּא קָמֵיהּ כְּאַיִן הוּא חָשִׁיב, וְאַת אַמָרְתְּ דִּקְרִיעַת יַם סוּף קְשֵׁה קַמֵּיהּ.</p>\n<p>אֶלָּא בְּזִמְנָא דְּיִשְׂרָאֵל אַעְבָּרוּ לְגַבֵּי יַמָּא, וּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִקְרַע לוֹן יַמָּא דְּסוּף, אָתָא רַהַב הַהוּא מְמָנָא דְּעַל מִצְרַיִם, וּבָעָא דִּינָא מִקָּמֵי קוּדְשָׁא בְּרִיךְ הוּא. אָמַר קַמֵּיהּ, מָארֵיהּ דְּעָלְמָא, אֲמַאי אַתּ בָּעֵי לְמֶעְבַּד דִּינָא עַל מִצְרַיִם, וּלְמִקְרַע יַמָּא לְיִשְׂרָאֵל, הָא כֻּלְּהוּ חַיָּיבִין קַמָּךְ, וְכָל אָרְחָךְ בְּדִינָא וּקְשׁוֹט. אִלֵּין פַּלְחֵי כּוֹכָבִים וּמַזָּלוֹת וְאִלֵּין פַּלְחֵי כּוֹכָבִים וּמַזָּלוֹת. אִלֵּין בְּגִלוּי עֲרָיוֹת, וְאִלֵּין בְּגִלוּי עֲרָיוֹת. אִלֵּין אוֹשְׁדֵי דָּמִין, וְאִלֵּין אוֹשְׁדֵי דָּמִין.</p>\n<p>בְּהַהִיא שַׁעֲתָא הֲוָה קְשֵׁה קַמֵּיהּ, לְמֶעְבַּר עַל אֹרַח דִּינָא. וְהָא יִשְׂרָאֵל הֲווֹ נַטְלֵי עַל יַמָּא, דִּכְתִּיב, (שמות י״ד:ט״ו) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי דַּבֵּר אֶל בְּנִי יִשְׂרָאֵל וְיִּסָעוּ, וַהֲוָה קְשֵׁה קַמֵּיהּ לְמֶעְבַּר עַל דִּינָא, וּלְמִקְרַע לוֹן יַמָּא דְּסוּף, וְאִלְמָלֵא דְּאַשְׁגַּח קוּדְשָׁא בְּרִיךְ הוּא בִּזְכוּת אַבְרָהָם, דְּאַקְדִים בְּצַפְרָא לְמֶעְבַּד פִּקּוּדָא דְּמָארֵיהּ, וּרְעוּתָא דִּילֵיהּ, כְּדִכְתִיב (בראשית כ״ב:ג׳) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר, כֻּלְּהוּ אִתְאֲבִידוּ בְּיַמָּא, בְּגִין דִּבְכָל הַהוּא לֵילְיָא, בְּדִינָא הֲוָה קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ דְּיִשְׂרָאֵל.</p>\n<p>דְּתָנֵינָן, מַאי דִּכְתִּיב וְלָא קְרָב זֶה אֶל זֶה כָּל הַלַּיְלָה. מְלַמֵּד דְּאָתוּ מַלְאֲכֵי עִלָּאֵי לְשַׁבְּחָא בְּהַהוּא לֵילְיָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, אָמַר לוֹן, וְכִי (ס\"א בני) עוֹבָדֵי יְדַי טַבְעִין בְּיַמָּא, וְאָתוּן מְשַׁבְּחָן קָמָאי, מִיַּד וְלָא קְרָב זֶה אֶל זֶה כָּל הַלַּיְלָה. מַה כְּתִיב, וַיְהִי בְּאַשְׁמֹרֶת הַבֹּקֶר, אַשְׁגַּח קוּדְשָׁא בְּרִיךְ הוּא בִּזְכוּתָא דְּאַבְרָהָם, דְּאַקְדִּים בְּצַפְרָא לְמֶעְבַּד רְעוּתֵיהּ דְּמָארֵיהּ, כְּדִכְתִיב וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. כְּדֵין אַהְדָּר יַמָּא, וְעָרְקוּ מַיִין קַמָּיְיהוּ דְּיִשְׂרָאֵל.</p>\n<p>דִּכְתִּיב וַיָּשָׁב הַיָּם לִפְנוֹת בֹּקֶר לְאֵיתָנוֹ, וְתָנֵינָן, לְאֵיתָנוֹ: לִתְנָאוֹ. לְהַהוּא תְּנַאי דְּהִתְנָה עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, כַּד בָּרָא עָלְמָא, לְאֵיתָנוֹ, כְּתִיב הָכָא לְאֵיתָנוֹ, וּכְתִיב הָתָם (תהילים פ״ט:א׳) מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, וְעַל דָּא לִפְנוֹת בֹּקֶר, בְּהַהוּא זִמְנָא דְּאַקְדִּים אַבְרָהָם לְמֶעְבַּד רְעוּתָא דְּמָארֵיהּ, כְּדֵין אִתְקְרַע יַמָּא, (הכא ויהם את מחנה מצרים) וְעַל דָּא קְשֵׁה הֲוָה קַמֵּיהּ קְרִיעַת יַם סוּף.</p>"],[9520011783,"<p>כְּגַוְונָא דָּא, קָשִׁין זִוּוּגִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא כִּקְרִיעַת יַם סוּף, מַה קְרִיעַת יַם סוּף קָטִיל לְאִלֵּין בְּהַאי סִטְרָא, וּמְקַיֵים לְאִלֵּין בְּהַאי סִטְרָא, אוּף הָכָא בְּזִוּוּגִין, כְּתִיב (תהילים ס״ח:ז׳) מוֹצִיא אֲסִירִים בַּכּוֹשָׁרוֹת, וְתָנֵינָן בְּכִי וְשִׁירוֹת, מַיִּית הַאי, וְיָהִיב אִתְּתֵיהּ לְהַאי, וּלְזִמְנִין לַחַיָּיבָא מִזְדַּמְנָא לֵיהּ אִתְּתָא מָעַלְיָא. אֲבָל רָזִין סְתִימִין אִינּוּן בְּכֹלָּא וְכֹלָּא הוּא בְּדִינָא, וּמַה דְּאִתְעֲרוּ חַבְרַיָּיא בְּהָא, וַדַּאי הָכִי הוּא.</p>\n<p>וּמַה דְּאִתְעֲרוּ לִפְנֵי, וְלא (קנ\"ג ע\"ב) מִלְּפָנַי, לִפְנֵי הַהוּא דְּקָאִים לִפְנֵי, קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְשִׁמֵּשׁ קַמֵּיהּ, וְעַל דָּא לָא אָמְרוּ דְּקָשִׁין זִוּוּגִין לְקוּדְשָׁא בְּרִיךְ הוּא. וְכֵן קָשִׁין מְזוֹנוֹתָיו שֶׁל אָדָם לְקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא לִפְנֵי, וּלְהַאי קַשְׁיָין כָּל הָנֵי, דְּהָא לָאו בִּרְשׁוּתֵיהּ קַיְימֵי, אַף עַל גַּב דְּאִיהוּ עָבִיד, בִּרְשׁוּתָא אַחֲרָא עָבִיד. (ד\"א ל\"ג אבל אף על גב דאיהו עביד)</p>\n<p>כְּתִיב (ויקרא כ״ב:ג׳) וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מִלְּפָנַי. מַאי מִלְּפָנַי. אֶלָּא דָּא עָלְמָא דְּאָתֵי, הַהוּא דְּכָל חַיִּין קַיְימִין תַּמָּן. דָּבָר אַחֵר, דָּא צִנּוֹרָא עִלָּאָה, נָהָר דְּלָא פַּסְקִין מֵימוֹי לְעָלְמִין. וְכֹלָּא חַד, וְדָא אִיהוּ דְּנָטִיל כָּל עִדּוּנִין דְּעָלְמָא דְּאָתֵי. וּמֵאִינּוּן עִדּוּנִין עִלָּאִין תִּשְׁתֵּצֵי, (האי נפש) מֵאֲתָר דְּהַהוּא נֹעַם יְיָ' תַּמָּן, וְדָא אִיהוּ מִלְּפָנַי.</p>\n<p>וְאִי תֵּימָא, אִי הָכִי, הָא כְּתִיב, (יונה א׳:ג׳) וַיָּקָם יוֹנָה לִבְרוֹחַ תַּרְשִׁישָׁה מִלִּפְנִי יְיָ' כִּי יָדְעוּ הָאֲנָשִׁים כִּי מִלִּפְנֵי יְיָ' הוּא בּוֹרֵחַ, וְתָנֵינָן מַאי טַעְמָא אָזַל יוֹנָה וּבָרַח, וְכִי מַאן יֵיכוּל לְמִבְרַח מִקָּמֵי קוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא הֲוָה אָזִיל וּבָרַח לְנָפְקָא מֵאַרְעָא קַדִּישָׁא, דְּהָא שְׁכִינְתָּא לָא שַׁרְיָא לְבַר מֵאַרְעָא דְּיִשְׂרָאֵל, וּבְגִין דְּלָא תִּשְׁרֵי עֲלוֹי שְׁכִינְתָּא, הֲוָה בְּרַח בְּאַרְעָא קַדִּישָׁא, דְּהָא שְׁכִינְתָּא אִיהִי שַׁרְיָא תַּמָּן, כְּמָה דְּאַתְּ אָמֵר (תהילים קכ״ח:ג׳) אֶשְׁתְּךָ כְּגֶפֶן פּוֹרִיָּה בְּיַרְכְּתֵי בֵיתֶךָ. גֶּפֶן פּוֹרִיָּה דָּא שְׁכִינְתָּא, מַה שְׁכִינְתָּא הֲוָה סְתִימָא לְגוֹ בְּבֵית קֹדֶשׁ הַקֳּדָשִׁים, <Nonei></i>אוּף הָכִי אִתְּתָא צְנִיעָא, לָא נָפְקָא מִתַּרְעָא דְּבֵיתָה לְבַר. וּבְגִינִי כַּךְ הֲוָה בְּרַח יוֹנָה לְבַר מֵאַרְעָא קַדִּישָׁא, וְהָא הָכָא כְּתִיב מִלִּפְנֵי, וְלָא כְּתִיב לִפְנֵי.</p>\n<p>אֶלָּא וַדַּאי הָכִי הוּא, מִלִּפְנֵי, דְּהָא רוּחַ נְבוּאָה לָא אַתְיָא מִגּוֹ שְׁכִינְתָּא, אֶלָּא מִלִּפְנֵי. אִינּוּן תְּרֵין דַּרְגִּין דִּנְבִיאִים, דְּקָא שַׁרְיָין עַל שְׁכִינְתָּא, וּמֵהַהוּא אֲתָר דָּחִיל לְמֶהוֵי תַּמָּן בְּאַרְעָא קַדִּישָׁא, וְעַל דָּא מִלִּפְנֵי. כִּי מִלִּפְנִי יְיָ' הוּא בּוֹרֵחַ, וְלָא לִפְנִי יְיָ', דְּהָא הֲוָה יָדַע דִּנְבוּאָה לָא הֲוָה אָתֵי אֶלָּא מִלִּפְנֵי.</p>\n<p>וּבְגִינֵי כַּךְ קָשִׁין זִוּוּגִין, קָשִׁין מְזוֹנוֹתָיו שֶׁל אָדָם לִפְנִי הַקָדוֹשׁ בָּרוּךְ הוּא, וְעַל דָּא דָּוִד מַלְכָּא תָּלֵי מְזוֹנוֹתָיו לְעֵילָּא, בְּגִין דִּלְעֵילָּא לָא פָּסִיק לְעָלְמִין. אֲבָל הָכָא פָּסִיק, דְּהָא לָא תַּלְיֵין בֵּיהּ מְזוֹנוֹת. לְעֵילָּא אִינּוּן. וְעַל דָּא כְּתִיב, (תהילים כ״ג:א׳) יְיָ' רֹעִי לָא אֶחְסָר, לָא יִפְסְקוּן מְזוֹנוֹת מִנִּי לְעָלְמִין, בְּגִין דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק מֵעֵדֶן לָא פָּסִיק לְעָלְמִין, וּבְגִין דָּא קַדְמָא שְׁכִינְתָּא עַל דָּא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּהַאי אֲתָר מְקַבְּלָא מְזוֹנָא מִלְּעֵילָּא, כֻּלְּהוּ דִּמְקַדְּשֵׁי לְמָארֵיהוֹן, כֻּלְּהוּ מִתְעַדְּנִין, וּמִתְעָרִין, וְסַלְּקִין גַּדְפִין, כַּד אַתְיָא שְׁכִינְתָּא בְּהַהוּא מְזוֹנָא, בְּגִין דְּלָא יִסְתַּכְּלוּן בָּהּ.</p>\n<p>וְאִינּוּן תְּלַת מַשִּׁרְיָין בִּסְלִיקוּ חַד, קָרָאן וְאַמְרֵי (ישעיה ו) קָדוֹשׁ. קָרָאן אִלֵּין לְּמַשִׁרְיָיתָא תִּנְיָינָא, וְסַלְּקִין גַּדְפִּין אִלֵּין קַדְמָאֵי, וְאִלֵּין תִּנְיָּינֵי, וְאָמְרִין אִלֵּין תִּנְיָּינִי קָדוֹשׁ. קָרָאן אִלֵּין לְּמַשִׁרְיָּיתָא תְּלִיתָאָה, וְסַלְּקִין גַּדְפִּין תְּלַת מַשִּׁרְיָין כַּחֲדָא, וְכֻלְּהוּ אַמְרֵי קָדוֹשׁ יְיָ' צְבָאוֹת מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. וְעַל דָּא כֻּלְּהוּ מְשֻׁלָּבָן דָּא בְּדָא, אִלֵּין עָאלִין לְגוֹ אִלֵּין, וְאִלֵּין עָאלִין לְגוֹ אִלֵּין, מְשֻׁלָּבָן דָּא בְּדָא, כְּמָה דְּאַתְּ אָמַר מְשׁוּלָּבוֹת אִשָּׁה אֶל אֲחוֹתָהּ כֵּן תַּעֲשֶׂה לְכָל קַרְשֵׁי הַמִּשְׁכָּן.</p>\n<p>קְרָשִׁים קַיְימֵי תָּדִיר בְּקִיּוּמַיְיהוּ, וְלָא מִתְכַּפְפֵי, כְּגַוְונָא דְּאִינּוּן עוֹמְדִים, דְּלָא מִתְכַּפְפֵי דְּלֵית לוֹן קְפִיצֵי, וְקַיְימֵי תָּדִיר בְּלָא יְשִׁיבָה, וְעַל דָּא כְּתִיב בַּקְרָשִׁים עוֹמְדִים.</p>\n<p>מָה כְּתִיב, שְׁתֵּי יָדוֹת לַקֶּרֶשׁ הָאֶחָד, אוּף הָכִי, בִּתְרֵי גְּוָונֵי אִינּוּן כְּלִילָן כֹל חַד וְחַד מִנַּיְיהוּ, הַהוּא דִּילֵיהּ וּדְחַבְרֵיהּ, וְחַבְרֵיהּ אוּף הָכִי בֵּיהּ, וְעַל דָּא מְשֻׁלָּבָן דָּא עִם דָּא. (דא נטיל דיליה ודחבריה, ודא נטיל דיליה ודחבריה).</p>\n<p>כְּגַוְונָא דָּא כְּתִיב בְּאוֹרַיְיתָא, (משלי ג׳:י״ד) כִּי טוֹב סַחְרָהּ מִסְּחַר כָּסֶף וּמֵחָרוּץ תְּבוּאָתָהּ, דָּא אוֹלִיף לְדָא, וְדָא אוֹלִיף לְדָא, אִתְעֲבָדוּ מְשֻׁלָּבָן דָּא עִם דָּא. דָּא נָטִיל דִּילֵיהּ וּדְחַבְרֵיהּ, וְדָא נָטִיל דִּילֵיהּ וּדְחַבְרֵיהּ, וּמְשֻׁלָּבָן דָּא בְּדָא.</p>\n<p>כְּתִיב בִּנְאוֹת דֶּשֶׁא יַרְבִּיצֵנִי עַל מֵי מְנוּחוֹת יְנַהֲלֵנִי. נְאוֹת דֶּשֶׁא, אִלֵּין אִינּוּן מְקוֹרִין עִלָּאִין, דְּכָל מְזוֹנָא וְסִפּוּקָא אַתְיָא מִנַּיְיהוּ. נְאוֹת אִלֵּין אִקְרוּן (איכה ב׳:ב׳) נְאוֹת יַעֲקֹב. נְאוֹת דֶּשֶׁא, בְּגִין דְּאִית נְאוֹת לְבַר דְּאִקְרוּן (יואל ב׳:כ״ב) נְאוֹת מִדְבָּר, וְעַל דָּא בִּנְאוֹת דֶּשֶׁא. וְאִי תֵּימָא הָא כְּתִיב תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא, דְּהָא אִיהוּ לְתַתָּא. אֶלָּא דֶּשֶׁא מֵאִינּוּן נְאוֹת אַתְיָא דְּאִתְיְילִיד וְאַצְמַח מִנַּיְיהוּ, וְעַל דָּא בִּנְאוֹת דֶּשֶׁא יַרְבִּיצֵנִי.</p>\n<p>עַל מֵי מְנוּחוֹת יְנַהֲלֵנִי, אִלֵּין מַיִין דְּנַיְיחָא, דְּקָא נַגְדִּין מֵהַהוּא אֲתָר דְּנָגִיד וְנָפִיק מֵעֵדֶן, וְאִינּוּן מַיִין אִקְרוּן מֵי מְנוּחוֹת. נַפְשִׁי יְשׁוֹבֵב דָּא הוּא נֶפֶשׁ דָּוִד, וְלָא בָּעָא דָּוִד לְאַתְקְנָא אֶלָּא לְהַהוּא דַּרְגָּא דִּילֵיהּ כְּדְקָא יֵאוֹת. בְּאִלֵּין מֵי מְנוּחוֹת, זְמִינִין צַדִּיקַיָּא לְנַיְיחָא לְעָלְמָא דְּאָתֵי, דִּכְתִּיב, (ישעיה נח) וְנָחֲךָ יְיָ' תָּמִיד וְגוֹ'.</p>"],[9520011784,"<p>(שמות כ״ו:י״א) וְעָשִׂיתָ קַרְסֵי נְחֹשֶׁת חֲמִשִׁים וְגוֹ'. רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא הֲווֹ יַתְבֵי לֵילְיָא חַד. כַּד רָמַשׁ לֵילְיָא, עָאלוּ גּוֹ גִּנָּא דְּעַל יַמָּא דִּטְבֶרְיָא. אַדְּהָכִי, חָמוּ תְּרֵין כֹּכָבַיָא דְּנַטְלֵי, דָּא מֵהָכָא, וְדָא מֵהָכָא, וְאִעֲרָעוּ דָּא בְּדָא וְאִטְמָרוּ.</p>\n<p>אָמַר רַבִּי אַבָּא, כַּמָה רַבְרְבָן עוֹבָדֵי דְּקוּדְשָׁא בְּרִיךְ הוּא, בִּשְׁמַיָּא מִלְּעֵילָּא, וּבְאַרְעָא מִלְּרַע. מַאן יָכִיל לְמִנְדַּע בְּאִלֵּין תְּרִין כֹּכָבַיָא, דְּנַפְקוּ חַד מֵהָכָא, וְחַד מֵהָכָא וְאִעֲרָעוּ דָּא בְּדָא, וְאִטְמָרוּ. אֲמַר לֵיהּ רַבִּי אֶלְעָזָר וְכִי לָא חֲמֵינָא לוֹן, הָא אַשְׁגַּחְנָא בְּהוּ, וְאַשְׁגַּחְנָא בְּכַמָּה עוֹבָדִין אַחֲרָנִין <Nonei></i>דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד תָּדִיר.</p>\n<p>פָּתַח וְאָמַר (תהילים קמ״ז:ה׳) גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ וְגוֹ' גָּדוֹל וְרַב וְעִלָּאָה אִיהוּ קוּדְשָׁא בְּרִיךְ הוּא. וְכִי לָא יָדַעְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא גָּדוֹל אִיהוּ וְרַב כֹּחַ, מַאי שְׁבָחָא דְּדָוִד הָכָא.</p>\n<p>אֶלָּא בְּכָל אֲתָר אִיהוּ אָמַר (תהלים קמה) גָּדוֹל יְיָ', וְהָכָא אָמַר גָּדוֹל אֲדוֹנִינוּ. מַאי טַעְמָא. אֶלָּא הָתָם דְּאִיהוּ אָמַר גָּדוֹל יְיָ' וּמְהֻלָל מְאֹד. בְּדַרְגָּא עִלָּאָה קָאָמַר. וְהָכָא דִּכְתִּיב גָּדוֹל אֲדוֹנֵינוּ בְּדַרְגָּא תַּתָּאָה קָאָמַר, דְּאִיהוּ אֲדוֹן כָּל הָאָרֶץ. מָה כְּתִיב לְעֵילָּא מֵהַאי קְרָא, מוֹנֶה מִסְפָּר לַכֹּכָבִים לְכֻלָּם שֵׁמוֹת יִקְרָא. אִי כָּל בְּנֵי עָלְמָא מִיּוֹמָא דְּאִתְבְּרֵי אָדָם, יִתְכַּנְּשׁוּן לְמִמְנֵי כֹּכָבַיָא, לָא יַכְלִין לְמִמְנֵי, כְּמָה דְאַתְּ אָמֵר (בראשית ט״ו:ה׳) וּסְפוֹר הַכֹּכָבִים אִם תּוּכַל לִסְפּוֹר אוֹתָם. וְקוּדְשָׁא בְּרִיךְ הוּא מַה כְּתִיב בֵּיהּ, מוֹנֶה מִסְפָּר לַכֹּכָבִים לְכֻלָּם שֵׁמוֹת יִקְרָא. מַאי טַעְמָא. בְּגִין דִּכְתִּיב גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ וְגוֹ'. כְּמָה דְּלֵית מִסְפָּר לְכֹּכְבֵי שְׁמַיָא, בַּר מִנֵּיהּ. אוּף הָכִי אִיהוּ כְּתִיב בֵּיהּ, וְלִתְבוּנָתוֹ אֵין מִסְפָּר.</p>\n<p>תָּא חֲזִי, כְּתִיב (ישעיהו מ׳:כ״ו) הַמּוֹצִיא בְמִסְפָּר צְבָאָם וְגוֹ', כֻּלְּהוּ חַיָּילִין וּמַשִּׁרְיָין וְכֹכָבַיָּא, קוּדְשָׁא בְּרִיךְ הוּא אַפִּיק לוֹן בִּשְׁמָא, כָּל חַד וְחַד, וְלָא גָּרַע אֲפִילּוּ חַד. בְּכָל כֹּכָבַיָּא וּמַזָּלֵי דִּרְקִיעִין כֻּלְּהוּ, אִתְמְנוּן נְגִּידִין וּפְקִידִּין לְשַׁמְּשָׁא עָלְמָא, כָּל חַד וְחַד כַּדְקָא חֲזִי לֵיהּ. וְלֵית לָךְ עִשְׂבָּא זְעִירָא בְּכָל עָלְמָא, דְּלָא שַׁלְטָא עָלֵיהּ כֹּכָבָא וּמַזָּלָא בִּרְקִיעָא, וְעַל הַהוּא כֹּכָבָא מְמָנָא חַד, דְּקָא מְשַׁמֵּשׁ קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, כָּל חַד וְחַד כַּדְקָא חֲזִי לֵיהּ.</p>\n<p>כָּל כֹּכָבַיָּא דְּבִרְקִיעִין כֻּלְּהוּ מְשַׁמְּשֵׁי עַל הַאי עָלְמָא, וְכֻלְּהוּ פְּקִידָן לְשַׁמְּשָׁא כָּל מִלָּה וּמִלָּה, לְאִינּוּן דִּבְּהַאי עָלְמָא, וְלָא צַמְחִין וְלָא מְגַדְּלִין עֲשָׂבִין וְאִלָנִין וּדְשָׁאִין, וְעִשְׂבֵי בָּרָא, בַּר בְּחֵיזוּ דְּכֹּכָבַיָּא דְּקָא קַיְימֵי עָלַיְיהוּ, וְאִתְחָזוּן עָלַיְיהוּ אַנְפִּין בְּאַנְפִּין, כָּל חַד וְחַד כְּמָה דְּאִתְחָזֵי לֵיהּ.</p>\n<p>רוֹב מַשִּׁרְיָין דְּכֹּכָבַיָּא וּמַזָּלֵי, כֻּלְּהוּ נָפְקִין בְּרֵאשִׁיתָא דְּלֵילְיָא, עַד תְּלַת שַׁעְתֵּי חָסֵר רְבִיעָא. מִתַּמָּן וּלְהָלְאָה לָא נָפְקִין בַּר זְעִירִין. וְאִינּוּן כֹּכָבַיָּא כֻּלְּהוּ לָא מְשַׁמְשֵׁי לְבַטָּלָה, וְלָא אִתְחָזוּן לְבַטָּלָה. וְאִית כֹּכָבַיָא דְּקָא מְשַׁמְשֵׁי כָּל לֵילְיָא, בְּגִין לְאַצְמְחָא וּלְגַדְּלָא כָּל אִינּוּן מִלִּין דְּאִתְפְּקָדוּ עָלַיְיהוּ. וְאִית כֹּכָבַיָּא דְּקָא מְשַׁמְשֵׁי עַד פַּלְגוּת לֵילְיָא, וְצָמְחִין וּמְגַדְּלִין מֵרֵאשִׁיתָא דְּלֵילְיָא, עַד הַהִיא שַׁעֲתָא, כָּל אִינּוּן מִלִּין דְּאִתְפְּקָדוּ עָלַיְיהוּ. וְאִית כֹּכָבַיָא דְּקָא מְשַׁמְשֵׁי זְעֵיר מִלֵילְיָא, דְּכֵיוָן דְּאִתְחָזֵי בַּהֲדֵי הַהוּא עִשְׂבָּא, אוֹ הַהוּא דְּשָׁאָה, מִיָּד אַשְׁלִים שִׁמוּשֵׁיהּ, וְלָא אִצְטְרִיךְ יַתִּיר בְּהַהוּא לֵילְיָא. וְהָא אִינּוּן לָא קַיְימִין לְבַטָּלָה, כֵּיוָן דְּאַשְׁלִימוּ שִׁמּוּשַׁיְיהוּ, לָא אִתְחָזוּן יַתִּיר בְּהַאי עָלְמָא, וְעַיְילִין לְאַתְרַיְיהוּ.</p>\n<p>בְּסִפְרָא דְּחָכְמְתָא עִלָּאָה דִּבְנֵי קֶדֶם, אַמְרֵי עַל כָּל אִינּוּן כֹּכָבַיָא (ויחי רכ\"ג ע\"א, ויקרא רל\"א ע\"ב) דְּשַׁרְבִיטָא, דְּקָא מְשַׁדְּרֵי שַׁרְבִיטָא בִּרְקִיעָא, אַמְרִי דַּעֲשָׂבִין אִינּוּן בְּאַרְעָא, מֵאִינּוּן דְּאִקְרוּן סַמֵי דְּחַיֵּי, וְאַבְנִין יַקִירָן אִית בְּאַרְעָא, וְזָהָב שָׁחוּט דִּמְגַּדְלָא גּוֹ טוּרֵי רָמָאֵי, בִּזְעֵיר מַיִין דְּחַפְיָא עָלֵיהּ, וְלָא חַפְיָא אֶלָּא דְּנָגִיד עָלֵיהּ, וְשָׁלְטָאן עַל כָּל אִלֵּין אִינּוּן כֹּכָבַיָּא דְּשַׁרְבִיטָא, וּמְגַּדְלֵי אִלֵּין בְּגִינַיְיהוּ.</p>\n<p>וְכָל תִּקּוּנָא וּגְדוּלָא דִּלְהוֹן, לָאו אִיהוּ אֶלָּא בְּחֵיזוּ וְנֹגְהָא דְּהַהוּא שַׁרְבִיטָא, דְּקָא מְשַׁדֵּר הַהוּא כֹּכָבָא, גּוֹ רְקִיעָא, וּכְדֵין אִתְתַּקְנָן וּמִתְגַּדְלָן כָּל אִינּוּן מִלִּין.</p>\n<p>מַרְעִין אִית בִּבְנֵי נָשָׁא, כְּגוֹן יְרוֹקִין וְקַסְטִירִין. דְּאַסְוָותָא דִּלְהוֹן לָא תָּלֵי, אֶלָּא בְּחַד מַרְאֶה דְּפַרְזְלָא קָלִיל נָצִיץ לְעַיְינִין, וְאִית לֵיהּ לְמָארֵיהּ דְּמַרֵע לְאִסְתַּכְּלָא בֵּיהּ. וְלָא (נ\"א שכיך) שַׁיָּיךְ (ס\"א אתסי) בְּהַאי עַד דְּאַעְבַּר הַהוּא מַרְאֶה לְסִטְרָא דָּא וּלְסִטְרָא דָּא, כְּגַוְונָא דְּשַׁרְבִיטָא, דְּיוֹשִׁיט נְצִיצוּ דְּבָרָק לְאַנְפּוֹי, וּבְהַהוּא אוֹשִׁיטוּ דְּבָרָק דְּקָא נָצִיץ לְעַיְינִין, אָתֵי לֵיהּ אַסְוָותָא. אוּף הָכִי, כָּל אִינּוּן דְּשַׁלְטֵי עָלַיְיהוּ אִינּוּן כֹּכָבַיָא, לֵית לוֹן תִּקּוּנָא וּגְדוּלָא בַּמֶּה דְּאִתְחָזֵי, בַּר הַהוּא פְּשִׁיטוּ דְּשַׁרְבִיטָא, וּבְהַאי מִתַּתְקְנֵי, בְּחֵיזוּ, <Nonei></i>בְּגָוְון, בְּחֵילָא, כְּמָה דְּאִתְחָזֵי.</p>\n<p>וְשַׁפִּיר אִיהוּ, דְּהָא כְּגַוְונָא דָּא, רָמִיז בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, בְּחָכְמְתָא דְּאַבְנִין יְקִירִן, דְּאִי חָסֵר מִנְּהוֹן נֹגְהָא דִּנְצִיצוּ וּלְהִיטוּ דְּכֹּכָבַיָּא יְדִיעָן, לָא מְגַדְּלִין, וְלָא (ס\"א מתתקנין לעלמין) מְתַקְּנֵי לוֹן לְעָלְמִין, וְכֹלָּא אַתְקִין קוּדְשָׁא בְּרִיךְ הוּא לְתִקּוּנָא דְּעָלְמָא, כְּמָה דְאַתְּ אָמֵר (בראשית א׳:ט״ו) לְהָאִיר עַל הָאָרֶץ, בְּכָל מַה דְּאִצְטְרִיךְ בְּהַאי עָלְמָא לְתַקְּנָא לֵיהּ.</p>\n<p>כְּתִיב (שמותכו) וְעָשִׂיתָ קַרְסֵי נְחֹשֶׁת חַמִשִׁים, וּכְתִיב וְעָשִׂיתָ חַמִשִׁים קַרְסֵי זָהָב, וְתָנֵינָן, מַאן דְּלָא חָמָא אִינּוּן קְרָסִים בְּמַשְׁכְּנָא, לָא חָמָא נְהִירוּ דְּכֹּכָבַיָּא בִּרְקִיעָא, בְּגִין דִּבְהַהוּא חֵיזוּ, וּבְהַהוּא גַּוְונָא, דַּמְיָין לְכָל מַאן דְּאִסְתָּכַּל בְּהוּ.</p>\n<p>כֹּכָבַיָא אִית בִּרְקִיעָא, דְּאִלֵּין נַפְקֵי מֵהַהוּא רְקִיעָא, דְּכָל כֹּכָבַיָא אַדּוּקִין תַּמָּן. בְּהַהוּא רְקִיעָא אִית מְאָה חַלוֹנִי מַשְׁקוֹפִין, מִנְּהוֹן לִסְטַר מִזְרָח, וּמִנְּהוֹן לִסְטַר דָּרוֹם. וּבְכָל חַלוֹנָא וְחַלוֹנָא כֹּכָבָא חַד.</p>\n<p>וְכַד שִׁמְשָׁא אָזִיל בְּאִינּוּן חַלּוֹנִין וּמַשְׁקוֹפִין דִּי בִּרְקִיעָא נָצִיץ בִּנְצִיצוּ, וְאִלֵּין כֹּכָבַיָּא נַפְקֵי לְאִתְנַצְּצָא מֵהַהוּא נְצִיצוּ דְּשִׁמְשָׁא וְאִצְטָבָּעוּ, מִנְהוֹן סוּמָקִין כְּגַוְונָא דִּנְחֹשֶׁת, וּמִנְהוֹן יְרוֹקִין כְּגַוְונָא דְּזָהָב, וְעַל דָּא, אִלֵּין סוּמָקִין, וְאִלֵּין יְרוֹקִין. חַמִשִּׁים אִינּוּן בְּאִינּוּן חַמִשִּׁים חַלּוֹנִין, (נ\"א וחמשים אינון באינון חלונין) אַחֲרָנִין. דְּלִסְטַר מִזְרָח אִינּוּן יְרוֹקִין, דְּלִסְטַר דָּרוֹם אִינּוּן סוּמָקִין, בְּהוּ אִתְאֲחָד סִיּוּמָא דְּמַשְׁכְּנָא.</p>\n<p>בְּכָל אִינּוּן כֹּכָבַיָא דְּנַפְקֵי מֵהַהוּא רְקִיעַ, מִתְעָרְבֵי אִינּוּן כֹּכָבַיָא בְּלֵילְיָא, וְנַצְצֵי וּמְלַהֲטֵי וְשַׁלְטֵי בְּהַאי עָלְמָא. מִנְהוֹן עַל נְחֹשֶׁת, מִנְהוֹן עַל זָהָב יְרַקְרָק, וְאִתְתַּקְנָן וּמְגַּדְלָן עַל חֵילָא דִּלְהוֹן.</p>\n<p>אִלֵּין כֹּכָבַיָא שַׁלְטֵי בְּכ\"ה וּפַלְגָּא נְקוּדִין דְּלֵילְיָא, דְּאִינּוּן רִגְעֵי שַׁעֲתָא, וְאִינּוּן דִּמְגַּדְלֵי נְחֹשֶׁת דְּאִינּוּן סוּמָקֵי וְלַהֲטֵי וְנַצְצֵי. וְכַד אוֹשִׁיטוּ תְּלָת זִמְנִין נְצִיצוּ לְסִטְרָא דְּמִזְרָח, אוֹ חֲמֵשׁ, אוֹ שֶׁבַע, מַלְכֵי עַמִּין יִיִתוּן עַל הַהוּא סִטְרָא, וְכָל עֻתְרָא וְדַהֲבָא יִסְתַּלָּק מֵהַהוּא סִטְרָא. וְאִי נְצִיצוּ חַד, תְּרֵין, אַרְבַּע, שִׁית, דָּא בָּתַר דָּא, אֵימָתָא וּפַחֲדָא יִפּוֹל, וְיִשְׁרֵי עַל הַהוּא סִטְרָא. בָּטִישׁ נְצִיצוּ וְשָׁכִיךְ, בָּטִישׁ נְצִיצוּ וְשָׁכִיךְ, יִתְּעֲרוּ קְרָבֵי, וְלָא יִתְעַבִידוּ, (ד\"א בעלמא בההוא סטרא) דְּהָא בְּהַהוּא זִמְנָא, אִתְעֲרוּתָא הוּא לְעֵילָּא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בְּאִינּוּן מְמָנָן דְּעָלְמָא דְּשַׁלְטִין עַל שְׁאַר עַמִּין, וְכֵן כְּגַוְונָא דָּא בְּסִטְרָא אַחֲרָא.</p>\n<p>פָּתַח וְאָמַר, (דניאל ב׳:כ׳) לֶהוֵא שְׁמֵיהּ דִּי אֱלָהָא מְבָרַךְ מִן עָלְמָא וְעַד עָלְמָא דִּי חָכְמְתָא וּגְבוּרְתָּא דִּילֵיהּ הִיא. וְהוּא מְהַשְׁנֵא עִדָּנַיָּא וְזִמְנַיָא. וְכֹלָּא אִיהוּ בִּרְשׁוּתֵיהּ, וְאַפִּיק לְעַמֵּיהּ קַדִּישָׁא, מֵחֵילָא וּרְשׁוּתָא דְּכֹּכָבַיָּא וּמַזָּלֵי, בְּגִין דְּאִינּוּן טַעֲוָון אַחֲרָן וְלָא בְּאִלֵּין חוּלָקָא דְּיַעֲקֹב, כִּי אִם (ירמיה י) בְּיוֹצֵר הַכֹּל הוּא.</p>\n<p>רָקִיעַ אִית לְעֵילָּא, עַל כָּל אִלֵּין רְקִיעִין, וְאִיהוּ טָמִיר וְגָנִיז, וְחוֹתָמָא דְּגוּשְׁפַּנְקָא דְּמַשְׁכְּנָא שַׁלְטָא עַל הַאי רָקִיעַ, וְהַאי רָקִיעַ אִקְרֵי אִדָּרָא דְּמַשְׁכְּנָא, וּבְהַאי רָקִיעַ כָּל אִינּוּן חַלּוֹנִין, מִסִּטְרָא דָּא, וּמִסִּטְרָא דָּא, וְאָחִיד כָּל אִינּוּן סִדּוּרִין דְּמַשְׁכְּנָא. שִׁית (בלק קפ\"ג ע\"ב) חַלּוֹנִין אִינּוּן רַבְרְבִין עַל כֻּלְּהוּ, וְחַד סָתִים לְשַׁלְטָא עָלַיְיהוּ.</p>\n<p>חַלוֹנָא חַד, אִקְרֵי חַלוֹן זָהֳרָא, וּבֵיהּ נָפְקָא כֹּכָבָא חֲדָא, דְּאִקְרֵי לְחַכִּימֵי יַ\"ד, וְדָא אִיהוּ הִתּוּכָא דְּקָא מְהַתֵּךְ לְתַתָּא בְּשֻׁלְטָנוּתָא דִּיהוּדָה. לָאו דְּאִית לֵיהּ חוּלָקָא בֵּיהּ, דְּהָא לֵית לַשְּׁבָטִין דְּיִשְׂרָאֵל חוּלָקָא וְאַחֲסָנָא בְּהוּ, אֶלָּא שִׁבְטָא דִּיהוּדָה שַׁלְטָא עַל הַאי, וְלָאו אִיהוּ עָלֵיהּ.</p>\n<p>וְכַד אַסְטוּ בְּנֵי יְהוּדָה אָרְחַיְיהוּ מִבָּתַר קוּדְשָׁא בְּרִיךְ הוּא, אָזְלוּ לְמִנְדַּע בָּתַר חַלוֹנָא דָּא, וְהַאי כֹּכָבָא. וְאָמְרוּ (ס\"א דהא ידע) דְּהַאי יְדָא דְּקָא מְנַצַּח לִשְׁאַר עַמִּין, דִּכְתִּיב בֵּיהּ (בראשית מ״ט:ח׳) יָדְךָ בְּעֹרֶף אוֹיְבֶיךָ, וְאָזְלוּ אֲבַתְרֵיהּ וְעַבְדּוּ לֵיהּ שִׁמּוּשָׁא וּפֻלְחָנָא, וְעַל דָּא כְּתִיב, (מלכים א י״ד:כ״ב) וַיַּעַשׂ יְהוּדָה הָרַע בְּעֵינֵי יְיָ'.</p>\n<p>הַאי כֹּכָבָא כַּד נָפִיק פָּשִׁיט חַד יָד בַּחֲמֵשׁ אֶצְבְּעָן, נָהִיר וְנָצִיץ בְּהַהוּא חַלוֹן. <Nonei></i>מָארֵיהוֹן דְּקוּסְמִין וְחֲרְשִׁין, דַּחֲלֵי מֵהַאי אֲתָר, בְּגִין דִּבְשַׁעֲתָא דְּהַאי שַׁלְטָא, כֻּלְּהוּ קְסָמִין וְחֲרְשִׁין מִתְבַּלְבְּלֵי, וְלָא אַצְלַח בִּידַיְיהוּ.</p>\n<p>וְאִי תֵּימָא, הוֹאִיל וְאִיהוּ הַאי רָקִיעַ טְמִירָא, הֵיךְ יַדְעֵי לֵיהּ. אֶלָּא סִימָנָא אִית לוֹן לְבַר, וְיַדְעֵי דְּהָא שַׁלְטָא כֹּכָבָא דָּא, וְדַחֲלֵי תָּדִיר מִנֵּיהּ, וְלָא אַצְלַח בִּידֵיהוֹן, אִינּוּן קְסָמִין וְחֲרְשִׁין. וְעַל דָּא אִית זִמְנִין דְּאַצְלָחוּ בֵּיהּ בְּנִי נָשָׁא, וְאִית זִמְנִין דְּלָא אַצְלָחוּ בֵּיהּ. וּבְגִין דָּא אִינּוּן מָארֵי קוּסְמִין וְחֲרְשִׁין מִתְמַעֲטֵי מֵעָלְמָא, בְּגִין דְּלָא יַדְעִין עִקָרָא, כַּד חָמָאן דְּלָא אַצְלַח בִּידַיְיהוּ. וְעַל דָּא אִינּוּן קַדְמָאֵי הֲווֹ יַדְעֵי, וּמִסְתַּכְּלָן לְבַר בְּהַהוּא סִימָנָא, דְּקָא יַדְעֵי.</p>\n<p>חַלוֹנָא תִּנְיָינָא, אִקְרֵי חַלוֹן טוּפְרָא, בְּגִין דְּאִיהוּ כְּגַוְונָא דְּטוּפְרָא, וּבֵיהּ נָפְקָא כֹּכָבָא חַד, דְּאִקְרֵי לְחַכִּימִין צִפְעוֹן, דְּהָא דָּא שַׁלְטָא בְּשׁוּלְטָנָא תַּקִּיף בְּדִינָא בְּרֵישָׁא וְזַנְבָא, אִית לֵיהּ כְּצִפְעוֹן כָּמִין לְקָטְלָא.</p>\n<p>מֵהַהוּא חַלוֹן, נַפְקֵי שִׁית מֵאָה אֶלֶף רִבּוֹא רוּחִין, דְּשַׁלְטִין עַל אִינּוּן טוּפְרִין דִּבְנֵי נָשָׁא, כַּד אִזְדַרְקָן בְּאִתְגַּלְּיָא. בְּהַאי עַבְדֵי חֲרָשִׁין וּקְסָמִין, כָּל אִינּוּן דְּיַדְעֵי לוֹן. בְּהַהִיא שַׁעֲתָא דְּהַאי כֹּכָבָא שַׁלְטָא, כָּל אִינּוּן דְּזַרְקֵי טוּפְרֵי, (ס\"א אי עביד) אוֹ עַבְדֵי חֲרָשִׁין בְּהוֹן, גָּרִים מוֹתָא לְכָל עָלְמָא, וְסָלִיק חֲרָשִׁין בִּידַיְיהוּ דְּאִינּוּן דְּעַבְדֵי לוֹן.</p>\n<p>חַלוֹנָא תְּלִיתָאָה, אִקְרֵי חַלוֹן חוֹשְׁנָא, וּבֵיהּ נָפְקָא כֹּכָבָא חֲדָא, וְאִקְרֵי נִגְהָ\"א דְּבוּסִי\"נָא, (נ\"א דבוציני) הַאי אִיהוּ נְצִיצוּ דְּנָצִיץ, וְקַיְּימָא עַל כָּל רוּחָא, וְנַיְיחָא וְשֵׁיזְבוּתָא (נ\"א וטיבותא) בֵּיהּ. לֵית בֵּיהּ קִטְרוּגָא כְּלַל, כַּד אִיהוּ שַׁלְטָא, כָּל נַיְיחָא, וְכָל נְהִירוּ שַׁלְטָא בְּעָלְמָא, שַׁלְוָה שָׂבְעָא וְכֹלָּא שַׁלִּיט בְּעָלְמָא.</p>\n<p>חַלוֹנָא רְבִיעָאָה, אִיהוּ חַלוֹן דְּאִקְרֵי גְּבִיעַ, וּבֵיהּ נָפְקָא כֹּכָבָא חַד, דְּאִקְרֵי לְחַכִּימִין אֶשְׁכּוֹל הַכֹּפֶר, בְּגִין דְּהָכִי נָפִיק כְּאֶשְׁכּוֹל, נָצִיץ נְצִיצִין כַּעֲנָבִין בְּכּוֹפָרָא, בְּהַאי אִתְּעָרוּ דְּרַחֲמֵי אִתְּעַר בְּעָלְמָא, מַרְחִיק וּמַקְרִיב, תּוֹלָדִין סַגִּיאִין אַסְגִּיאוּ בְּעָלְמָא. בְּנֵי עָלְמָא לָא קַפְדֵּי כַּד אִצְטְרִיכוּ דָּא לְדָא, שְׁלָמָא וְחֶדְוָה אִתְּעַר בְּעָלְמָא.</p>\n<p>חַלוֹנָא חֲמִישָׁאָה, אִיהוּ חַלוֹן דְּאִקְרֵי בְּאֵר, עַל דִּי כֹּכָבָא דְּנָפִיק בֵּיהּ, עָאל וְנָפִיק שָׁאִיב כַּדְּלִי, לָא שָׁכִיךְ לְעָלְמִין. בְּהַאי חַכִּימֵי לִבָּא לָא יַכְלִין לְמֵיקָם בְּאֹרַח קְשׁוֹט, בְּגִין דְּלָא קָאִים בְּקִיּוּמָא, וְלָא שָׁכִיךְ לְעָלְמִין. וְעַל דָּא אִתְדַּחֲקָן גַּרְמַיְיהוּ, לְעַיְּינָא בְּהַאי אֲתָר, וּלְמֵידַן דִּינָא.</p>\n<p>חַלוֹנָא שְׁתִּיתָאָה, אִיהוּ חַלוֹן דְּאִקְרֵי נֹגְהָא, וְנָפְקָא בֵּיהּ כֹּכָבָא חַד, דְּאַקְרִין גִּזְרוֹן, בְּגִין דְּכַד הַאי שַׁלְטָא, עָלְמָא קָאִים בְּדִינָא, וְכַמָּה גִּזְרִין, וּבְכַמָּה עוֹנָשִׁין, וּבְכָל יוֹמָא וְיוֹמָא מִתְחַדְּשָׁן גִּזְרִין עַל עָלְמָא, וְעַד לָא יְסַיְּימוּן אִלֵּין, הָא אַחֲרָנִין מִתְחַדְּשִין, וְהַאי לָא שַׁלְטָא כָּל כַּךְ בְּעָלְמָא.</p>\n<p>אֲבָל סָמוּךְ לְיוֹמֵי מְשִׁיחָא, יִשְׁלוֹט הַאי חַלוֹנָא, בְּהַאי כֹּכָבָא, עַל עָלְמָא. וְעַל דָּא יִשְׁלְטוּן חֵיוָן וּמַרְעִין בִּישִׁין עַל עָלְמָא, וְיִתְחַדְתּוּן זִינִין בִּישִׁין, דָּא בָּתַר דָּא, וְיִשְׂרָאֵל יְהוֹן בְּעָקוּ. וְכַד יִתְדַּחֲקוּן גּוֹ חֲשׁוֹכָא דְּגָלוּתָא, כְּדֵין יַנְהֵר לוֹן קוּדְשָׁא בְּרִיךְ הוּא נְהִירוּ דִּימָמָא, וִיקַבְּלוּן מַלְכוּתָא קַדִּישֵׁי עֶלְיוֹנִין, וְיִּתְבַּטֵּל מַלְכוּתָא מִידָא דְּעֲמְמִין עוֹבְדֵי כּוֹכָבִים, וְיִשְׁלְטוּן עָלַיְיהוּ יִשְׂרָאֵל, וְיִתְקַיֵּים (ישעיהו ל׳:כ״ו) וְהָיָה אוֹר הַלְּבָנָה וְגוֹ'.</p>\n<p>וּכְדֵין חַלוֹנָא שְׁבִיעָאָה יִתְפְּתַח בְּכָל עָלְמָא, וְכֹכָבָא דִּילֵיהּ אִיהוּ כֹּכָבָא דְּיַעֲקֹב, וְהַאי אִיהוּ דְּקָאָמַר בִּלְעָם, (במדבר כ״ד:י״ז) דָּרַךְ כֹּכָב מִיַּעֲקֹב, וְכֹכָבָא דָּא יְהֵא נָהִיר (נ\"א ד' יומין וד' לילין) אַרְבְּעִין (ח' ע\"א) יוֹמִין. (וארבעין לילין) וְכַד יִתְגְּלֵי מַלְכָּא מְשִׁיחָא, וְיִתְכַּנְּשׁוּן לְגַבֵּי מַלְכָּא מְשִׁיחָא כָּל עַמִּין דְּעָלְמָא, כְּדֵין יִתְקַיֵּים קְרָא דִּכְתִּיב, (ישעיהו י״א:י׳) שֹׂרֶשׁ יִשַׁי אֲשֶׁר עוֹמֵד לְנֵס עַמִּים אֵלָיו גּוֹיִם יִדְרֹשׁוּ וְהָיְתָה מְנוּחָתוֹ כָּבוֹד.</p>"],[9520011785,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (איוב ל״ה:י׳) וְלא אָמַר אַיֵּה אֱלוֹהַּ עֹשָׂי נוֹתֵן זְמִירוֹת בַּלַּיְלָה. הַאי קְרָא אוּקְמוּהָ וְאִתְּמַר, אֲבָל עוֹשָׂי, עוֹשִׂי מִבָּעֵי לֵיהּ, מַאן עוֹשָׂי. אֶלָּא שְׁמָא דְּאֱלוֹהַּ שְׁמָא כָּלִיל אִיהוּ דְּאִתְחָזֵי הוּא וּבֵי דִּינֵיהּ. דָּא שְׁמָא שְׁלִים אִיהוּ, דְּכָלִיל דְּכַר וְנוּקְבָּא: א\"ל ו\"ה וּבְגִינִי כַּךְ עוֹשָׂי.</p>\n<p>נוֹתֵן זְמִירוֹת בַּלַּיְלָה, בְּגִין דְּדָא אִיהוּ דְּקָא (ק\"ע ע\"א) מְשָׁבַּחַת תָּדִיר לְגַבֵּי מַלְכָּא דִּשְׁלָמָא דִּילֵיהּ, כְּגַוְונָא דְּבוּצִינָא דְּלָא שָׁכִיךְ תָּדִיר, בְּגִין לְקַבְּלָא נְהוֹרָא חֶדְוָה עִלָּאָה, מִסְּגִיאוּת <Nonei></i>חֶדְוָה דִּילֵיהּ. וְעַל דָּא נוֹתֵן זְמִירוֹת בַּלַּיְלָה.</p>\n<p>כָּל אִינּוּן כֹּכָבַיָא דְּקָא מְנָהֲרָן בִּרְקִיעָא, כֻּלְּהוּ אוֹדָאן וּמְשַׁבְּחָן לְקוּדְשָׁא בְּרִיךְ הוּא, בְּכָל הַהוּא זִמְנָא דְּאִתְחָזוּן בִּרְקִיעָא, בְּגִין דְּמַלְאֲכֵי עִלָּאֵי, כֻּלְּהוּ אוֹדָאן וּמְשַׁבְּחָן אַשְׁמוּרוֹת אַשְׁמוּרוֹת, בִּתְלַת פַּלְגֵּי דְּהַוְי לֵילְיָא.</p>\n<p>בְּלֵילְיָא אִתְפַּלְגָּן כַּמָּה סִטְרִין. בְּרֵאשִׁיתָא דְּלֵילְיָא, כַּד רָמַשׁ לֵילְיָא וְאִתְחֲשָׁךְ, כֹּל אִינּוּן רוּחִין בִּישִׁין וְּזִינִין בִּישִׁין, כֻּלְּהוּ מִתְבַּדְּרָן וְּמְשַׁטְטֵי בְּכָל עָלְמָא. וְאִתְפַּרְשַׁת סִטְרָא אַחֲרָא, וְתָבְעֵי אָרְחֵי דְּבֵי מַלְכָּא, מִכָּל אִינּוּן סִטְרִין קַדִּישִׁין.</p>\n<p>כֵּיוָן דְּהַהוּא סִטְרָא אַחֲרָא אִתְּעַר, כָּל בְּנֵי עָלְמָא טַעֲמֵי טַעֲמָא דְּמוֹתָא, (נ\"א דשינה) חַד מִשִׁתִּין בְּמוֹתָא, וְשַׁלְטָא עָלַיְיהוּ. כְּדֵין כֵּיוָן דִּמְסָאֳבוּ אִתְפָּרְשָׁא מִלְּעֵילָּא, וְשַׁלְטָא וְנַחְתָּא לְתַתָּא, כְּדֵין אִתְפָּרְשָׁן תְּלַת מַשִּׁרְיָין לְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בִּתְלַת סִטְרִין (נ\"א מטרין) דְּלֵילְיָא, כְּמָה דְּאִתְעֲרוּ בְּהַאי חַבְרַיָא.</p>\n<p>בְּעוֹד דְּאִינּוּן מְשַׁבְּחִין לְקוּדְשָׁא בְּרִיךְ הוּא, סִטְרָא אַחֲרָא אַזְלָא וּמְשַׁטְּטָא לְתַתָּא, בְּכָל סִטְרֵי עָלְמָא, וְעַד דְּסִטְרָא אַחֲרָא לָא אִתְעַבָּר מִתַּמָּן, לָא יַכְלִין אִינּוּן לְאִתְיַיחֲדָא בְּמָארֵיהוֹן.</p>\n<p>רָזָא לְחַכִּימִין, מַלְאֲכֵי עֶלְיוֹנִין, וְיִשְׂרָאֵל לְתַתָּא, כֻּלְּהוּ דָּחֲקֵי בְּהַהוּא סִטְרָא אַחֲרָא. מַלְאָכִין עִלָּאִין כַּד בָּעָאן לְאִתְיַיחֲדָא בְּמָארֵיהוֹן, לָא יַכְלִין עַד דְּדַחְיָין לָהּ לְבַר. מָה עַבְדִּין, נַחְתִּין שִׁיתִּין רִבּוֹא דְּמַלְאֲכֵי קַדִּישֵׁי, וַאֲפִילּוּ שֵׁינָתָא עַל כָּל בְּנֵי עָלְמָא, כֵּיוָן דְּאִיהִי נַחְתָּא, דְּקָא דַּחְיָּין לָהּ לְבַר, וְיָהֲבֵי לָהּ כָּל עָלְמָא דָּא בְּהַהִיא שֵׁינָתָא, כְּדֵין אִיהִי שַׁלְטָא עָלַיְיהוּ, וּמְקַבְּלִין מִסְאֲבוּ מִינָּהּ. בַּר בְּאַרְעָא דְּיִשְׂרָאֵל בִּלְחוֹדָהָא, דְּלָא (ק\"מ ע\"ב) שַׁלְטָא תַּמָּן. כֵּיוָן דְּאִיהִי אִתְפָּרְשָׁא מִנַּיְיהוּ, עָאלִין לְקָמֵי מָארִיהוֹן, וּמְשַׁבְּחָן וְאוֹדָאן קָמֵיהּ.</p>\n<p>כְּגַוְונָא דָּא יִשְׂרָאֵל לְתַתָּא, לָא יַכְלִין לְאִתְיַיחֲדָא בְּמָארֵיהוֹן, עַד דְּדַחְיָין לְהַהוּא סִטְרָא אַחֲרָא מִנַּיְיהוּ, וְיָהֲבֵי לָהּ חוּלָקָא בְּמָּה דְּאִתְעַסְקַת, וּלְבָתַר, אִינּוּן מִתְקָרְבֵי לְגַבֵּי מָארֵיהוֹן, וְלָא אִשְׁתְּכַח מְקַטְרְגָא עֵילָּא וְתַתָּא.</p>\n<p>וְאִי תֵּימָא תִּינַח לְתַתָּא, אֲבָל לְעֵילָּא מַאי קִטְרוּגָא תַּמָּן. אֶלָּא לְעֵילָּא, בְּגִין דְּאִיהוּ רוּחַ מְסַאֲבָא, וְאִינּוּן רוּחִין קַדִּישִׁין, עַד דִּמְשַׁדְּרֵי רוּחָא מְסַאֲבָא מִבֵּינַיְיהוּ, לָא יַכְלִין לְקָרְבָא לְגַבֵּי מָארֵיהוֹן, דְּהָא קוּדְשָׁא גּוֹ מְסַאֲבָא, לָא מִתְעָרֵב לְעָלְמִין. וְכֵן כְּגַוְונָא דָּא, יִשְׂרָאֵל לְתַתָּא, לָא מִתְעָרְבִין בְּאוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּעָלְמָא. וּתְרֵין סִטְרִין, עִלָּאִין וְתַתָּאִין, כַּד בַּעְיָין לְקָרְבָא לְגַבֵּי מַלְכָּא קַדִּישָׁא, דַּחְיָּין לָהּ לְבַר.</p>\n<p>וְעַל דָּא, כַּד עָיִיִל לֵילְיָא, וּמַלְאָכִין קַדִּישִׁין עִלָּאִין, כַּד מִסְתַּדְּרָן שׁוּרִין שׁוּרִין לְקָרְבָא (נ\"א לשבחא) לְגַבֵּי מָארִיהוֹן, דַּחְיָּין לֵיהּ לְהַהוּא סִטְרָא לְבַר בְּקַדְמִיתָא, וּלְבָתַר עָאלִין בְּקוּדְשָׁא. (נ\"א ועל דא, כד עייל ליליא כל רוחין בישין וזינין בישין ורוחי מסאבי אתדחיין לכר ושמשי מלכא עיילין לגו קדשא).</p>\n<p>לְמַלְכָּא, דַּהֲווֹ לֵיהּ אֲבָנִין יַקִירִין בְּחַד תֵּיבוּתָא, מִתְגַּלְּפָא בְּקוּסְטְרוֹי. וְהַהוּא מַלְכָּא הֲוָה חַכִּים. בְּגִין דְּלָא יִתְקָרֵב כָּל מַאן דְּבָעֵי, לְגַבֵּי הַהוּא תֵּיבוּתָא דַּאֲבָנִין יַקִירָן וּמַרְגְּלָן דְּתַמָּן, נָטַל בְּחָכְמָתֵיהּ, חַד חִוְיָא תַּקִּיפָא, וְכָּרִיךְ לֵיהּ סָחֲרָנֵיהּ דְּהַהוּא תֵּיבוּתָא, כָּל מַאן דְּבָעֵי לְאוֹשָטָא יְדֵיהּ לְגַבֵּי תֵּיבוּתָא, הָא חִוְיָא דָּלִיג עָלֵיהּ, וְקָטִיל לֵיהּ.</p>\n<p>חַד רְחִימָא הֲוָה לְמַלְכָּא, אָמַר לֵיהּ מַלְכָּא, כָּל זִמְנָא דְּאַתְּ בָּעֵי לְאָעֲלָא וּלְאִשְׁתַּמְּשָׁא בְּתֵיבוּתָא, תַּעֲבִיד כַּךְ וְכַךְ לְגַבֵּי הַהוּא חִוְיָא, וְתִפְתַּח תֵּיבוּתָא, וּתְשַׁמֵּשׁ בִּגְנִיזִין דִּילִי. כַּךְ קוּדְשָׁא בְּרִיךְ הוּא, כָּרִיךְ חִוְיָא סָחֲרָנִיהּ דְּקֻדְשָׁא, אָתָאן מַלְאָכִין עִלָּאִין לְאָעָלָא גּוֹ קֻדְשָׁא, הָא חִוְיָא תַּמָּן, וְדַחֲלֵי לְאִסְתָּאֲבָא בֵּיהּ. (ואי תימא זה אכולהו אשא, ואשא לא מקבלא מסאבא)</p>\n<p>תָּא חֲזֵי, כְּתִיב (תהילים ק״ד:ד׳) עוֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לוֹהֵט, עוֹשֶׂה מַלְאָכָיו רוּחוֹת, אִלֵּין מַלְאָכִין דְּקַיְימִין לְבַר. מְשָׁרְתָיו אֵשׁ להֵט, אִלֵּין מַלְאָכִין דְּקַיְימִין לְגוֹ, אִיהוּ רוּחָא מִסְאֲבוּ, וְאִינּוּן רוּחַ. רוּחַ בְּרוּחַ לָא עָיִיִל דָּא בְּדָא. רוּחַ מִסְאֲבוּ בְּרוּחַ קֻדְשָׁא לָא <Nonei></i>אִתְעָרְבֵי דָּא בְּדָא. וּבְּגִין כָּךְ אִינּוּן דְּאִקְרוּן רוּחַ, לָא יַכְלִין לְאַעֲלָא לְגוֹ, בְּגִין הַהוּא רוּחָא מִסְאֲבוּ. אִינּוּן דִּלְגוֹ, אִינּוּן אֵשׁ, וְהַהוּא אֵשׁ דָּחֵי לְהַהוּא מִסְאֲבוּ דְּלָא עָיֵיל לְגוֹ. וּבְּגִין כָּךְ כֹּלָּא דַּחְיָּין לֵיהּ לְבַר לְמִסְאֲבוּ, דְּלָא יִתְעָרַב בַּהֲדַיְיהוּ. וְעַל דָּא, מַלְאֲכֵי עִלָּאֵי קָא מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בָּתַר דְּדַחְיָין לֵיהּ לְמִסְאֲבוּ לְבַר.</p>\n<p>תְּלַת אַשְׁמוּרוֹת אִינּוּן בְּלֵילְיָא, לָקֳבְלֵיהוֹן תְּלַת מַשִּׁרְיָין, דְּקָא מִתְפַּלְּגֵי לְשַׁבְּחָא לְקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאִתְּמַר. וְעַל דָּא הַאי רִבּוֹן דְּכֻלְּהוּ, אִיהוּ נִר (נ\"א כינור) דְּדָוִד דְּלָא שָׁכִיךְ לְעָלְמִין, אֶלָּא תָּדִיר אוֹדֵי וּמְשַׁבַּח לֵיהּ לְמַלְכָּא עִלָּאָה, וְעַל דָּא (איוב ל״ה:י׳) נוֹתֵן זְמִירוֹת בַּלָּיְלָה.</p>\n<p>דָּבָר אַחֵר, וְלא אָמַר אַיֵּה אֱלוֹהַּ עוֹשָׂי, כְּמָה דְּאִתְּמַר, בְּגִין דְּהָא מֵעֵילָּא וּמִתַּתָּא אִתְכְּלִיל בַּר נָשׁ, וְאִתְעָבִיד, כְּמָה דְּאִיהוּ גּוּפָא מִתְּרֵין סִטְרִין, מִגּוֹ דְּכַר וְנוּקְבָּא, אוּף הָכִי רוּחָא. רוּחַ אִיהוּ כָּלִיל, מִגּוֹ דְּכַר וְנוּקְבָּא. וְעַל רָזָא דְּנָא אִתְתָּקַּן בַּר נָשׁ בִּגְלִיפוֹי, בְּגוּפָא וְרוּחָא. וּבְגִין דְּאִיהוּ כָּלִיל בְּרָזָא דָּא, וּבְעוֹבָדָא דָּא, כְּמָה דְּאִתְּמַר, עַל דָּא (ודאי) כְּתִיב, (בראשית א׳:כ״ו) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ וְהָא אִתְּמַר.</p>\n<p>בְּלֵילְיָא הָא אַמָרְתְּ, דְּהָא בְּרֵאשִׁיתָא דְּלֵילְיָא, כָּל אִינּוּן זִינִין וְרוּחִין בִּישִׁין מִתְעָרֵי בְּעָלְמָא, הֵיךְ אִיהוּ יָכִיל לְמֶהֱוֵי, דְּאִי הָכִי, הָא תָּנֵינָן, דְּמִסְטְרָא דְּצָפוֹן נַפְקֵי כָּל הָנֵי זִינִין בִּישִׁין, וְאִתְּאַמְרָת (ס\"א ואתמר) דְּכַד אִתְּעַר רוּחַ צָפוֹן בְּפַלְגוּת לֵילְיָא, דְּהָא כְּדֵין כָּל אִינּוּן רוּחִין בִּישִׁין, וְסִטְרִין בִּישִׁין, אִתְכְּנָשׁוּ מֵעָלְמָא, וְעָאלִין גּוֹ נוּקְבָּא דִּתְהוֹמָא רַבָּא, אִי הָכִי הָא בְּסִטְרָא דְּדָרוֹם דְּאִיהוּ יְמִינָא, אֲמַאי מְשַׁטְטֵי אִינּוּן זִינִין בִּישִׁין בְּרֵישׁ לֵילְיָא, דְּקָא שָׁלְטָא רוּחַ דָּרוֹם.</p>\n<p>אֶלָּא וַדַּאי, אִלְמָלֵא הַהוּא סִטְרָא דְּדָרוֹם, דְּקָא מְעַכֵּב וְדַחְיָיא לְהַהוּא סִטְרָא בִּישָׁא, הֲוָה מִטַשְׁטֵשׁ כּוּלֵי עָלְמָא, וְלָא יָכִיל עָלְמָא לְמִסְבַּל. אֲבָל כַּד אִתְּעַר הַהוּא סִטְרָא אַחֲרָא, לָא אִתְּעַר אֶלָּא בִּסְטַר רוּחַ מַעֲרָב, דְּקָא שַׁלְטָא בְּרֵישׁ לֵילְיָא, וְעָלְמָא אִיהוּ כֹּלָּא כָּנִישׁ. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא אַקְדִּים אַסְוָותָא לְעָלְמָא, בְּגַוְונָא דָּא כְּמָה דְּאִתְּמַר. זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ מִכָּל שְׁאַר עַמִּין דְּעָלְמָא.</p>\n<p>עָאלוּ לְבֵיתָא רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא. כַּד אִתְפְּלַג לֵילְיָא, קָמוּ לְמִלְעֵי בְּאוֹרַיְיתָא. אָמַר רַבִּי אַבָּא, הַשְׁתָּא וַדַּאי אִיהוּ עִידָּן רְעוּתָא לְקוּדְשָׁא בְּרִיךְ הוּא, וְהָא זִמְנִין סַגִּיאִין אִתְּעַרְנָא הַאי, דְּקוּדְשָׁא בְּרִיךְ הוּא בְּשַׁעֲתָא דְּאִתְפְּלַג לֵילְיָא, עָאל גּוֹ אִינּוּן צַדִּיקַיָּיא בְּגִּנְתָּא דְּעֵדֶן, וְאִשְׁתַּעֲשַׁע בְּהוּ. זַכָּאָה אִיהוּ מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, בְּהַהִיא זִמְנָא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הָא דְּאִשְׁתַּעֲשָׁע קוּדְשָׁא בְּרִיךְ הוּא גּוֹ צַדִּיקַיָּא בְּגִּנְתָּא דְּעֵדֶן, הֵיךְ אִשְׁתֲּעְשָׁע. אֶלָּא בְּהַהוּא זִמְנָא דְּאִתְפְּלַג לֵילְיָא, קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר בִּרְחִימוּ דִּשְׂמָאלָא, לְגַבֵּי כְּנֶסֶת יִשְׂרָאֵל, דְּהָא לֵית רְחִימוּ אֶלָּא מִסִּטְרָא דִּשְׂמָאלָא. וּכְנְסֶת יִשְׂרָאֵל לֵיהּ לָהּ דּוֹרוֹנָא לְמִקְרַב לְגַבֵּי מַלְכָּא, אוֹ חֲשִׁיבוּ מֵעַלְיָא, אֶלָּא בְּאִינּוּן רוּחִין דְּצַדִּיקַיָּא, דְּקוּדְשָׁא בְּרִיךְ הוּא חָמֵי לוֹן מִתְעַטְּרָן, בְּכַמָּה עוֹבָדִין טָבִין, וּבְכַמָּה זַכְיָין דְּעָבְדוּ בְּהַהוּא יוֹמָא, וְקוּדְשָׁא בְּרִיךְ הוּא נִיחָא לֵיהּ מִכָּל קָרְבָּנִין וְעִלָּוָון, דְּקוּדְשָׁא בְּרִיךְ הוּא אָרַח בְּהוּ רֵיחַ נִיחֹחַ, דְּקָא עַבְדֵי יִשְׂרָאֵל.</p>\n<p>כְּדֵין נְהִירוּ אִתְנְהִיר, וְכֹל אִילָנִין דְּגִּנְתָּא דְּעֵדֶן אָמְרוּ שִׁירָתָא, וְצַדִּיקַיָּא מִתְעַטְּרָן תַּמָּן בְּאִינּוּן עִדּוּנִין דְּעָלְמָא דְּאָתֵי. כַּד אִתְּעַר בַּר נָשׁ בְּהַהִיא שַׁעֲתָא לְמִלְעֵי בְּאוֹרַיְיתָא, נָטִיל חוּלָקֵיהּ עִמְּהוֹן דְּצַדִּיקַיָּא דִּי בְּגוֹ גִּנְתָּא, חַד שְׁמָא גְּלִיפָא דִּתְלָתִין וּתְרֵין אַתְוָון, (ס\"א אתער) אִתְעַטָּר בְּהוּ תַּמָּן, וְאִיהוּ גּוֹ רָזִין דְּצַדִּיקַיָּא.</p>"],[9520011786,"<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהילים קי״א:א׳) הַלְלוּיָהּ אוֹדֶה יְיָ' בְּכָל לֵבָב וְגוֹ', הַלְלוּיָהּ, הָא אִתְּמַר וְאִתְּעֲרוּ בֵּיהּ חַבְרַיָּיא, וְהָכִי אִיהוּ, דְּדָא אִיהוּ שְׁבָחָא דְּקָא סַלְּקָא עַל כָּל אִינּוּן שִׁירִין וְתוּשְׁבְּחָן דְּאָמַר דָּוִד, בְּעֶשֶׂר זִינִי תּוּשְׁבְּחָן דְּאִיהוּ אָמַר, בְּגִין דְּאִיהוּ כָּלִיל שְׁמָא (וישלח קע\"ב ע\"ב) וּשְׁבָחָא בְּחַד, וְאִיהוּ כְּלָלָא דִּשְׁמָא קַדִּישָׁא עִלָּאָה.</p>\n<p>אוֹדֶה יְיָ' בְּכָל לֵבָב, בְּכָל אֲתָר דְּאָמַר דָּוִד מַלְכָּא, רָזָא דְּאַלְפָא <Nonei></i>בֵּיתָא, אִיהוּ רָזָא דְּאַתְוָון גְּלִיפָן, דְּנָפְקִין בְּגִלּוּפֵי דִּתְלָתִין וּתְרֵין שְׁבִילִין. וְאִית אַתְוָון עִלָּאִין, מֵרָזָא דְּעָלְמָא עִלָּאָה. וְאִית אַתְוָון אַחֲרָנִין, דְּאִינּוּן אַתְוָון (הקדמה ג' ע\"א) זְעִירִין. וְהָכָא אִיהוּ רָזָא דְּאַלְפָא בֵּיתָא, דְּעָלְמָא (ס\"א עילאה יהיב לעלמא) תַּתָּאָה.</p>\n<p>אוֹדֶה יְיָ' בְּכָל לֵבָב: בְּיִּצְרָא טָבָא וּבְיִּצְרָא בִּישָׁא דְּאִיהוּ שָׁרֵי בְּגַוֵּיהּ. דְּהָא עַל כֹּלָּא אִית לְאוֹדָאָה לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּיִּצְרָא טָבָא וּבְיִּצְרָא בִּישָׁא. דְּהָא מִסִּטְרָא דְּיִצְרָא טָבָא אָתֵי טוֹב לְבַר נָשׁ, וְאִית לְבָרְכָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא הַטּוֹב וְהַמֵטִיב. וּבְסִטְרָא דְּיִצְרָא בִּישָׁא, אָתֵי קִטְרוּגָא לְבַר נָשׁ, וְאִית לְאוֹדָאָה לְקוּדְשָׁא בְּרִיךְ הוּא, (ביצרא טבא וביצרא בישא) בְּכָל מָה דְּאָתֵי עַל בַּר נָשׁ, מִסִּטְרָא דָּא וּמִסִּטְרָא דָּא.</p>\n<p>בְּסוֹד יְשָׁרִים וְעֵדָה, בְּסוֹד יְשָׁרִים: בְּאִינּוּן (ס\"א מלאכין עלאין קדישין) דְּרָזָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִינּוּן יַדְעֵי. דְּהָא כָּל רָזִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִינּוּן יַדְעֵי, וְאִינּוּן רָזָא דִּילֵיהּ, וְעַל דָּא בְּסוֹד יְשָׁרִים. וְעֵדָה: אִלֵּין אִינּוּן יִשְׂרָאֵל, כַּד מִתְכַּנְּשֵׁי בַּעֲשָׂרָה, לְאוֹדָאָה לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וּבְּגִין כָּךְ, אִית לְאוֹדָאָה לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, עַל טָב וְעַל בִּישׁ, וּלְפַרְסְמָא קָמֵי כֹּלָּא. דְּאִי תֵּימָא הָא אִיהוּ יָדַע, אֲמַאי אִצְטְרִיךְ לְפַרְסְמָא. אֶלָּא בְּדָא, אִתְיָיקָר קוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא לְפַרְסְמָא נִסָּא. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא כְּתִיב בֵּיהּ, (יחזקאל ל״ח:כ״ג) וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְגוֹ'.</p>"],[9520011787,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים ק״נ:ו׳) כֹּל הַנְּשָׁמָה תְּהַלֵּל יָהּ. תַּנָּא, כָּל נִשְׁמָתִין אָתוּ מֵהַאי גּוּפָא קַדִּישָׁא, וְאַתְעָרוּ בִּבְנֵי נָשָׁא. וּמֵאָן אֲתָר. מֵהַהוּא אֲתָר דְּאִקְרֵי יַד. (ס\"א י\"ה) מַאן אֲתָר דָּא אָמַר רַבִּי יְהוּדָה דִּכְתִּיב, (תהילים ק״ד:כ״ד) מָה רַבּוּ מַעֲשֶׂיךָ יְיָ' כֻּלָּם בְּחָכְמָה עָשִׂיתָ. תָּנָא, מֵהַאי חָכְמְתָא דְּמַבּוּעוֹי נָפְקִין לִתְלָתִין וּתְרֵין שְׁבִילִין, אִשְׁתָּכְלַל כֹּלָּא, וְכָל מָה דְּאִית לְעֵילָּא וְתַתָּא, וְהוּא אִתְקְרֵי רוּחָא קַדִּישָׁא, דְּכָל רוּחִין אִשְׁתָּכְלָלוּ בֵּיהּ.</p>\n<p>אָמַר רַבִּי יִצְחָק, בְּיוֹמָא דְּהֲוָה רַבִּי שִׁמְעוֹן פָּרִישׁ מִלָּה דָּא, עֵינוֹי נַבְעִין מַיָּא, וַהֲוָה אָמַר, כָּל גִּנְזַיָּיא דְּמַלְכָּא עִלָּאָה, אִתְמָסְרָן בְּחַד מַפְתְּחָא, וְאִתְגַּלְיָיא בְּקֻזְפִיטָן דְּקוּרְדִּיטֵי גְּלִיפִין עִלָּאִין.</p>\n<p>אֶלָּא הָכִי תָּאנָא, מַאן יָכִיל לְאִשְׁתְּמוֹדְעָא וּלְאִתְכַּלְלָא מַה דְּגָנִיז בְּדָא מַבּוּעָא. דְּהָא מֹשֶׁה לָא גַּלֵּי דָּא בְּיוֹמוֹי, כַּד הֲוָה גַּלֵּי רָזָא עֲמִיקְתָא לְיִשְׂרָאֵל, וְאַף עַל גַּב דְּכֹלָא הֲוָה מִתְגַּלְיָיא עַל יְדוֹי. אֶלָּא בְּהַהִיא שַׁעֲתָא דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְסַלְּקָא לֵיהּ לִמְתִיבְתָּא קַדִּישָׁא עִלָּאָה, וּלְטַמְרָא לֵיהּ מִבְּנֵי נָשָׁא, דִּכְתִּיב, (דברים ל״א:ב׳) בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם. הַיּוֹם מַמָּשׁ, דְּהַהוּא יוֹמָא אִשְׁתְּלִימוּ יוֹמוֹי, לְאִתְקָרְבָא לְאֲתָר דָּא, דִּכְתִּיב, (דברים ל״א:י״ד) הֵן קָרְבוּ יָמֶיךָ, קָרְבוּ מַמָּשׁ.</p>"],[9520011788,"<p>דְּתַנְיָא אָמַר רַבִּי שִׁמְעוֹן, מֹשֶׁה לָא מִית. וְאִי תֵּימָא הָא כְּתִיב (דברים לא) וַיָּמָת שָׁם מֹשֶׁה. כַּךְ בְּכָל אֲתָר לְצַדִּיקַיָּא קָרֵי בְּהוּ מִיתָה. מַאי מִיתָה. מִסִּטְרָא דִּילָן אִקְרֵי הָכִי. דְּתַנְיָא אָמַר רַבִּי שִׁמְעוֹן, וְכֵן תָּנָא, דְּמַאן דְּאִיהוּ בִּשְׁלִימוּתָא דִּמְהֵימְנוּתָא קַדִּישָׁא תַּלְיָיא בֵּיהּ, לָא תַּלְיָיא בֵּיהּ מִיתָה וְלָא מִית. כְּמָה דְּהֲוָה בְּיַעֲקֹב דִּמְהֵימְנוּתָא שְׁלֵימָתָא הֲוָה בֵּיהּ.</p>\n<p>דְּאָמַר רִבִּי שִׁמְעוֹן, (בראשית ל״ה:י׳) לֹא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ, וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל. מַאי יִשְׂרָאֵל. שְׁלֵימוּתָא דְּכֹלָּא. דִּכְתִּיב, (ירמיהו ל׳:י׳) וְאַתָּה אַל תִּירָא עַבְדִי יַעֲקֹב וְאַל תֵּחַת יִשְׂרָאֵל כִּי הִנְנִי מוֹשִׁיעֲךָ מֵרָחוֹק וְאֵת זַרְעֲךָ מֵאֶרֶץ שִׁבְיָם וְגוֹ'.</p>\n<p>אָמַר רִבִּי יְהוּדָה מֵהָכָא, (ירמיהו ל׳:י״א) כִּי אִתְּךָ אָנִי, דַּיְיקָא, זַכָּאָה חוּלְקֵיהּ, דְּמָארֵיהּ אָמַר לֵיהּ כֵּן. כִּי אִתִּי אַתָּה לָא כְּתִיב, אֶלָּא כִּי אִתְּךָ אָנִי, דְּמָארֵיהּ אָתֵי לְאִתְחַבְּרָא דִּיּוּרֵיהּ עִמֵּיהּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן שַׁפִּיר קָאָמַר רִבִּי אַבָּא דְּאָמַר (ירמיהו ל׳:י׳) וְשָׁב יַעֲקֹב וְשָׁקַט וְשַׁאֲנַן וְאֵין מַחֲרִיד. וְשָׁב יַעֲקֹב: לְאִתְקְרֵי בִּשְׁמָא אַחֲרָא, דִּכְתִּיב לא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל.</p>\n<p>דָּבָר אַחֵר וְשָׁב יַעֲקֹב, לְאֲתָר דְּאִתְנְסִיב מִתַּמָּן. וְשָׁקַט, בָּעוֹלָם הַזֶּה. וְשַׁאֲנַן, בָּעוֹלָם הַבָּא. וְאֵין מַחֲרִיד מִמַּלְאַךְ הַמָּוֶת. דְּמַשְׁמַע דְּכֹלָּא הֲוָה בֵּיהּ. רִבִּי יִצְחָק אָמַר, חַבְרַיָּיא הָא אוּקְמוּהָ, דִּכְתִּיב וְאֶת זַרְעֲךָ מֵאֶרֶץ שִׁבְיָם, מַה זַרְעוֹ בַּחַיִּים, אַף הוּא בַּחַיִּים.</p>"],[9520011789,"<p><Nonei></i>וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִיחַ מִן הַקָּצֶה אֶל הַקָּצֶה. רַבִּי יְהוּדָה פָּתַח (קהלת י׳:י״ז) (צ\"ה ע\"ב) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ. וּכְתִיב, אִי לָךָ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר וְשָׂרַיִךְ בַּבֹּקֶר יֹאכֵלוּ. (במאי אוקימנא הני קראי) וַוי לְעָלְמָא דְּלָא מַשְׁגְּחָן בְּפוּלְחָנָא דְּמָארֵיהוֹן, דְּהָא מָארֵיהוֹן אַשְׁגַּח בְּגִינֵיהוֹן לְאוֹטָבָא לְהוּ, דְּאָנַח קָמַיְיהוּ פִּתְגָּמֵי אוֹרַיְיתָא, וְלָא מַשְׁגְּחָן.</p>\n<p>דְּתָנֵינָן, תְּלַת מִלִּין בָּעֵי בַּר נָשׁ לְמֶעְבַּד לִבְרֵיהּ, מִילָה, וּפִדְיוֹן, וּלְנַסְבָא לֵיהּ אִנְתּוּ. וְכֹלָּא עָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל. מִילָה: דִּכְתִּיב, (יהושע ה׳:ב׳) וְשׁוּב מוֹל אֶת בְּנִי יִשְׂרָאֵל שֵׁנִית. וּכְתִיב (בראשית י״ז:י״ב) וּבֶן שְׁמֹנַת יָמִים יִמּוֹל לָכֶם כָּל זָכָר. פִּדְיוֹן. דִּכְתִּיב, (דברים טו) וַיִּפְדְּךָ (יי אלהיך) (ס\"א (דברים ז׳:ח׳) מבית עבדים) מִיַּד פַּרְעֹה מֶלֶךְ מִצְרָיִם. לְנַסְּבָא לֵיהּ אִנְתּוּ: דִּכְתִּיב, (בראשית א׳:כ״ח) זָכָר וּנְקֵבָה בָּרָא אוֹתָם, וּכְתִיב וַיְבָרֶךְ אוֹתָם אֱלֹהִים וַיֹּאמֶר לָהֶם אֱלֹהִים פְּרוּ וּרְבוּ. תּוּ, אַטִּיל לְהוּ כְּהַאי נִשְׁרָא, דְּאָטִיל לִבְנוֹי עַל גַּדְפּוֹי, דִּכְתִּיב, (שמות י״ט:ד׳) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים.</p>\n<p>אָמַר רַבִּי יוֹסִי, כֹּלָּא הוּא יֵאוֹת, אֲבָל אוֹרַיְיתָא דְּאַהֲדָר קָמַיְיהוּ דְּיִשְׂרָאֵל, וְאוֹלִיף לוֹן, יַתִּיר מִכֹּלָּא. תָּא חֲזִי, לֵית שְׁבָחָא דְּבַר נָשׁ בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי, כִּשְׁבָחָא דְּאוֹרַיְיתָא דִּכְתִּיב בָּהּ (משלי ה) בִּי מְלָכִים יִמְלכוּ.</p>\n<p>(מדרש הנעלם הוא) דְּהָא תָּנֵינָן כַּד סָלִיק רַב הוּנָא לְהָתָם, אַשְׁכַּח רַבָּנָן דַּהֲווֹ עַסְקֵי בְּהַאי קְרָא, דִּכְתִּיב, (ירמיהו נ״א:מ״ד) וּפָקַדְתִּי עַל בֵּל בְּבָבֶל וְהוֹצֵאתִי אֶת בִּלְעוֹ מִפִּיו וְלֹא יִנְהֲרוּ אֵלָיו עוֹד גּוֹיִם. וְרַב הוּנָא לָא הֲווֹ מַשְׁגִּיחִין בֵּיהּ, דְּהָא לָא אִשְׁתְּמוֹדְעָן לֵיהּ בְּקַדְמִיתָא, בְּגִין דְּהֲוָה זְעֵיר. עָאל לְבֵי מִדְרָשָׁא, וְאַשְׁכַּח רַבָּנָן דַּהֲווֹ אַמְרֵי, הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, אִי טַעֲוָתֵיהּ וְדָחַלְתֵּיהּ דִּנְבוּכַדְנֶצַר הֲוָה שְׁמֵיהּ בֵּל, הָא כְּתִיב בֵּיהּ, (דניאל ד׳:ה׳) וְעַד אָחֳרִין עַל קֳדָמַי דָּנִיאֵל דִּי שְׁמֵהּ בֵּלְטְשַׁאצַּר כְּשֻׁם אֱלָהִי. וְעוֹד, מַאי וְהוֹצֵאתִי אֶת בִּלְעוֹ מִפִּיו.</p>"],[9520011790,"<p>קָם רַב הוּנָא בֵּינֵי קַיָימֵי דְּעַמוּדֵי, וְאָמַר אִילּוּ הֲוֵינָא בְּאַתְרִי, דָּרִישְׁנָא לֵיהּ לְהַאי פְּסוּקָא. לָא אַשְׁגָּחוּ בֵּיהּ. קָם תִּנְיָינוּת, וְאָמַר מִלָּה דָּא. אָתָא רַבִּי יוֹדָאי בַּר רַב, וְאוֹתְבֵיהּ קַמֵּיהּ. אָמַר לֵיהּ, אֵימָא בְּרִי אֵימָא, דְּמִלֵּי אוֹרַיְיתָא כְּתִיב בְּהוּ, (משלי א׳:כ״א) בְּרֹאשׁ הוֹמִיּוֹת תִּקְרָא וְגוֹ'.</p>\n<p>פָּתַח וְאָמַר, הָכִי תָּנֵינָן, בְּיוֹמֵי קַדְמָאֵי עַד לָא אָתָא יַעֲקֹב, הֲוָה בַּר נָשׁ שָׁלֵו בְּבֵיתֵיהּ, מָטָא זִמְנֵיהּ, מִית בְּלָא מַרְעִין, כֵּיוָן דְּאָתָא יַעֲקֹב, בָּעָא קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, אָמַר לֵיהּ, מָרֵי דְּעָלְמָא, אִי נִיחָא קָמָךְ, דְּלִנְפּוֹל בַּר נָשׁ בְּבֵי מַרְעֵיהּ, תְּרֵין אוֹ תְּלַת יוֹמִין, וּלְבָתַר יִתְכְּנָשׁ לְעַמֵּיהּ, וְיַפְקֵד לְבֵיתֵיהּ, וְיֵתוּב מֵחוֹבוֹי. אָמַר לֵיהּ שַׁפִּיר. אַתְּ הוּא סִימָנָא בְּעָלְמָא. תָּא חֲזֵי, מָה כְּתִיב בֵּיהּ (בראשית מ״ח:א׳) וַיְהִי אַחֲרֵי הַדְּבָרִים הָאֵלֶּה וַיֹּאמֶר לְיוֹסֵף הִנֵּה אָבִיךָ חוֹלֶה. חֹלֶה כְּתִיב מַה דְּלָא הֲוָה לְבַר נָשׁ מִן קַדְמַת דְּנָא.</p>"],[9520011791,"<p>בָּתַר דְּשָׁכִיב, לָא הֲוָה בַּר נָשׁ דְּהֲוָה לֵיהּ מַרְעִין, דְּלָא מִית. עַד דְּאָתָא חִזְקִיָּה, מָה כְּתִיב בֵּיהּ, (ישעיהו ל״ח:א׳) בַּיָּמִים הָהֵם חָלָה חִזְקִיָּהוּ לָמוּת וְגוֹ'. תָּא חֲזִי, מָה כְּתִיב וַיַסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל יְיָ', אָמַר לֵיהּ, אִי נִיחָא קָמָךְ דְּיִתְּסוּן בְּנֵי נָשָׁא מִבֵּי מַרְעֵיהוֹן, וְיוֹדוּן שְׁמָךְ, וְיִשְׁתְּמוֹדְעוּן, וִיתוּבוּן לְבָתַר בְּתִיּוּבְתָא שְׁלֵימָתָא, וְיִשְׁתַּכְּחוּן בְּנֵי עָלְמָא זַכָּאִין קֳדָמָךְ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, יֵאוֹת הוּא, אַתּ תְּהֵא סִימָנָא בְּעָלְמָא, וְכַךְ הוּא, מַאי דְּלָא הֲוָה מִקַּדְמַת דְּנָא. הֲדָא הוּא דִּכְתִּיב, (ישעיהו ל״ח:ט׳) מִכְתָּב לְחִזְקִיָּהוּ מֶלֶךְ יְהוּדָה בַּחֲלוֹתוֹ וַיְחִי מֵחָלְיוֹ. וְתָאנָא, הַהוּא יוֹמָא אִתְחָזַר שִׁמְשָׁא עֶשֶׂר דַּרְגִּין.</p>\n<p>וְתָאנָא, מְרוֹדָךְ בַּלְאֲדָן הֲוָה אָכִיל כָּל יוֹמָא בְּד' שַׁעְתֵּי, וְנָאִים עַד תֵּשַׁע שַׁעְתֵּי, וְהַהוּא יוֹמָא נָאִים עַד ט' שַׁעְתֵּי, כַּד אִתְּעַר חָמָא שִׁמְשָׁא דְּקָאִים בְּד' שַׁעְתֵּי, אָמַר מַאי הַאי, בְּקִטּוּלָא דְּקוּנְטִירָא קוֹנְטְרוֹי אַנְקָטַּרְתּוּן. אָמְרוּ <Nonei></i>לֵיהּ לָמָּה. אָמַר, דְּנָאִימְנָא יוֹמָא חַד, וּתְלָתוּת יוֹמָא. אָמְרוּ לֵיהּ, לָאו הָכִי, אֶלָּא אֱלָהָא דְּחִזְקִיָה עֲבַד יוֹמָא דֵּין תְּרֵין נִיסִּין. אָסֵי לְחִזְקִיָה מִבֵּי מַרְעֵיהּ, וְאַחְזָר שִׁמְשָׁא לְעִדָּנָא דָּא. אָמַר וְכִי אִית בְּעָלְמָא אֱלָהָא רַבָּא בַּר מֵאֱלָהַי. אָמְרוּ, אֱלָהָא דְּחִזְּקִיָהוּ.</p>\n<p>קָם וְכָתַב כְּתָבוֹי, שְׁלָם לְחִזְקִיָּהוּ מַלְכָּא דִּיהוּדָה וּשְׁלָם לְאֱלָהֵיהּ וּשְׁלָם לִיְרוּשָׁלַ ם קַרְתָּא קַדִּישָׁא. לְבָתַר אַמְלִיךְ וְקָם מִכֻּרְסְיָה, וּפָסַע תְּלַת פְּסִיעָן, וְכָתַב אַחֲרָנִין, שְׁלָם לֶאֱלָהָא רַבָּא דְּבִיְרוּשָׁלַ ם וּשְׁלָם לְחִזְקִיָּהוּ מַלְכָּא דִּיהוּדָה וּשְׁלָם לִיְרוּשָׁלַ ם קַרְתָּא קַדִּישָׁא. אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אַנְתְּ פָּסַעְתְּ בְּגִין יְקָרִי תְּלַת פְּסִיעָן, חַיֶּיךָ, מִינָךְ יִפְקוּן תְּלַת מַלְכִּין שַׁלִּיטִין, קַסְטִירִין רוּפִינִין דְּשָׁלִיטִין בְּכָל עָלְמָא, וְקַדְמָאָה מִנַּיְיהוּ נְבוּכַדְנֶצַר הֲוָה.</p>\n<p>תָּא חֲזֵי, מַאי אֲמַר לֵיהּ דָּנִיאֵל, (דניאל ב׳:ל״ח-ל״ט) אַנְּתּ הוּא רֵאשָׁה דִּי דַּהֲבָא. וּבַתְרָךְ תְּקוּם מַלְכוּ אָחֳרִי אֲרַע מִינָךְ וּמַלְכוּ תְּלִיתָאָה אָחֳרִי וְגוֹ'. מַה כְּתִיב (דניאל ג׳:א׳) נְבוּכַדְנְצַר מַלְכָּא עֲבַד צְלֵם דִּי דְהַב רוּמֵיהּ אַמִּין שִׁתִּין פְּתָיֵהּ אַמִּין שִׁית. אֲמַר נְבוּכַדְנֶצַר צֻלְמָא דַּחֲמֵינָא, הֲוָה רֵישָׁא דִּי דַּהֲבָא, מֵעוֹי דְּכֶסֶף, אֲנָא אַעֲבִיד כֹּלָּא דְּדַהֲבָא, דְּלִהוֵי קַּזְפִּירָא דְּדַהֲבָא בְּרֵישָׁא.</p>\n<p>וְתָאנָא, הַהוּא יוֹמָא כָּנַשׁ כָּל אוּמַיָּא וַעֲמַמְיָא וְלִישָׁנַיָיא לְמִפְלַח לְהַהוּא צַלְמָא, וְנָטַל מָאנָא מִמָּאנִי מַקְדְּשָׁא, דְּהֲוָה גָּלִיף בֵּיהּ שְׁמָא קַדִּישָׁא, וְעָיִיל לֵיהּ בְּפוּמֵיהּ דְּהַהוּא צַלְמָא, וּבְהַהִיא שַׁעֲתָא הֲוָה מְמַלֵּל רַבְרְבָן, עַד דְּאָתָא דָּנִיאֵל, וְקָרִיב גַּבֵּי דְּהַהוּא צַלְמָא, וְאָמַר אֲנָא שְׁלִיחָא דְּמָארָא עִלָּאָה, גּוֹזְרָנִי עָלָךְ לְמֵפַק מֵהָכָא. אִדְכַּר שְׁמָא קַדִּישָׁא, וְנָפַק הַהוּא מָאנָא, וְנָפַל צַלְמָא וְאִתְבַּר. הַיְינוּ דִּכְתִּיב וְהוֹצֵאתִי אֶת בִּלְעוֹ מִפִּיו וְלֹא יִנְהֲרוּ אֵלָיו עוֹד גּוֹיִם. קָם רִבִּי יְהוּדָה וּנַשְׁקֵיהּ עַל רֵישֵׁיהּ, אָמַר אִי לָא דְּקָרִיבְנָא בְּקּוּטְפַיָיא הָכָא, לָא אִשְׁתְּמוֹדַעְנָא בָּךְ. וַהֲווּ דַּחֲלִין קַמֵּיהּ מֵהַהוּא יוֹמָא.</p>"],[9520011792,"<p>תָּאנָא (קהלתי) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ. רִבִּי יוֹסִי אוֹקִים לְהַאי קְרָא, בְּמֹשֶׁה, בְּשַׁעֲתָא דְּאַפִּיק לְהוּ לְיִשְׂרָאֵל מִמִּצְרָיִם, וַעֲבַד לוֹן בְּנִי חוֹרִין. וְשָׂרַיִךְ בָּעֵת יאכֵלוּ, דִּכְתִּיב, (שמות י״ב:י״א) וְאֲכַלְתֶּם אוֹתוֹ בְּחִפָּזוֹן פֶּסַח הוּא לַיְיָ'.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן בַּר יוֹחָאי, וְכִי לָא אֲמֵינָא דְּמִלוֹי דִּשְׁלֹמֹה מַלְכָּא, דְּכֻלְּהוּ בְּגוֹ, לְגוֹ הֵיכְלָא קַדִּישָׁא הֲווֹ. וְהַאי דְּאַמְרִיתּוּ כֹּלָּא שַׁפִּיר הֲוָה, וְלִדְרָשָׁא הוּא דְּאָתָא, אֲבָל הַאי קְרָא, לְעֵילָּא בְּהֵיכָלָא קַדִּישָׁא הוּא.</p>\n<p>תָּאנָא, אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים. מַאי אֶרֶץ. אֶרֶץ סְתָם. דְּתַנְיָא, מַהוּ דִּכְתִּיב, (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל. אֶלָּא הַאי אֶרֶץ, הִיא רָזָא, בְּגוֹ כִּתְרֵי מַלְכָּא קַדִּישָׁא, דִּכְתִּיב בֵּיהּ (בראשית ב׳:ד׳) בְּיוֹם עֲשׂוֹת יְיָ' אֱלהִים אֶרֶץ וְשָׁמָיִם. וְהַאי אֶרֶץ, וְכָל מַה דְּיָנִיק וְאִתְּזָן, מֵהַהוּא אֲתָר דְּאִקְרֵי שָׁמַיִם הוּא, וְלָא אִתְּזָנַת אַרְעָא דָּא, אֶלָּא מִשְּׁלֵימוּתָא קַדִּישָׁא, דְּאִקְרֵי שָׁמַיִם.</p>\n<p>וּבְשַׁעֲתָא דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַחֲרָבָא בֵּיתֵיהּ דִּלְתַתָּא, וְאַרְעָא קַדִּישָׁא דִּלְתַתָּא, אַעְבַּר לְהַאי אַרְעָא קַדִּישָׁא דִּלְעֵילָּא בְּקַדְמִיתָא, וְנָחִית לֵיהּ מֵהַהוּא דַּרְגָּא דְּהֲוָה יַנְקָא מִשָּׁמַיִם קַדִּישָׁא, וּלְבָתַר חָרִיב לְהַאי דִּלְתַתָּא, הֲדָא הוּא דִכְתִיב הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ בְּקַדְמִיתָא, וּלְבָתַר וְלָא זָכָר הֲדוֹם רַגְלָיו. דְּתַנְיָא, כַּךְ אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, כַּד בָּעֵי לְמֵידַן עָלְמָא, בְּקַדְמִיתָא עָבִיד דִּינָא לְעֵילָּא, וּלְבָתַר אִתְקָיָּים לְתַתָּא, דִּכְתִּיב, (ישעיהו כ״ד:כ״א) יִפְקוֹד יְיָ' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם, בְּקַדְמִיתָא, וּלְבָתַר וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִין, דְּזָן לָךְ בִּסְגִיאוּת כֹּלָּא, בְּלָא דְּחִילוּ דְּאַחֲרָא, וּמֵהַהוּא מַלְכָּא עִלָּאָה אִתְּזַן כֹּלָּא. וְשָׂרַיִךְ בָּעֵת יאכֵלוּ, כְּמָה דְאַתְּ אָמֵר (במדבר כ״ג:כ״ג) כָּעֵת יֵאָמֵר לְיַעֲקֹב וּלְיִשְׂרָאֵל מָה פָּעַל אֵל, אִי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר כְּמָה דְאַתְּ אָמֵר (ישעיהו ג׳:ד׳) וְנָתַתִּי נְעָרִים שָׂרֵיהֶם. דְּוַוי לְאַרְעָא כַּד יַנְקָא מִשְּׂמָאלָא. וְשָׂרַיִךְ בַּבֹּקֶר יֹאכֵלוּ, <Nonei></i>בְּהַהוּא קַדְרוּתָא, וְעַד לָא נָהִיר, וְלָא שַׁלְטָא מָה דְּשַׁלְטָא.</p>\n<p>תָּנָא אָמַר רַבִּי שִׁמְעוֹן, (שמות כ״ו:כ״ח) וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִיחַ מִן הַקָּצֶה אֶל הַקָּצֶה, דָּא הוּא יַעֲקֹב קַדִּישָׁא שְׁלֵימָא, כְּמָה דְּאוּקִימְנָא, דִּכְתִּיב, (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם יוֹשֵׁב אֹהָלִים. יוֹשֵׁב אֹהֶל לָא כְּתִיב, אֶלָּא יוֹשֵׁב אוֹהָלִים, תְּרֵי, דְּאָחִיד לְהַאי וְאָחִיד לְהַאי. אַף הָכָא כְּתִיב, וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים, מַבְרִיחַ מִן הַקָּצֶה אֶל הַקָּצֶה, דְּאָחִיד לְהַאי וְאָחִיד לְהַאי.</p>\n<p>דְּתָנֵינָן, מַאי אִישׁ תָּם. כְּתַרְגּוּמוֹ, שְׁלִים. שְׁלִים מִכֹּלָּא, שְׁלִים לִתְרֵין סִטְרִין, לְעַתִּיקָא קַדִּישָׁא, וְלִזְעֵיר אַפִּין. שְׁלִים לְחֶסֶד עִלָּאָה וְלִגְּבוּרָה עִלָּאָה, וְאַשְׁלִים לְהַאי וּלְהַאי.</p>"],[9520011793,"<p>אָמַר רִבִּי שִׁמְעוֹן, חֲמֵינָא דְּהָא חָכְמְתָא כְּלַל כֹּלָּא. וְחֶסֶד עִלָּאָה נָפְקָא מֵחָכְמָה. גְּבוּרָה, דְּהוּא דִּינָא תַּקִּיפָא, נָפְקָא מִבִּינָה. יַעֲקֹב אַשְׁלִים לִתְרֵין סִטְרִין וַאֲבָהָן כְּלַל כֹּלָּא, וְיַעֲקֹב כְּלַל אֲבָהֲתָא.</p>\n<p>תָּאנָא בָּטַשׁ חָכְמָה בִּשְׁבִילוֹי, וְכָנִיף בְּרוּחָא (ס\"א למיא') וְאִתְכָּנְפוּ מַיָּא לְאֲתָר חַד, וְאִתְפְּתָחוּ חַמְשִׁין תַּרְעִין דְּבִינָה. מֵאִלֵּין שְׁבִילִין, נַפְקֵי עֲשָׂרָה כִּתְרִין, בְּקַרְנִיטֵּי זְהִירִין, וְאִשְׁתָּאָרוּ עֶשְׂרִין וּתְרֵין שְׁבִילִין. בָּטַשׁ הַהוּא רוּחָא בְּאִינּוּן שְׁבִילִין, וְאִתְפְּתָחוּ חַמְשִׁין תַּרְעִין דְּבִינָה, וְאִתְגְּלִיפוּ עֶשְׂרִין וּתְרֵין, בְּחַמְשִׁין תַּרְעִין דְּיוֹבְלָא, וְאִתְעַטָּרוּ בְּשִׁבְעִין וּתְרֵין אַתְוָון דִּשְׁמָא קַדִּישָׁא. אִלֵּין אִתְפְּתָּחוּ לְסִטְרוֹי.</p>\n<p>וְאִתְעַטָּרוּ עֶשְׂרִין וּתְרֵין כִּתְרִין דְּרַחֲמֵי, דִּכְלִילָן בְּעַתִּיק יוֹמִין, דְּנָהִיר לוֹן כָּל חַד בְּסִטְרוֹי. אִתְעַטָּרוּ חַמְשִׁין גְּלִיפִין, בְּמ\"ב אַתְוָון קַדִּישִׁין דִּשְׁמָא קַדִּישָׁא, דִּבְהוֹן אִתְבְּרֵי שְׁמַיָא וְאַרְעָא. וְאִתְגְּלָפוּ בְּגִּלוּפֵיהוֹן, תְּמַּנְיָא תַּרְעִין, דְּאִינּוּן תְּמַנְיָא אַתְוָון דְּרַחֲמֵי, דִּכְתִּיב, (שמות לה) יְיָ' יְיָ' אֵל רַחוּם וְחַנּוּן, דְּנָפְקָא מֵעַתִּיקָא קַדִּישָׁא, לִזְעִירָא, וּמִתְחַבְּרָן בְּאִלֵּין כִּתְרִין קַדִּישִׁין, חָכְמָה וּבִינָה עִלָּאִין דְּסַלְּקִין. נָפְקָא חֶסֶד עִלָּאָה מֵהַאי סִטְרָא, וְדִינָא דִּגְבוּרָה מֵהַאי סִטְרָא, אָתָא זְכוּתָא דְּיַעֲקֹב, וְאַשְׁלִים אֲתַרְוַויְיהוּ וְאָחִיד לוֹן. דְּהָא הוּא שְׁלֵימוּתָא עִלָּאָה.</p>\n<p>תָּאנָא אָמַר רִבִּי שִׁמְעוֹן, בְּגִין כָּךְ יִשְׂרָאֵל אִתְקְרֵי. דְּתָאנָא יַעֲקֹב תַּתָּאָה. יִשְׂרָאֵל עִלָּאָה. יַעֲקֹב לָאו שְׁלֵימוּתָא, יִשְׂרָאֵל שְׁלֵימוּתָא דְּכֹלָּא. וְכֵן תָּאנָא, (שמואל ב כ״ג:א׳) נְאֻם דָּוִד בֶּן יִשַׁי, דָּוִד לָאו שְׁלֵימוּתָא, דְּהָא בַּתְרָאָה הוּא. יִשַׁי יְסוֹד עִלָּאָה הוּא, וּשְׁלֵימוּתָא. וְהַיְינוּ דְּתָנֵינָן, לָא גָּלוּ יִשְׂרָאֵל מֵאַרְצָם עַד שֶׁכָּפְרוּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְמַלְכוּתָא דְּבֵית דָּוִד, דִּכְתִּיב, (שמואל ב כ׳:א׳) אֵין לָנוּ חֵלֶק בְּדָוִד וְלא נַחֲלָה בְּבֶן יִשַׁי אִישׁ לְאֹהָלָיו יִשְׂרָאֵל. מַאי אִישׁ לְאֹהָלָיו. אֲתָר דְּעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת שַׁרְיָא בְּגַּוַּיְיהוּ, הַיְינוּ לֶאֱלֹהָיו.</p>\n<p>אָמַר רִבִּי יְהוּדָה, כַּד שַׁרְיָא חָכְמְתָא לְגַּלְפָא גְּלִיפִין בְּכֻלְּהוּ כִּתְרִין, מֵאָן כִּתְרָא שַׁאֲרֵי מֵהַהוּא דְּאִתְקְרֵי בִּינָה. בְּבִּינָה אִתְכְּלִיל כֹּלָּא. וּבְּגִין כָּךְ אִתְפְּתָּחוּ בָּהּ חַמְשִׁין תַּרְעִין, וְאִשְׁתְּכַח דְּכֹלָּא בְּחָכְמָה אִתְגְּלָפוּ, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ.</p>"],[9520011794,"<p>תָּאנָא, כְּתִיב (ישעיהו מ׳:י״ב) מִי מָדַד בְּשָׁעֳלוֹ מַיִם וְגוֹ'. בְּשָׁעֳלוֹ מַיִם. מַאן מַיִם. דָּא הוּא בִּינָה. רִבִּי אֶלְעָזָר מַתְנִי הָכִי, דָּא חֶסֶד. אֲמַר לֵיהּ רַבִּי שִׁמְעוֹן, כֹּלָּא בְּחַד מַתְקְלָא סַלְּקָא. (ס\"א מתתקן) (ישעיהו מ׳:י״ב) וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן, מַאן שָׁמַיִם. תִּפְאֶרֶת. דִּכְתִּיב תִּפְאֶרֶת יִשְׂרָאֵל. וְכָל בַּשָּׁלִישׁ עֲפַר הָאָרֶץ. דָּא הוּא גְּבוּרָה. וְשָׁקַל בַּפֶּלֶס הָרִים, אִלֵּין אִינּוּן שְׁאַר כִּתְרִין, דְּאִקְרוּן טוּרֵי אֲפַרְסְמוֹנָא דַּכְיָא. וּגְּבָעוֹת בְּמֹאזְנָיִם, אִלֵּין שְׁאַר רְתִיכִין תַּתָּאִין מִנַּיְיהוּ.</p>\n<p>תָּא חֲזִי, בְּשָׁעֳלוֹ, מָאי שָׁעֳלוֹ. דָּא רוּחַ חָכְמְתָא דְּהָכִי תָּנֵינָן, שָׁעֳלָא דְּקִיטְרֵי בְּקִיזְפָא שְׁקִיעָן.</p>\n<p>וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן, מַאן זֶרֶת. אִלֵּין אִינּוּן (חמשין) תַּרְעִין דְּאִתְפָּתָחוּ וְאִתְפָּזְרוּ לְכָל סִטְרִין, כְּמָה דְאַתְּ אָמֵר (מלאכי ב׳:ג׳) וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם וְגוֹ'. וְכָל בַּשָּׁלִישׁ, מַאן שָׁלִישׁ. רַחֲמֵי. שְׁלֵימוּתָא דְּכֹלָּא. וְשָׁקַל בַּפֶּלֶס, מַאי פֶּלֶס, אָמַר רִבִּי שִׁמְעוֹן, דִּכְתִּיב, (ויקרא י״ט:ל״ו) מֹאזְנֵי צֶדֶק. אַבְנֵי צֶדֶק. תּוּ אָמַר רַבִּי שִׁמְעוֹן, הָנֵי מִילֵּי בְּשִׁיעוּרָא <Nonei></i>דְּיוֹצֵר כֹּלָּא אוֹקִימְנָא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, שְׁמַע מִינָּהּ, דְּיַעֲקֹב מִגּוֹ דִּינָא קַשְׁיָא נָפִיק, דְּהָא יִצְחָק דִּינָא קַשְׁיָא, אָחִיד לְחוּלָקֵיהּ. אָמַר לֵיהּ רִבִּי שִׁמְעוֹן, וְדָא הוּא בִּלְחוֹדוֹי, וְהָא יִצְחָק מִגּוֹ חֶסֶד נְפַק, וְהָכִי כֻּלְּהוּ, דִּינָא מִגּוֹ רַחֲמֵי נָפְקָא, וְרַחֲמֵי מִדִּינָא. אַבְרָהָם יָרִית אַחֲסָנָא דְּחֶסֶד, נָפַק יִצְחָק בְּדִינָא מִגּוֹ חֶסֶד. יַעֲקֹב נְפַק בְּרַחֲמֵי, מִגּוֹ דִּינָא קַשְׁיָא, וְכַךְ הוּא לְעֵילָּא, דָּא מִן דָּא, וְיַנְקָא דָּא מִן דָּא, עַד דְּאִשְׁתְּמוֹדַע כֹּלָּא דְּהוּא חַד, וּמֵחָד תַּלְיָין כֻּלְּהוּ, וְכֹלָּא אִשְׁתְּכַח חַד. בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אִשְׁתְּמוֹדַע, דְּלֵית שְׁלֵימוּתָא אֶלָּא כַּד אָחִיד דָּא מִן דָּא, (ס\"א וחד) וְדָא אָחִיד בְּתַרְוַויְיהוּ, לְשַׁכְלְלָא כֹּלָּא, כְּגוֹן יַעֲקֹב, וְהַיְינוּ דִּכְתִּיב מַבְרִיחַ מִן הַקָּצֶה אֶל הַקָּצֶה.</p>\n<p>תָּאנָא, כּוּלֵי הַאי לָא אִתְקְרֵי אֶלָּא מִסִּטְרָא דִּילָן, וּמִסִּטְרָא דִּילָן אִשְׁתְּמוֹדַע כֹּלָּא. (ס\"א דהא בהאי לעילא) וּלְעֵילָּא כֹּלָּא בְּחַד מַתְקְלָא סַלְּקָא. לָא שָׁנִי, וְלָא יִשְׁתָּנִי, כְּמָה דִּכְתִּיב, (מלאכי ג׳:ו׳) אֲנִי יְיָ' לָא שָׁנִיתִי. אָמַר רַבִּי יְהוּדָה, כֻּלְּהוֹן בּוּצִינִין נְהִירִין מֵחַד, וּמֵחָד תַּלְיָין, וּבוּצִינִין אִינְהוּ חַד כֹּלָּא. דְּהָא לָא בָּעוּ לְאִתְפָּרְשָׁא, וּמַאן דְּפָרִישׁ לוֹן, כְּאִלּוּ אִתְפְּרַשׁ מִן חַיֵּי עָלְמָא.</p>"],[9520011795,"<p>אָמַר רִבִּי יִצְחָק, כְּתִיב (ישעיהו ג׳:ד׳) וְנָתַתִּי נְעָרִים שָׂרֵיהֶם וְתַעֲלוּלִים יִמְשְׁלוּ בָם, הַיְינוּ דִּכְתִּיב, (שמות כ״ה:י״ח) וְעָשִׂיתָ שְׁנַיִם כְּרוּבִים זָהָב. כְּתִיב (שמואל א ד׳:ד׳) יוֹשֵׁב הַכְּרוּבִים, וּכְתִיב (שמואל ב כ״ב:י״א) וַיִּרְכַּב עַל כְּרוּב וַיָּעֹף. יוֹשֵׁב הַכְּרוּבִים, כַּד שַׁרְיָא לְאִתְיַישְּׁבָא בִּשְׁלִימוּתָא, כְּתִיב יוֹשֵׁב הַכְּרוּבִים. (ס\"א כד אשתכח בשלימותא) וְכַד לָא שַׁרְיָא, וְלָא אִתְיַישְׁבָא מַלְכָּא בְּכֻרְסְיָא, כְּתִיב וַיִּרְכַּב עַל כְּרוּב חַד, דְּלָא אִתְיַישְׁבָא מַלְכָּא בְּכֻרְסְיָּיה. יוֹשֵׁב הַכְּרוּבִים תְּרֵי.</p>\n<p>אָמַר רַבִּי יוֹסִי, וַוי לְעָלְמָא, כַּד חַד כְּרוּב אַהְדָּר אַנְפֵּיה מֵחַבְרֵיהּ, דְּהָא כְּתִיב וּפְנֵיהֶם אִישׁ אֶל אֶחָיו, כַּד הֲוָה שְׁלָמָא בְּעָלְמָא. אָמַר רַבִּי יִצְחָק, הָא תָּנֵינָן (ויקרא י״ח:ז׳) עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לא תְגַלֵּה, וַוי לְמַאן דְּגַלֵּי עֲרָיַיתְהוֹן. כְּגַוְונָא דָּא כְּתִיב בְּיַעֲקֹב, מַבְרִיחַ מִן הַקָּצֶה אֶל הַקָּצֶה. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתְּבַּח בְּתֻשְׁבַּחָתַיְיהוּ כְּגַוְונָא דִּלְעֵילָּא, דִּכְתִּיב (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.</p>\n<p>תָּאנָא אָמַר רַבִּי יִצְחָק, בְּיוֹמֵי קַדְמָאֵי, הֲוָה בַּר נָשׁ אָמַר לְחַבְרֵיהּ, אֵימָא לִי מִלָּה חֲדָא דְּאוֹרַיְיתָא, וְטוֹל מָנֶה כְּסַף. הַשְׁתָּא אָמַר בַּר נָשׁ לְחַבְרֵיהּ, טוֹל מָנֶה כְּסַף וְאִשְׁתְּדַּל בְּאוֹרַיְיתָא, וְלֵית מַאן דְּיִשְׁגַּח, וְלֵית מַאן דְּיַרְכִּין אוּדְנֵיהּ, בַּר אִינּוּן זְעִירִין (נ\"א זרעין) קַדִּישֵׁי עֶלְיוֹנִין, דְּקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתְּבַּח בְּהוּ, דִּכְתִּיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִרְשׁוּ אֶרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר.</p>"],[9520011796,"<p>(שמות כ״ז:י׳) וָוִי הָעַמּוּדִים וַחֲשֻׁקֵיהֶם כָּסֶף. רַבִּי יִצְחָק אָמַר, וָוִי הָעַמּוּדִים, הָא אֲמֵינָא כָּל אִינּוּן דְּמִתְאַחֲדָן מִקִּטְרֵי קַיָּימִין עִלָּאִין, אִקְרוּן וָוִי הָעַמּוּדִים. וְכָל אִינּוּן דִּלְתַתָּא, תַּלְיָין מֵאִינּוּן וָוִים. מַאי ווִים. שִׁתָא בְּגוֹ שִׁתָא, וּמִתְאַחֲדָן וּמִתְשַׁקְיָין מִחוּטָא דְּשִׁדְרָה, דְּקָאִים עָלַיְיהוּ. וּבְסִפְרָא דִּצְנִיעוּתָא תָּאנָא, וָוִים לְעֵילָּא, וָוִים לְתַתָּא, וְכֻלְּהוּ בְּמַתְקְלָא חַד סַלְּקִין.</p>"],[9520011797,"<p><Noneb>ספרא דצניעותא</b> מַאן צְנִיעוּתָא דְּסִפְרָא. אָמַר רִבִּי שִׁמְעוֹן, חֲמִשָׁה פִּרְקִין אִינּוּן דְּכְלִילָן בְּהֵיכָל רַב, וּמַלְיָין כָּל אַרְעָא. אָמַר רִבִּי יְהוּדָה, אִי כְּלִילָן הָנֵי, מִכֻּלְּהוּ עֲדִיפֵי. אָמַר רִבִּי שִׁמְעוֹן, הָכִי הוּא, לְמַאן דְּעָאל וְנָפַק, וּלְמָאן דְּלָא עָאל ונָפַק לָאו הָכִי.</p>\n<p>מַתְלָא, לְבַר נָשׁ דְּהֲוָה דִּיוּרֵיהּ בֵּינֵי טוּרִין, וְלָא יָדַע בְּדִּיוּרֵי מָתָא. זָרַע חִטִּין. וְאָכִיל חִטֵּי בְּגוּפַיְיהוּ. יוֹמָא חַד עָאל לְמָתָא, אַקְרִיבוּ לֵיהּ נַהֲמָא טָבָא. אֲמַר הַהוּא בַּר נָשׁ, דְּנָא לָמָּה. אֲמַרוּ נַהֲמָא הוּא לְמֵיכַל. אָכַל וְטָעַם לְחָדָא לְחִכֵּיהּ. אֲמַר וּמִמָּה אִתְעָבִיד דָּא. אֲמַרוּ מֵחִטִין. לְבָתַר אַקְרִיבוּ לֵיהּ גְּרִיצִין דְּלִישִׁין בְּמִשְׁחָא. טָעַם מִנַּיְיהוּ, אֲמַר וְאִלֵּין מִמַּה אִתְעֲבִידוּ. אֲמַרוּ מֵחִטִין. לְבָתַר אַקְרִיבוּ לֵיהּ טְרִיקֵי מַלְכִין, דְּלִישִׁין בְּדּוּבְשָׁא וּמִשְׁחָא. אֲמַר וְאִלֵּין מִמַּה אִתְעָבִידוּ. אֲמַרוּ מֵחִטִין. אֲמַר וַדַּאי אֲנָא מָארֵי דְּכָל אִלֵּין, דַּאֲנָא אָכִיל עִקָּרָא דְּכָל אִלֵּין דְּאִיהוּ חִטָּה. בְּגִין <Nonei></i>הַהוּא דַּעְתָּא מֵעִדוּנֵי עָלְמָא לָא יָדַע וְאִתְאֲבִידוּ מִנֵּיהּ. כַּךְ, מַאן דְּנָקִיט כְּלָלָא, וְלָא יָדַע בְּכֻלְּהוּ עִדוּנִין דִּמְהַנְיָין, דְּנַפְקִין מֵהַהוּא כְּלָלָא.</p>"],[9520011798,"<p><Noneb>ספרא דצניעותא פרקא קדמאה</b> תָּאנָא. סִפְרָא דְּצְנִיעוּתָא, סִפְרָא, דְּשָׁקִיל (רל\"ה ע\"א) בְּמַתְקְלָא. (תאנא) דְּעַד דְּלָא הֲוָה מַתְקְלָא, לָא הֲווֹ מַשְׁגִּיחִין אַפִּין בְּאַפִּין, וּמַלְכִין קַדְמָאִין מִיתוּ, וְזִיוּנֵיהוֹן לָא אִשְׁתַּכְּחוּ, וְאַרְעָא אִתְבַּטְּלָת.</p>\n<p>עַד דְּרֵישָׁא דְּכִסּוּפָא דְּכָל כִּסוּפִין, לְבוּשֵׁי דִּיקָר אַתְקִין, וְאַחֲסִין.</p>\n<p>הַאי מַתְקְלָא תָּלֵי בַּאֲתַר דְּלָא הֲוָה, אִתְּקָלוּ בֵּיהּ אִינּוּן דְּלָא אִשְׁתַּכְּחוּ. מַתְקְלָא קָאִים בְּגוּפֵיהּ. לָא אִתְאֲחָד, וְלָא אִתְחָזֵי. בֵּיהּ סְלִיקוּ, וּבֵיהּ סָלְקִין דְּלָא הֲווֹ, וַהֲווּ, וְיְהוְיָּין.</p>\n<p>סִתְרָא גּוֹ סִתְרָא, אִתְתְּקָּן ואִזְדְּמַן, (אד\"ר קכ\"ח ע\"ב, באד\"ז רפ\"ז, רפ\"ח ע\"א) בְּחַד גּוּלְגַלְתָּא, מַלְיָיא טַלָּא דִּבְדוֹלְחָא. (שם אד\"ר קכ\"ט) קְרוּמָא דְּאַוִּירָא אִזְדָּכָךְ וְסָתִים, אִינּוּן עֲמָר נְקֵי תַּלְיָין בְּשִּׁקוּלָא. רַעֲוָא (אד\"ז שם) דְּרַעֲוִין אִתְגַּלְיָא בִּצְלוֹתָא דְּתַתָּאֵי. אַשְׁגָּחָא פְּקִיחָא דְּלָא נָאִים, וְנָטִיר תְּדִירָא. אַשְׁגָּחוּתָא דְּתַתָּא בְּאַשְׁגָּחוּתָא דִּנְהִירוּ דְּעִלָּאָה. (דביה) תְּרִין נוּקְבִין דְּפַרְדַּשְׂקָא, דְּאִתְּעַר רוּחָא לְכֹלָּא.</p>\n<p>בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, שִׁיתָא בְּרֵאשִׁית (ברא שית) עָלַיְיהוּ, כּוּלְהוּ לְתַתָּא, וְתַלְיָין מִשִּׁבְעָה דְּגּוּלְגְלָתָא עַד יְקִירוּ דְּיַקִירוּתָא, וְהָאָרֶץ תִּנְיָינָא לָאו בְּחוּשְׁבָּן וְהָא אִתְּמַר. וּמֵהַהִיא דְּאִתְלַטְּיָיא נָפְקָא, דְּכְתִּיב (בראשית ה׳:כ״ט) מִן הָאֲדָמָה אֲשֶׁר אֵרַרָה יְיָ'. הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ עַל פְּנֵי תְּהוֹם וְרוּחַ אֱלהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם. תְּלֵיסַר, תַּלְיָין בִּתְלֵיסָר יְקִירוּ דְּיַקִירוּתָא.</p>\n<p>שִׁיתָא אַלְפֵי שְׁנִין, תַּלְיָין בְּשִׁיתָא קַדְמָאֵי, שְׁבִיעָאָה עָלַיְיהוּ, דְּאִתְתָּקַּף בִּלְחוֹדוֹי. וְאִתְחָרִיב כֹּלָּא בִּתְרֵיסַר שַׁעְתֵּי, דְּכְתִּיב הָיְתָה תֹהוּ וָבֹהוּ וְגוֹ'. תְּלֵיסַר יְקִים לוֹן בְּרַחֲמֵי, וּמִתְחַדְּשָׁן בְּקַדְמִיתָא, וְקָמוּ (ס\"י קמו) כָּל אִינּוּן שִׁיתָא. בְּגִין דְּכְתִּיב בָּרָא, וּלְבָתַר כְּתִיב הָיְתָה, דְּהָא הֲוַת וַדַּאי, וּלְבַסּוֹף תֹהוּ וָבֹהוּ וְחֹשֶׁךְ, (ישעיהו ב׳:י״א) וְנִשְׂגַּב יְיָ' לְבַדּוֹ בְּיוֹם הַהוּא.</p>\n<p>גִּלוּפֵי דִּגְלִיפִין כְּחֵיזוּ דְּחִוְיָא אָרִיךְ, וּמִתְפָּשַּׁט לְכָאן וּלְכָאן, זַנְבָא בְּרֵישָׁא. רֵישָׁא (אחורא) אָחִיד אַכַתְפִין, אַעְבַּר וְזָעִים, נְטַר וְגָנִיז. חַד לְאֶלֶף יוֹמִין זְעִירִין אִתְגָּלְיָיא, (נ\"א אתמלייא) קוּלְטְרָא בְּקִטְרוֹי, סְנַפִּירָא בְּעַדְבוֹי, אִתְבַּר רֵישֵׁיהּ בְּמַיִין דְיַמָּא רַבָּא, דְּכְתִּיב (תהילים ע״ד:י״ג) שִׁבַּרְתָּ רָאשֵׁי תַּנִּינִים עַל הַמָּיִם. תְּרֵין הֲווֹ, חַד אִתְחֲזָרֵי, (ל\"ד ע\"ב) תַּנִּינָם כְּתִיב חָסֵר. רָאשֵׁי, כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ.</p>\n<p>וַיֹּאמֶר אֱלהִים יְהִי אוֹר וַיְהִי אוֹר, הַיְינוּ דְּכְתִּיב (תהלים לג) כִּי הוּא אָמַר וַיֶּהִי, הוּא בִּלְחוֹדוֹי. לְבָתַר אִתְחַזְרוּ חַד יהו\"י יה\"ו ו\"י ו' בַּתְרָאָה שְׁכִינְתָּא לְתַתָּא. כְּמָה דְּה' שְׁכִינְתָּא אִשְׁתְּכַח וּבְחַד מַתְקְלָא אִתְּקָלוּ.</p>\n<p>וְהַחַיּוֹת רָצוֹא וָשׁוֹב, דְּכְתִּיב וַיַּרְא אֱלהִים אֶת הָאוֹר כִּי טוֹב. (ישעיהו ג׳:י׳) אִמְרוּ צַדִּיק כִּי טוֹב. הַאי, בְּמַתְקְלֵּיה סַלְּקָא. קַדְמָאָה בִּלְחוֹדוֹי. וְכֹלָּא לְחָד אִתְחֲזְרֵי. אֲחַתָא וּמוֹדַעְתָּא כְּלִילָן דָּא בְּדָא בְּיו\"ד הֵ\"א, כִּתְרֵין רְחִימִין דְּמִתְחַבְּקָן.</p>\n<p>שִׁיתָא נָפְקִין מֵעַנְפָא דְּשָׁרְשָׁא דְּגוּפָא, לִישָׁן מְמַלֵּל רַבְרְבָן. לִישָׁן דָּא, סָתִים בֵּין יוֹ\"ד וְהֵ\"א, דְּכְתִּיב (ישעיהו מ״ד:ה׳) זֶה יֹאמַר לַה' אָנִי וְזֶה יִקְרָא בְּשֵׁם יַעֲקֹב וְזֶה יִכְתּוֹב יָדוֹ לַיְיָ' וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה (יכנה) מַמָּשׁ. זֶה יֹאמַר לַה' אָנִי: אֲחַתָא. וְכֹלָּא אִתְּמַר בְּיה\"ו. כֹּלָּא כְּלִילָן בְּלִישָׁן סָתִים לְאִימָא. דְּהָא אִתְפַּתְּחַת לֵיהּ דְּנָפִיק מִינָּהּ. אַבָּא יָתִיב בְּרֵישָׁא, אִימָא בְּאֶמְצָעִיתָא, וּמִתְכַּסְיָּיא מִכָּאן וּמִכָּאן וַוי לְמַאן דְּגַלֵּי עֲרָיַיתְהוֹן.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, שַׁלִּיט דְּכַר בְּנוּקְבָא. (ס\"י שלימו דכר ונוקבא) דְּכְתִּיב (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם, נָהִיר יוֹ\"ד בִּתְרֵין, וְנָהִיר וּמְעָבַּר לְנוּקְבָא. אִתְיְיחָד יוֹ\"ד בִּלְחוֹדוֹי, (ובתר כן) סָלִיק בְּדַרְגּוֹי לְעֵילָּא לְעֵילָּא. אִתְחַשְׁכָא נוּקְבָּא, וְאִתְנְהִירַת אִימָא וּמִתְפַּתְּחָא <Nonei></i>בְּתַרְעוֹי. אָתָא מַפְתְּחָא דְּכָלִיל בְּשִׁית, וּמְכַסְיָא פִּתְחָהָא, וְאָחִיד לְתַתָּא לְהַאי וּלְהַאי, ווי לְמַאן דְּגַלֵּי פִּתְחָהָא.</p>"]]});
